window.PF_DATA_races = {"meta":{"category":"races","count":56,"generatedAt":"2026-11-19T19:04:01Z","source":"https://pathfinder.family"},"races":[{"adventurers":"Аасимары часто становятся искателями приключений, поскольку они часто чувствуют себя не в своей тарелке в обществе и ощущают притяжение какого-то великого предназначения. Жрецы, оракулы и паладины наиболее многочисленны в их рядах, хотя барды, колдуны и призыватели также не редкость среди тех аасимар, кто любит мистическую магию. Варвары-аасимары редки, но, родившись в варварских племенах, они часто становятся их лидерами и продвигают использование небесных тотемов в своих племенах.","alignmentAndReligion":"Аасимары чаще всего придерживаются доброго мировоззрения, хотя это и не обязательно, и аасимары, которые повернулись спиной к праведности, могут упасть в бездонную пропасть пороков. И всё же по большей части аасимары отдают предпочтение божествам чести, доблести, защиты, исцеления и покровительства или простой и банальной вере в дом, общину и семью. Некоторые также следуют путями искусства, музыки и сказаний, находя истину и мудрость в красоте и познании.","altTraits":[{"description":"Некоторые аасимары следуют своему предназначению воевать против сил абсолютного зла. Они получают бонус +1 (интуитивный) к броскам атаки и к КБ против злых потусторонних существ и расовый бонус +2 к Знаниям (планы) и проверке Колдовства для идентификации злых потусторонних существ, предметов или эффектов, созданных злыми потусторонними существами; они могут использовать навыки без рангов для этих целей.","name":"Небесный крестоносец","related":["Небесная устойчивость","Умелый"]},{"description":"Многие аасимары чувствуют себя обязанными пытаться защищать мир от демонов. Эти аасимары получают расовый бонус +2 при проверке уровня заклинателя, чтобы преодолеть устойчивость к заклинаниям, и при проверке Знаний (планы).","name":"Крестоносная магия","related":["Псевдозаклинание","Умелый"]},{"description":"Особенно волевые аасимары обладают небесным духом, способным противостоять силам смерти. Они получают сопротивление 5 к повреждению негативной энергией. Они не теряют очки жизни, когда получают отрицательный уровень, и они получают расовый бонус +2 к испытаниям против эффектов смерти, Вытягивания жизни (Energy drain), негативной энергии и заклинаний или псевдозаклинаний школы некромантии.","name":"Бессмертный дух","related":["Небесная устойчивость"]},{"description":"Аасимар с этой чертой народа получает устойчивость к магии (УкМ), равную 5 + УЗ, против заклинаний и псевдозаклинаний с дескриптором «зло», а также любых заклинаний и псевдозаклинаний, применяемых злыми потусторонними существами.","name":"Возвышенная сопротивляемость","related":["Небесная устойчивость"]},{"description":"Некоторые аасимары обладают способностью создавать ореолы. Аасимар с этой расовой чертой может по желанию создавать свет, исходящий из его головы, в качестве псевдозаклинания. При использовании своего ореола он получает бонус +2 (обстоятельства) при проверке Устрашения против злых существ и при испытаниях против ослепления.","name":"Ореол","related":["Ночное зрение"]},{"description":"Аасимары с этой чертой народа получают бонус +2 к проверкам Знаний (планы) и творят заклинания с дескриптором \"добро\" или \"свет\" с УЗ +1.","name":"Рожденный небом","related":["Псевдозаклинание","Умелый"]},{"description":"Аасимары с этой чертой народа бросают вызов силам смерти. Они получают бонус +2 к проверке Знаний (история) и испытаниям против эффектов смерти и могут использовать низшую Сопротивляемость возрасту (Age resistance) один раз в день в качестве псевдозаклинания.","name":"Бессмертная искра","related":["Псевдозаклинание","Умелый"]},{"description":"Иногда появляются аасимары, обладающие более сильной способностью отгонять зло. Аасимары с этой чертой народа могут использовать Сопротивление разврату (Corruption resistance) против зла один раз в день в качестве псевдозаклинания. Если аасимар использует эту способность на себе, продолжительность увеличивается до 1 часа за уровень.","name":"Неподкупный","related":["Псевдозаклинание"]},{"description":"В то время как многие рассматривают красоту и небесную силу аасимаров как дар, в некоторых сообществах аасимар может подвергнуться преследованиям за то, что он отличается от других, и он погружается во тьму. Силы зла наслаждаются таким извращением даров своих небесных собратьев. До тех пор, пока аасимар сохраняет злое мировоззрение, он приобретает альтернативную черту народа тифлинга \"пасть (maw)\" или \"коготь (claw)\".","name":"Утраченное обещание","related":["Псевдозаклинание"]},{"description":"Небесное наследие некоторых аасимаров чрезвычайно отдалено. Аасимар с этой расовой чертой считается потусторонним существом (местный) и гуманоидом (человек) для любого эффекта, связанного с расой, включая требования для черт и заклинаний, влияющих на гуманоидов. Он может сойти за человека, не используя навык Маскировки.","name":"Отпрыск человечества","related":["Языки"]},{"description":"Есть некоторые аасимары, чьи знания языков превосходит все границы. Они получают бонус +2 к Языкознанию и Проницательности, а также изучают два языка каждый раз, когда получают ранг Языкознания.","name":"Несущий истину","related":["Умелый"]}],"book":"Advanced Race Guide","description":"Аасимары - люди, в чьих венах течёт кровь небожителей или других добрых потусторонних существ. Аасимары не всегда добры, но творить добро - их естественная потребность, поэтому они обычно предпочитают служить добрым богам или вступать в связанные с небожителями организации. Аасимарское происхождение может не проявляться на протяжении поколений, а потом у двух обычных людей может внезапно появиться столь необычный ребёнок. Большинство народов считают рождение аасимара благим знамением, но некоторые аасимары пользуются репутацией своего народа, внезапно подрывая ожидания ужасающей жестокостью и вопиющей порочностью. “Всегда побеждает тот, кого ты меньше всего подозреваешь” - вот аксиома, которой придерживаются эти злые аасимары, и они часто ведут двойную жизнь как добропорядочные граждане или псевдогерои, хорошо скрывая свое истинное лицо. К счастью, эти немногие являются исключением, а не правилом.","favoredClass":[{"alias":"bard","description":"Выберите одно выступление барда; при определении эффектов этого выступления считайте, что бард на +1/6 уровня выше.","name":"Бард"},{"alias":"cleric","description":"добавляет +1/2 к урону при использовании положительной энергии против нежити или при использовании черты Проводник Мировоззрения (Alignment Channel) для нанесения урона злым потусторонним существам.","name":"Жрец"},{"alias":"inquisitor","description":"Добавляет +1/2 к проверкам Запугивания, Знаний и Проницательности, проводимым против потусторонних существ.","name":"Инквизитор"},{"alias":"cavalier","description":"Добавляет +1/4 к бонусу урона кавалериста, наносимого целям его вызова.","name":"Кавалерист"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"oracle","description":"Добавляет +1/6 к уровню оракула с целью определения эффектов одного откровения.","name":"Оракул"},{"alias":"paladin","description":"Добавляет +1/6 к бонусу морального духа к испытаниям, обеспечиваемым аурами паладина.","name":"Паладин"},{"alias":"summoner","description":"Добавьте СУ 1/зло к Эйдолону. Каждый дополнительный раз, когда призыватель выбирает это преимущество, СУ/зло увеличивается на +1/2 (максимум СУ 10/зло).","name":"Призыватель"},{"alias":"sorcerer","description":"Добавляет +1/4 к уровню заклинателя чародея при произнесении заклинаний с дескриптором «добро».","name":"Чародей"}],"kind":"race","nameEn":"Aasimar","nameRu":"Аасимар","names":[{"isMale":true,"name":"Аритиан"},{"isMale":true,"name":"Белтинг"},{"isMale":true,"name":"Сернан"},{"isMale":true,"name":"Кронвир"},{"isMale":true,"name":"Эран"},{"isMale":true,"name":"Иламин"},{"isMale":true,"name":"Модрил"},{"isMale":true,"name":"Окрин"},{"isMale":true,"name":"Парант"},{"isMale":true,"name":"Турал"},{"isMale":true,"name":"Вайран"},{"isMale":true,"name":"Зайган"},{"isMale":false,"name":"Аркен"},{"isMale":false,"name":"Арсиноя"},{"isMale":false,"name":"Давина"},{"isMale":false,"name":"Дринма"},{"isMale":false,"name":"Имеса"},{"isMale":false,"name":"Масози"},{"isMale":false,"name":"Ниджена"},{"isMale":false,"name":"Нирамур"},{"isMale":false,"name":"Ондреа"},{"isMale":false,"name":"Риалла"},{"isMale":false,"name":"Валтира"}],"physicalDescription":"Аасимары выглядят практически неотличимо от людей, за исключением незначительных особенностей внешности, выдающих необычное происхождение: металлический блеск волос, необычный цвет глаз или оттенок кожи, а порой - излучающий золотистое сияние нимб.","relations":"Аасимары наиболее распространены и чувствуют себя наиболее комфортно в человеческих сообществах. Это чаще справедливо в отношении тех, чья родословная наиболее «тусклая» и кто несет лишь слабые следы своего небесного происхождения. Неясно, почему прикосновение небожителей ощущается в человечестве гораздо сильнее, чем в других расах, вероятно, присущая человечеству адаптивность и склонность к переменам является причиной эволюции аасимаров как отдельной расы. Возможно, свойственные другим расам черты слишком глубоко укоренились и слишком устойчивы к изменениям. Какие бы интрижки ни были у других рас с обитателями верхних планов, потомства от таких связей крайне мало и они редко бывают способны размножаться. Однако, даже если они в основном тяготеют к человеческому обществу, аасимары могут чувствовать себя комфортно практически в любой среде. Они обладают непринужденной манерой общения и обезоруживающе привлекательны. Они хорошо ладят с полуэльфами, которые разделяют аналогичный, не совсем человеческий, статус маргиналов, но их отношения с полуорками часто менее дружелюбны, так как те терпеть не могут чрезмерно красивые слова и лица аасимаров. Эльфийский двор иногда отвергает аасимаров как незамысловатых и порицает их за то, что они полагаются на врожденное обаяние, а не добиваются уважения вопреки ему. Возможно, из всех известных рас гномы находят аасимаров наиболее очаровательными и высоко ценят их разнообразную внешность, а также магию, окружающую их небесное наследие.","slug":"aasimar","society":"Нельзя сказать, что у аасимаров действительно есть собственное независимое общество. Они, как часть человечества, перенимают окружающие их социальные нормы, хотя большинство из них тяготеют к тем сторонам общества, которые работают над устранением несправедливости и облегчением страданий. Это иногда ставит их по другую сторону закона в тиранических обществах, но аасимары могут быть осторожными и хитрыми, когда это необходимо, способными притворяться, чтобы не привлекать внимание угнетателей. В то время как порочные аасимары могут быть одиночками или создавать тайные общества, чтобы скрыть свою причастность к преступлениям, праведных же аасимаров часто можно встретить в большом количестве в составе добропорядочных организаций, особенно (хотя и не всегда) церквей и религиозных орденов.","traits":[{"description":"+2 Харизма, +2 Мудрость. Аасимары догадливы, уверенны и обаятельны.","name":"Модификаторы характеристик"},{"description":"Потустороннее существо (подтип Местные).","name":"Тип"},{"description":"Средний.","name":"Размер"},{"description":"30 футов.","name":"Базовая скорость"},{"description":"Аасимары начинают игру со знанием всеобщего и небесного языков. Аасимары с высоким значением Интеллекта могут выбрать дополнительные языки из следующего списка: гномий, дварфийский, драконий, полуросличий, сильван, эльфийский.","name":"Языки"},{"description":"Аасимары получают устойчивость к кислоте 5, устойчивость к холоду 5, устойчивость к электричеству 5.","name":"Небесная устойчивость"},{"description":"Аасимары получают +2 (народ) к проверкам Внимательности и Дипломатии.","name":"Умелый"},{"description":"Аасимары могут раз в день сотворить псевдозаклинание дневной свет (daylight) (УЗ равен уровню персонажа).","name":"Псевдозаклинание"},{"description":"Аасимары могут видеть в темноте на расстоянии до 60 футов.","name":"Ночное зрение"}]},{"alignmentAndReligion":"Обычно нейтральное.","book":"Bestiary 5","description":"Технологичные создания известные как андройды обладают почти абсолютным сходством с людьми. Хотя они и не люди большинство андройдов живущих среди людей скрывают свою природу и ведут себя так, как будто они реальные люди. Сложность в понимании и имитировании эмоций может раскрыть их, поэтому большинство из них тщательно изучают окружающих, чтобы обеспечить себе надежную маскировку. Они не рождаются, их создают и приходят они в этот мир будучи взрослыми по внешнему виду. Чужеродные кузни, где создаются андройды скрыты от любопытных глаз среди загадочных руин и ни один андройд не помнит как он пришел в этот мир, ровно как и не помнит место своего «рождения».","favoredClass":[{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"}],"kind":"race","nameEn":"Android","nameRu":"Андройд","physicalDescription":"Эта стройная женщина облдает странной резкой грацией. Ее бледная плоть покрыта сложным узором синих татуировок. Обычно андройдов создают ростом под 2 метра и весом под 90 кг.","slug":"android","traits":[{"description":"Андройды используют уровни в классах - КЗ народа у них нет.","name":""},{"description":"У андройдов очень быстрые рефлексы и они очень умны, но им крайне сложно понимать окружающих.","name":"+2 к Ловкости, +2 к Интеллекту, -2 к Харизме"},{"description":"Андройды видят в темноте на расстоянии 60 футов, а также видят при тусклом освещении, также получают расовый бонус +2 к Вниманию.","name":"Сверхчувствительность"},{"description":"Андройд считается одновременно как гуманойд и конструкция (например, при определении заклятых врагов следопыта). Андройды получают расовый бонус +4 к проверкам против эффектов воздействующих на разум, паралича, оглушения, яда. Oни не подвержены усталости или истощению и наделены иммунитетом к болезням и эффектам сна.","name":"Конструированный"},{"description":"Андройд никогда не получает бонусов к морали и обладает иммунитетом к страху и эмоциональным эффектам. У них проблемы с выражением эмоций и также они наделены штрафом -4 к Проницательности.","name":"Безэмоциональный"},{"description":"Тело андройда наполнено множеством нанитов. Раз в день в качестве быстрого действия Андройд может вызвать в себе всплеск нанитовой энергии и получить бонус равный 3 + уровень персонажа к любому броску d20 (данная способность должна быть акивирована до начала броска). При использовании этой способности татуировки на теле андройда начинают светиться (эффект освещения приравнивается к факелу) в течении 1 раунда.","name":"Нанитовый скачок"},{"description":"Андройды начинают игру со знанием языков: общий. Андройды с высоким показателем Интеллекта могут выбрать любой дополнительный язык за исключения священных языков, например как язык друидов.","name":"Языки"}]},{"adventurers":"Большинство афоритов, независимо от культуры, в которой они выросли, со временем испытывают стремление увидеть мир за пределами места своего рождения. По выбору или случайно, афориты кажутся предрасположенными к жизни искателя приключений. Всегда стремясь лучше понять не только мир, но и самих себя, афориты превосходны, когда попадают в ситуации, где их интеллект может проявиться. Будучи одновременно хитрыми и сильными по своей природе, афориты тяготеют к классам, сочетающим в себе искусство заклинаний и боя, таким как колдун или жрец войны.","alignmentAndReligion":"Хотя не все афориты по своей сути законны, большинство из них наслаждаются структурой и порядком в своей жизни. Однако идеи морали менее четко сводятся к афоритам. Хотя большинство могут оценить научные исследования философии добра и зла и признать различия между ними, этот разрыв не влияет на них в такой степени, как структура закона в сравнении с неорганизованным безумием хаоса. Следовательно, большинство афоритов принципиальные нейтральные. Обычно афориты, обращенные к богословию, выбирают в качестве покровителей принципиальных богов, причем поклонение Абадару, в частности, перекликается с присущими им желаниями и целями построения идеального общества. Когда афорита охватывает хаос, другие афориты часто относятся к своим своенравным собратьям со смесью любопытства, ужаса и жалости. Сами хаотические афориты, как правило, одиночки и мало интересуются традициями своего рода, вместо этого ищут присоединения к другим обществам.","book":"Planar Adventures","description":"Основными жителями идеального города Оси является народ, известный как аксиомиты, потусторонние существа, рожденные принципиальными нейтральными душами, чья основная цель - служить Оси одним из трех способов: создание и уход за неизбежным, расширение и поддержание самого города, а также исследование и расчет законов и констант, лежащих в основе всей реальности, в надежде использовать эти знания для наведения порядка в Великом Запределье. Но аксиомиты плохо подходят для взаимодействия со смертными. Как существам чистого порядка, им трудно иметь дело с существами, имеющими свободную волю выбирать свою судьбу и интерпретировать (или даже сознательно игнорировать) законы. Древние аксиомиты долго обдумывали решение проблемных встреч с посетителями с Материального Плана. Ответом, к которому они пришли, было создание новой формы жизни - слияние их собственного совершенства порядка с непредсказуемыми и хрупкими телами и разумами смертных гуманоидов. Так появились первые афориты. Хотя этим женщинам и мужчинам всегда были рады в Оси, идеальный город не был их настоящим домом. Наполненные искрой смертности и влиянием Материального Плана, афориты были созданы, чтобы служить дипломатами, переводчиками и посланниками между аксиомитами и бесчисленными культурами бесчисленных миров Материального Плана. Будучи местными потусторонними существами, афориты обладают собственной свободной волей, и они живут и умирают так же, как и другие смертные. Хотя афориты во многом схожи с другими местными потусторонними существами, такими как аасимары, ганзи и тифлинги, они отличаются тем, что они не являются результатом союза между потусторонними существами и смертными.","favoredClass":[{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"}],"kind":"race","nameEn":"Aphorite","nameRu":"Афорит","physicalDescription":"В то время как первоначальная популяция была создана в Оси аксиомитами, от родителей-афоритов рождаются новые афориты. В случаях, когда у афорита и гуманоида рождается ребенок, потомство становится либо новорожденным афоритом, либо представителем народа гуманоидного родителя. Первоначально афориты были созданы почти одинакового внешнего вида, но они изменились в результате поколений, проведенных на Материальном Плане. Сегодня афорит всегда имеет гуманоидную форму с золотистой кожей, которая мерцает и периодически блистает сверкающей кристаллической пылью, а также глазами и волосами, имеющими металлические оттенки (обычными цветами являются медь, золото и серебро). Помимо этого, они могут выглядеть похожими на дварфов, эльфов, людей или любой другой средний гуманоидный народ. Наследие неизменного порядка Оси долгое время препятствовало образованию афоритов других размеров, но исключения происходят всё чаще по мере того, как на Материальном Плане рождается каждое новое поколение афоритов.","relations":"Умные и сильные, афориты могут стать как объектом внимания и восхищения, так и жертвами ревности и ненависти. Их упорядоченные и структурированные личности часто вызывают напряженные отношения с более капризными или озорными соседями и могут быть источником конфликта с культурами, которые высоко ценят индивидуальное выражение мысли, например, с эльфами. Народы с более сильными тенденциями к закону обычно создают более прочные связи с афоритами. Дварфам особенно нравится компания афоритов, и они находят рождение афорита среди себе подобных желанным событием, поскольку афориты имеют интуитивное понимание ремесла, столь неотъемлемого для дварфийского общества.","slug":"aphorite","society":"Афориты не встречаются в больших количествах на большинстве миров Материального Плана, и Голарион не является исключением. Первые афориты, прибывшие на Голарион, не стремились утвердить свой собственный народ как отдельный культурный элемент, а вместо этого ассимилировались с устоявшимися обществами, чтобы помочь в формировании законов и поддержать потенциальное взаимодействие с гражданами Оси. Но по мере распространения народа афоритов произошло то, чего следовало предвидеть аксиомитам: будучи местными потусторонними существами, способными выбирать свою судьбу, многие афориты были заинтригованы обществами, в которых они жили. Есть некоторые ограничения на принятие новых обществ; афориты, принимающие хаос, считаются среди своих родственников изгоями и нарушителями спокойствия, несмотря на то, что эти афориты являются естественным выражением определяющих характеристик смертных.","traits":[{"description":"Афориты используют уровни в классах - КЗ народа у них нет.","name":""},{"description":"Афориты сильны и сообразительны, но двигаются и реагируют несколько скованно.","name":"+2 Сила, +2 Интеллект, -2 Ловкость"},{"description":"Афориты - потусторонние существа с подтипом местный.","name":"Местное потустороннее существо (Native Outsider)"},{"description":"Афориты - существа среднего размера, что не даёт им никаких бонусов или штрафов.","name":"Средний размер (Medium)"},{"description":"Базовая скорость афоритов - 30 футов.","name":"Нормальная скорость (Normal Speed)"},{"description":"Афориты видят в темноте на 60 футов.","name":"Ночное зрение (Darkvision)"},{"description":"Афориты получают +2 (народ) к проверкам навыка одного Ремесла по своему выбору.","name":"Умелый (Skilled)"},{"description":"Афориты могут использовать защиту от хаоса один раз в день в качестве псевдозаклинания (уровень заклинателя равен классовому уровню афорита).","name":"Псевдозаклинание (Spell-Like Ability)"},{"description":"У афоритов есть устойчивость к электричеству 5 и +2 к испытаниям против яда и эффектов, воздействующих на разум.","name":"Устойчивости афоритов (Aphorite Resistances) (Экс)"},{"description":"Афорит может создавать дымку кристаллической пыли, которая превращается в нечёткие руны и глифы, окружающие его тело. Этот эффект даёт афориту 20% шанс промаха против атак ближнего и дальнего боя. Активация этой пыли - сопутствующее действие, но её можно поддерживать каждый раунд в качестве свободного действия. Эффект не может быть прерван, но немедленно прекращается, если афорит убит, парализован, в шоке, потерял сознание или иным образом лишён возможности совершать свободное действие для его поддержания в каждом раунде. Афорит может использовать эту способность количество раундов в день, равное его КЗ, но раунды не обязательно должны идти подряд.","name":"Кристаллическая пыль (Crystalline Dust) (Св)"},{"description":"Афориты начинают игру со знанием всеобщего и либо небесного, либо дьявольского языков. Афориты с высоким значением Интеллекта могут выбрать дополнительные языки из следующего списка: акван, ауран, демонический, дьявольский, игнан, небесный или терран.","name":"Языки (Languages)"}]},{"alignmentAndReligion":"Обычно нейтральное.","book":"Bestiary 5","description":"Эти загадочные существа не нуждаются в пище, да что там - у них и рта то нет, вдобавок у них отсутствуют глаза, которые позволяли бы им исследовать окружающий мир. Вместо этого они полагаются на свой мощный разум, способный давать им ощущения пространства вокруг, питаясь различными веществами из воздуха. Правда это может сыграть с ними злую шутку, поскольку сильные запахи и яды в воздухе могут привести их в беспомощное состояние. Аскетичны по натуре, предпочитают носить обычные тряпки вместо одежды, если вообще что-то носят.","favoredClass":[{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"}],"kind":"race","nameEn":"Astamoi","nameRu":"Астомой","physicalDescription":"Из ниоткуда появился гуманойд, сотворенный будто из самой тьмы, не обладавший ни ртом, ни носом, ни ушами, ни глазами.","slug":"astamoi","traits":[{"description":"Астромои используют уровни в классах - КЗ народа у них нет.","name":""},{"description":"Астомои всегда идут по пути просветления, остро ощущая мир своей психикой, однако их хрупкие тела очень восприимчивы к опасностям которые могут их окружать.","name":"+2 к Интеллекту, +2 к Мудрости, -2 к Выносливости"},{"description":"Астомои средние по размеру существа не имеющие бонусы и штрафы по габаритам.","name":"Средний"},{"description":"Астомои имеют базовую скорость 30 футов.","name":"Обычная скорость"},{"description":"Нюх является уникальной чертой расы.","name":"Нюх"},{"description":"Астомой не может говорить или видеть, но он способен ментально ощущать мир в пределах 60 футов (как черта ночное зрение) и может общаться используя телепатию. Астомой не видит ничего далее чем 60 футов. Астомой может заменять словесные компоненты заклятий, проговаривая их мысленно. Астомой может использовать различные возможности связанные с языковой речью (компенсируя это телепатией) но не в том случае, когда цель должна именно слышать словесные компоненты.","name":"Телепатия"},{"description":"Астомой получает штраф -2 к спасброскам против болезней и вдыхаемых ядов.","name":"Чувствительное дыхание"},{"description":"Астомой не имеет рта и не нуждается в еде и воде, хотя он может абсорбировать разумом саму сущность пищи, лишая ее при этом всяческих полезных свойств для других, словно она уже съедена. Использование зелий и прочих материалов работает в том же ключе. При этом учитывая, что фактически они ничего не глотают на них не действуют проглатываемые яды.","name":"Безротый"},{"description":"Астомой начинают игру со знанием языка: общий (поскольку они не имеют рта они могут общаться телепатически на расстоянии 100 футов). Астомой с высоким показателем Интеллекта могут выбрать следующие языки: абиссал, акло, небесный, эльфийский, гномий, инфернал, сильван.","name":"Языки"}]},{"adventurers":"Большинство искателей приключений калиньи становятся плутами и убийцами, перенимая опыт своих собратьев - темных проныр и темных охотников. Некоторые становятся алхимиками, а самые порочные общаются с ойбами как чародеи и призыватели.","alignmentAndReligion":"Обычно хаотчное нейтральное.","book":"Bestiary 5","description":"Название \"калиньи\" является древним термином для рас, которые в настоящее время в обществе известны как темный народ, в отдельных случаях еще используется название «сообщество темного народа» при обращении к самим себе. Многие поколения назад эти подземные жители стремились к великим судьбам и могли бы достичь их, если бы не запланированное дегенерация, назначенная извне их регуляторами ойбами. Тем не менее, даже сегодня, темный народ иногда рождается, имея поразительное сходство с древними, которое имитируют темные охотники. Возвращаясь к тому времени до вмешательства ойбов, такой индивид – называемый просто «калиньи» - может родиться от любой рассы темного народа, как напоминае этим людям о полузабытых мечтах. Рождение калиньи – это знаменательный знак, отмечаемый многими темными народами. Часто врослеющий калиньи ставит под угрозу кланы темного народа или задевает регулятора ойба; в результате большинство калиньи не доживают до взрослой жизни в обществе темного народа, становясь жертвой подозрительных несчастных случаев или таинственных убийств. Самые хитрые калиньи предвидят предательство своего народа и уходят, ища пристанища где-нибудь в темных землях и используя таланты, которые они узнали среди других темных народов, на собственной службе или менее коварным союзникам.","favoredClass":[{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"}],"kind":"race","nameEn":"Caligni","nameRu":"Калиньи","physicalDescription":"Под рваными клочьями бледная кожа этой худой фигуры темнеет, приобретая обугленный оттенок на конечностях. Калиньи достигают около 6 футов в высоту, но весят всего 125 фунтов. Их часто принимают за темных охотников, хотя их особенности более определены и индивидуально отличительны под их толстыми оболочками. Их кожа отбелено-серая, углубленно затемнена на конечностях. Калиньи стареют с такой же скоростью как и полуэльфы, и обычно не порождают чистокровное поколение, вместо этого рождаются более распространенные темные народы – типичные темные существа.","slug":"caligni","traits":[{"description":"Калиньи используют уровни в классах - КЗ народа у них нет.","name":""},{"description":"Калиньи быстры и выносливы, но поколение в изоляции и угнетении сделали их конервативными, чтобы принять новое веяние.","name":"+2 Ловкость, +2 Выносливость, -2 Интеллект"},{"description":"Калиньи имеют базовую скорость 30 футов.","name":"Нормальная скорость"},{"description":"калиньи прекрасно видят в любой тьме, даже созданной заклинанием кромешная тьма.","name":"Темновидение (Св)"},{"description":"Калиньи ослеплены в области яркого света.","name":"Светочувствительность"},{"description":"Когда Калиньи убит, его тело сгорает во вспышке обжигающего света. Все живые существа в пределах 5-ти футов озаряются вспышкой, должны успешно пройти проверку сохранения стойкости (СЛ = 10 + 1/2 КЗ Калиньи + модификатор Выносливости Калиньи) или будут ослеплены на 1d4 раундов. Труп, оставшийся после – треть размера Калиньи, иссохший и неузнаваемый как человек. Возвращение к жизни и похожие заклинания, используемые на эти останки Калиньи восстанавливают как обычно.","name":"Предсмертная агония (Св)"}]},{"adventurers":"Прирожденные следопыты, охотники-собиратели - это подталкивает любого кошколюда к становлению следопытами и друидами по умолчанию, но такие роли не всегда говорят об их любви к исполнительскому искусству, будь то песня, танец или рассказывание историй. Легенды кошколюдов также говорят о богатой традиции великих героев-чародеев. Те кошколюды, которые принимают свою страсть к путешествиям, часто становятся волшебниками и монахами, и многие из этих монахов идут по пути ловкого стража. В то время как кавалеристы и инквизиторы кошколюдов редки (стойкая преданность делу часто чужда менталитету кошколюдов), но на кошколюдов, которые выбирают эти пути, никогда не смотрят свысока. Кошколюды понимают, что исследование и самопознание могут вести по многим дорогам, и принимают почти все профессии и способы жизни.","alignmentAndReligion":"С сообществом и бескорыстным сотрудничеством в основе их культуры, а также добродушным любопытством и готовностью адаптироваться к обычаям многих других рас, большинство кошколюдей склонны к доброму мировоззрению. Подавляющее большинство кошколюдей также хаотичны, поскольку мудрость не является их сильнейшей добродетелью; тем не менее, есть исключения по некоторым причинам. Боги Дезна, Кайден Кайлин и Шелин общаются с душами кошколюдей, и многие племена изображают последних двоих как себе подобных кошколюдей. Стремление к самосовершенствованию привело многих из них к изучению различных философий, включая поклонение Ирори.","book":"Advanced Race Guide","description":"Кошколюды - это раса исследователей природы, которые редко устают открывать новые горизонты, но такие новаторские идеи не ограничиваются только поиском новых горизонтов в далеких странах. Многие кошколюды рассматривают личностный рост и развитие как равнозначные пути исследования. Хотя большинство представителей этой расы шустрые, способные и часто активные существа, среди них прослеживается сильная тенденция к тихому созерцанию и учебе. Такие кошколюды заинтересованы в поиске новых решений давних проблем и в сомнении даже в самых стойких философских установках того времени. Они любопытны по своей природе, а культура кошачьего народа никогда не препятствует любознательности, а скорее поощряет и награждает ее. Многих из них представители других рас считают причудливыми экстравертами, но племена кошколюдов не стыдятся незначительных особенностей, эксцентричности или безрассудства. Всем кошколюдам, кроме наиболее сосредоточенных на себе, нравится быть в центре внимания, но не за счет своего племени, будь то племя, в котором они родились, или племя, которое они выбрали по узами дружбы с другими существами. Кошколюды, как правило, щедры и преданы своей семье и друзьям.","favoredClass":[{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"shaman","description":"Добавьте 1/6 к уровню класса шамана для определения эффектов одного наговора.","name":"Шаман"}],"kind":"race","nameEn":"Catfolk","nameRu":"Кошколюд","physicalDescription":"В общих чертах, кошколюды гибкие и стройные, по росту они между дварфами и людьми. Несмотря на то, что они явно гуманоиды, они обладают многими кошачьими чертами, включая шерсть из мягкого тонкого меха, узкие зрачки и гладкий, тонкий хвост. Уши у них заостренные, но в отличие от ушей эльфов более округлые и кошачьи. Они манипулируют объектами так же легко, как и другие гуманоиды, но их пальцы заканчиваются маленькими острыми выдвижными когтями. Эти когти, как правило, недостаточно сильны, чтобы их можно было использовать в качестве оружия, но некоторые представители этого вида - по причуде рождения или многолетнему оттачиванию - могут использовать их со смертельным эффектом. Усы кошек не редкость, но не универсальны, а цвет волос и глаз сильно различается.","relations":"Приспосабливающиеся и любопытные, кошки ладят практически с любой расой, которая проявляет взаимную доброжелательность. Они легко адаптируются к полуросликам, людям и особенно эльфам. Кошки и эльфы разделяют страстный характер, а также любовь к музыке, танцам и рассказыванию историй; эльфийские общины часто нежно наставляют племена кошколюдов, хотя такие эльфы осторожны, чтобы не проявлять покровительство по отношению к своим друзьям-кошкам. Гномы - естественные компаньоны для кошколюдов, поскольку кошколюды наслаждаются странными и навязчивыми качествами гномов. Кошки терпимы к кобольдам, пока рептилии уважают границы кошачьего народа. Дикий характер орков вызывает у кошколюдов столько же недоумения, сколько и отвращение, поскольку они не понимают жестокости орков и их склонности к самоуничтожению. С другой стороны, полуорки интригуют кошколюдов, особенно те полуорки, которые стремятся превзойти вредоносную и ненавистную природу своих диких сородичей. Кошколюды часто считают гоблинов и крысолюдей паразитами, поскольку они презирают подобные скопления и пагубные наклонности этих рас.","slug":"catfolk","society":"Хотя самовыражение является важным аспектом кошачьей культуры, оно смягчается сильным чувством сообщества и коллективных усилий. В дикой природе кошачий народ - это племенной народ охотников-собирателей. Стремление к личной власти никогда не предшествует здоровью и благополучию племени. Многие народы недооценивали этих, казалось бы, мягкосердечных существ, но позже обнаруживала, что их сплоченность также дает им большую силу. Кошколюды предпочитают, чтобы их возглавляли наиболее компетентные члены, обычно совет подчиненных вождей, выбранный их сверстниками, либо путем консенсуса, либо путем выборов. Затем подчиненные выбирают вождя, который будет руководить во время опасности и урегулировать споры между подчиненными. Вождь - самый способный член племени и часто обладает магическими способностями. Кошколюды, которые поселяются в более городских и цивилизованных районах, по-прежнему придерживаются аналогичной племенной структуры, но часто видят друзей вне племени, даже из других рас, как часть своего расширенного племени. В группах приключенцев кошколюд, который не считает себя наиболее подходящим выбором в качестве вождя, часто подчиняется человеку, который больше всего напоминает их культурный идеал вождя.","traits":[{"description":"Кошколюды используют уровни в классах - КЗ народа у них нет.","name":""},{"description":"Кошколюды проворны и дружелюбны, но известны отсутствием здравого смысла и самоконтроля.","name":"+2 к Ловкости, +2 к Харизме, -2 к Мудрости"},{"description":"Кошколюды являются гуманоидами с подтипом кошколюд.","name":"Кошколюд"},{"description":"Кошколюды - существа среднего размера, что не дает им никаких бонусов или штрафов.","name":"Размер"},{"description":"Базовая скорость кошколюдов - 30 футов.","name":"Нормальная скорость"},{"description":"Кошколюды видят в сумерках вдвое дальше людей.","name":"Сумеречное зрение"},{"description":"Один раз в день, когда кошколюд проходит испытание Реакции, он может совершить бросок дважды и выбрать лучший результат. Он должен решить использовать эту способность перед попыткой испытания.","name":"Кошачья удача (Cat's Luck) (Экс)"},{"description":"Кошколюды получают +2 (народ) к проверкам Внимания, Скрытности и Выживания.","name":"Природный охотник"},{"description":"Кошколюд получает 10-футовый бонус (народ) к своей скорости при использовании действий атаки с разбега, бега или отступления.","name":"Спринтер (Sprinter)"},{"description":"Кошколюды начинают игру, говоря на общем и кошколюдском. Кошколюды с высоким уровнем Интеллекта могут выбирать из следующих языков: эльфийский, гноллский, гномий, гоблинский, полуросличий, орочий и сильван.","name":"Языки"}]},{"alignmentAndReligion":"Обычно принципиальное нейтральное.","book":"Bestiary 4","description":"Само их рождение загадка. Выращенные ничего не знающими родителями, подменыши - дети Карг и их обманутых любовников. Большинство не знают об их чудовищном происхождении, но наступает время в жизни каждого подменыша, когда их темное происхождение начинает давать о себе знать, побуждая запутанную девушку к таким вещам, которые она не в силах понять. Когда карга любого типа вступает в связь с мужчиной, результатом их кошмарного соития всегда будет подменыш. Отец будет убит и съеден прежде, чем он увидит потомство. Подменыши всегда рождаются девочками, и все без исключения вырастают высокими и стройными. Волосы у подменыша обычно длинные и темные, а ее кожа аномально бледная, но, так или иначе, для остальных она выглядит как представитель народа своего отца. Частая, но не универсальная черта у подменыша это разный цвет глаз, один из которого совпадает с распространённым цветом глаз народа отца. По достижении зрелости подменыш, рожденный от человека, достигает роста примерно 5-6 футов и весит около 110 фунтов.","favoredClass":[{"alias":"witch","description":"Добавьте одно заклинание из списка заклинаний ведьмы к фамильяру ведьмы. Это заклинание должно быть как минимум на один уровень ниже самого высокого уровня заклинания, которое она может использовать. Если ведьма заменит своего фамильяра, новый фамильяр будет знать эти дополнительные заклинания.","name":"Ведьма"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"}],"kind":"race","nameEn":"Changeling","nameRu":"Подменыш","physicalDescription":"Кожа этой стройной неестественно бледна, волосы ее черны как крыло ворона, а каждый глаз имеет свой цвет.","slug":"changeling","traits":[{"description":"Подменыши используют уровни в классах - КЗ народа у них нет.","name":""},{"description":"Подменыши хрупкие, но умные и миловидные","name":"-2 к Выносливости, +2 к Мудрости, +2 к Харизме"},{"description":"Подменыш обладает одним из следующих штрихов в зависимости от того какая карга была ее матерь); Громадный подменыш (Черная карга): Подменыш получает расовый бонус +1 к урону наносимому в ближнем бою. Зеленая вдова (Болотная карга): Подменыш получает расовый бонус +2 к Блефу против существ, которые сексуально привлекают ее. Морские легкие (Морская карга): Подменыш может задерживать дыхание под водой на число раундов, равное 3 х показатель Выносливости, прежде чем она рискует утонуть.","name":"Штрих карги"},{"description":"Руки и ногти подменыша крепнут и становятся острее, наделяя хозяйку двумя атаками когтями, каждая из которых наносит 1d4 урона.","name":"Когти"},{"description":"Подменыши обладают бонусом +1 к естественной броне.","name":"Естественная броня"},{"description":"Подменыши видят в темноте на расстоянии 60 футов.","name":"Ночное зрение"},{"description":"Подменыши начинают игру со знанием общего языка и основного языка народа их отца. Подменыши с высоким показателем Интеллекта могут выбрать следующие языки: акло, драконий, дварфийский, эльфийский, великаний, гнолльский, гоблинский и орочий.","name":"Языки"}]},{"alignmentAndReligion":"Обычно хаотчное злое.","book":"Bestiary 5","description":"Глубинный гибрид – это порождение людей и глубинных. Они наиболее комфортно чувствуют себя с другими представителями своего вида и обычно объединяются в небольшие, изолированные поселения, где они могут занять авторитетную позицию. Они держат всех людей в своих городах подчиненными и запуганными, убедившись, что эти жители знают, что так лучше, чем действовать против местных законов. Несмотря на то, что глубинные гибриды глубоко религиозны, они обычно скрывают свою истинную веру под видимостью более традиционного поклонения, полагая, что таким образом они могут избежать подозрений со стороны гостей и соседних обществ.","favoredClass":[{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"}],"kind":"race","nameEn":"Deep one hybrid","nameRu":"Глубинный гибрид","physicalDescription":"Широкое горло, разинутый рот, вытаращенные глаза и перепончатые руки этого старика наводят на мысль о зловещей примеси в его родословной.","slug":"deepOneHybrid","traits":[{"description":"Глубинные гибриды используют уровни в классах - КЗ народа у них нет.","name":""},{"description":"Глубинные гибриды сердечны и набожны, но как правило отчасти их движения медленные и неуклюжие.","name":"+2 Выносливость, +2 Мудрость, -2 Ловкость"},{"description":"Базовая скорость глубинных гибридов составляет 20 футов, поскольку они ходят с шаркающей походкой.","name":"Медленный"},{"description":"Глубинные гибриды видят в сумерках вдвое дальше людей.","name":"Сумеречное зрение"},{"description":"толстая кожа глубинных гибридов и плотные жировые ткани дают им +1 естественный бонус брони к КБ.","name":"Естественная броня"},{"description":"Глубинный гибрид стареет с той же скоростью, что и полуорк. Всего через 1d12 месяцев после того, как глубинный гибрид достигает почтенного возраста (в 60 лет), он умирает болезненной, мучительной смертью, только чтобы его тело превратилось в зрелого глубинного. Эта трансформация функционирует как заклинание реинкарнации, с вновь сформированным глубинным, который получает следующие изменения в его характеристиках физических способностей: +6 Сила, -2 Ловкость и +6 Выносливость.","name":"Окончательное изменение (Св)"},{"description":"Каждые 24 часа проведенные глубинным гибридом на территории более чем в 10 милях от моря, он должен пройти проверку Воли со СЛ 20 или потерять 1 очко Мудрости вытягиванием.","name":"Морская тоска (Экс)"},{"description":"Глубинный гибрид может задерживать дыхание в 10 раз дольше, чем человек, и получает бонус +2 на проверки инициативы и реакции во время плавания. Глубинный гибрид имеет скорость плавания 30 футов и получает расовый бонус +8 на всех проверках Плавания.","name":"Соприкосновение с водой (Экс)"},{"description":"Глубинные гибриды начинают играть, говоря на акло и общем. Гибриды с высокими показателями Интеллекта могут выбирать из следующих языков: абиссал, водный, дварфийский, эльфийский, великаний, гномий, гоблинский, полуросличий, орочий, и подземный.","name":"Языки"}]},{"adventurers":"Жизнь авантюриста естественна для большинства дампиров, поскольку постоянные преследования вынуждают многих проводить свои дни в странствиях. Злые дампиры продолжают передвигаться, чтобы сохранить свою тайну и уклоняться от линчевателей, в то время как те, кто следуют путем мести, отправляются на поиски своих презираемых отцов. Независимо от причин, большинство дампиров просто чувствуют себя в дороге как дома, нежели в поселении. Не имея формального образования, многие из этих путешественников становятся бойцами и разбойниками. Почти повсеместно те, кто склонен к магии, занимаются некромантией, хотя известно, что дампирские алхимики одержимы трансформацией своего тела. Те, кто чувствует зов охоты, часто становятся инквизиторами.","alignmentAndReligion":"Большинство дампиров поддаются злу в своей крови. Они сверхестественные существа, и отвратительное влияние их загробного наследия затрудняет преодоление зла. Те, кто борется со своей порочной природой, редко продвигаются дальше нейтрального мировоззрения. Дампиры, которые становятся охотниками на вампиров, склонны поклоняться Саренрей или Фаразме, в зависимости от их моральной позиции. Те, кто впал во зло и принял свое загробное наследие, обычно поклоняются повелителю демонов Зуре, Королеве вампиров, или Ургатоа, богине нежити.","book":"Advanced Race Guide","description":"Полуживые дети вампиров, рожденные человеческими женщинами, дампиры - потомки ужаса и трагедии. Обстоятельства зачатия дампира часто ставятся под сомнение, но их почти не понимают, поскольку немногие смертные матери выживают после родов. Те, кто выживают, часто бросают своих чудовищных детей и отказываются говорить об этом. В то время как некоторые предполагают, что дампиры возникают, когда смертные женщины спариваются с вампирами, другие утверждают, что они образуются, когда беременную женщину кусает вампир. Некоторые особенно ревностные ученые даже оспаривают статус дампиров как уникальной расы, вместо этого рассматривая их как людей, страдающих от нечестивых пристрастий. В самом деле, эта гипотеза подкрепляется кажущейся неспособностью дампиров к размножению, их потомство неизбежно является людьми (обычно чародеями с загробным наследием). Несмотря на это, они живут и умирают, как и любые другие смертные существа, несмотря на то, что обладают сверхъестественным долголетием, схожим с эльфийским. Трудности и страдания заполняют годы становления дампира. Большинство из них вырастают сиротами, и, несмотря на свои изысканные черты лица и врожденное обаяние, они всю жизнь сталкиваются с предрассудками, недоверием, страхом и преследованием. Люди, которые становятся свидетелями кажущейся зловещей природы сверхъестественных способностей ребенка-дампира или его чувствительности к дневному свету, демонстрируют множество реакций, от страха и ужаса до открытой ненависти. В конце концов, дампир должен научиться справляться с этими трудностями, чтобы найти свое место в мире. В то время как большинство дампиров поддаются врожденному злу своей неживой половины и превращаются в чудовищных демонов, подтверждая предубеждения общества, некоторые отвергают свои нечестивые корни, вместо этого клятвенно клянутся отомстить за своих матерей, охотясь на тех самых существ, которые их породили. У дампиров мало близких товарищей, если они вообще есть. В конце концов, большинство злых дампиров считают своих союзников не более чем инструментами или кормом. О тех, кого они считают полезными, судят по их личным достоинствам, а не по расе. Однако даже с теми, к кому они привязаны, большинство дампиров угрюмы и сдержанны. Некоторые опасаются, что преследование, обрушившееся на них, может затрагивать и их товарищей, в то время как другие опасаются, что однажды их собственная кровожадность овладеет ими, и они непреднамеренно обратятся к своим друзьям. В любом случае союз с дампиром почти всегда приводит к злополучному исходу.","favoredClass":[{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"}],"kind":"race","nameEn":"Dhampir","nameRu":"Дампир","physicalDescription":"Высокие, стройные, с хорошо выраженной мускулатурой дампиры выглядят статными людьми неземной красоты. Их цвет волос, глаз и кожи напоминает пугающую версию цветов, которые были у их матерей; у многих из них ужасная бледность, особенно на солнце, а у смуглых людей кожа с синеватым оттенком. В то время как многие дампиры в подходящих условиях могут выглядеть людьми, их черты неизбежно более выражены, и они двигаются с неестественно плавной грацией. У всех дампиров удлиненные резцы. Хотя это и не настоящие клыки, эти зубы достаточно острые, чтобы пролить кровь, и многие страдают от предосудительного желания предаться кровавым наслаждениям, несмотря на то, что это действие практически не приносит физической пользы.","slug":"dhampir","society":"У дампиров нет собственной культуры, и у них нет никаких известных земель или даже общин. Часто тайно рожденные и брошенные в приютах или умирать на окраине города, они, как правило, ведут уединенную жизнь в качестве изгнанников и изгоев. Они приобретают культурные верования и учения тех регионов, в которых они выросли, и усваивают дополнительные философские взгляды в течение своей сложной жизни. Эта способность приспосабливаться к истинным обстоятельствам дает дампирам социальную маскировку, скрывающую их как от хищников, так и от добычи. В редких случаях дампиры могут собираться в небольшие группы или кланы, посвященные решению их общих проблем. Даже в этом случае философия таких групп отражает интересы вовлеченных людей, а не какую-либо общую дампирскую культуру.","traits":[{"description":"Дампиры быстры и соблазнительны, но их расовая связь с нежитью препятствует их живой энергии.","name":"+2 к Ловкости, +2 к Харизме, -2 к Выносливости"},{"description":"Дампиры являются гуманоидами с подтипом дампир.","name":"Дампир"},{"description":"Дампиры - существа среднего размера, что не дает им никаких бонусов или штрафов.","name":"Размер"},{"description":"Базовая скорость дампиров - 30 футов.","name":"Нормальная скорость"},{"description":"Сумеречное зрение и ночное зрение на 60 футов.","name":"Чувства"},{"description":"+2 бонус (народ) к Блефу и Вниманию.","name":"Манипулятор"},{"description":"Дампиры получают бонус +2 (народ) к испытаниям против болезней и влияющих на разум эффектов.","name":"Сопротивление нежити"},{"description":"Дампир становится растерянным в зоне яркого солнечного света или заклинания дневной свет.","name":"Чувствительность к свету"},{"description":"Хотя дампиры - живые существа, они реагируют на позитивную и негативную энергию, как если бы были нежитью. Позитивная энергия наносит им вред, а негативная - лечит.","name":"Сродство к негативной энергии"},{"description":"Дампир может использовать обнаружение нежити три раза в день как псевдозаклинание. Уровень заклинателя для этой способности равен уровню класса дампира.","name":"Псевдозаклинание"},{"description":"Дампир не получает штрафов от эффектов вытягивания жизни, но он может умереть, если получит больше отрицательных уровней, чем у него костей здоровья. Через 24 часа все полученные дампиром отрицательные уровни исчезают без дополнительных испытаний.","name":"Устойчивость к вытягиванию жизни (Экс)"},{"description":"Дампиры начинают играть, говоря на общем. Те, у кого высокий уровень Интеллекта, могут выбрать любой язык по своему усмотрению (кроме секретных языков, таких как друидический).","name":"Языки"}]},{"alignmentAndReligion":"Обычно хаотичное злое.","book":"Bestiary 1","description":"Хоть дроу и состоят с эльфами в родстве, их в лучшем случае можно считать злыми и подлыми дальними родственниками. Эти хитрые существа, иногда называемые тёмными эльфами, обитают в пещерах и тоннелях глубоко под землёй, где правят огромными городами при помощи силы и страха. Дроу поклоняются демонам и порабощают большинство встреченных народов, поэтому мало кого из подземных обитателей боятся и ненавидят так же сильно, как их. Дроу ниже и стройнее обычных эльфов, но в остальном их телосложение мало отличается. У дроу тёмная кожа, чей цвет варьируется от чёрного до дымчато-лилового. У большинства дроу белые или серебристые волосы, а глаза белые или красные, хотя встречаются и другие цвета. Общество дроу управляется высокорожденными, а они, в свою очередь, находятся под пятой жестоких и опасных матриархов, которые постоянно плетут интриги и стараются уничтожить соперников как в других благородных домах, так и в собственной семье. Большая часть дроу - обычные солдаты и горожане (их параметры и представлены выше), но высокорожденные более сильны и опасны и подробно описаны на следующей странице. В бою дроу абсолютно беспощадны и сражаются без намёка на честь и жалость. Они предпочитают нападать из засады или заманить противника в место, где будут иметь явное преимущество. Если что-то пойдёт не так, дроу немедленно сбегут, оставив рабов и приспешников прикрывать отступление.","favoredClass":[{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"}],"kind":"race","nameEn":"Drow","nameRu":"Дроу","physicalDescription":"Эта темнокожая эльфийка приготовилась к бою. У неё серебристые волосы, а глаза абсолютно белые и лишены зрачков.","slug":"drow","traits":[{"description":"Дроу используют уровни в классах - КЗ народа у них нет.","name":""},{"description":"Дроу подвижны и хитры.","name":"+2 Ловкость, +2 Харизма, -2 Выносливость"},{"description":"Дроу - существа среднего размера и не получают ни бонусов, ни штрафов.","name":"Средний размер"},{"description":"Базовая скорость дроу - 30 футов.","name":"Нормальная скорость"},{"description":"Дроу могут видеть в темноте на расстоянии до 120 футов.","name":"Ночное зрение"},{"description":"Дроу невосприимчивы к эффектам магического сна и получают +2 (народ) к испытаниям против заклинаний школы очарования.","name":"Невосприимчивость дроу"},{"description":"Дроу получают +2 (народ) к проверкам Внимания.","name":"Острые чувства"},{"description":"Дроу обладают УкМ, равной числу их уровней в классах + 6.","name":"Устойчивость к магии"},{"description":"Дроу могут по разу в день сотворить псевдозаклинания пляшущие огоньки, тьма и фейское сияние. УЗ для них равен уровню персонажа.","name":"Псевдозаклинания"},{"description":"Кратковременный яркий свет ослепляет дроу на 1 раунд, в последующих раундах на ярком свету дроу становится растерянным до тех пор, пока не покинет ярко освещённую область.","name":"Световая слепота"},{"description":"Дроу умеют обращаться с ядами и не могут случайно отравить себя. Они предпочитают особый токсин, вызывающий потерю сознания, - это позволяет захватывать рабов без особых усилий. Яд дроу - ранение; Испытание: Стойкости со СЛ 13; Частота: 1/минута до 2 минут; Первичное действие: потеря сознания на 1 минуту; Вторичное действие: потеря сознания на 2d4 часа; Лечение: 1 испытание.","name":"Специалист по ядам"},{"description":"Дроу умеют обращаться с ручным арбалетом, рапирой и коротким мечом.","name":"Оружие дроу"},{"description":"Дроу начинают игру со знанием эльфийского и подземного языков. Дроу с высоким значением Интеллекта могут выбрать дополнительные языки из следующего списка: акван, акло, всеобщий, гномий, гоблинский, демонический, драконий, язык жестов дроу.","name":"Языки"}]},{"alignmentAndReligion":"Обычно хаотичное злое.","book":"Bestiary 1","description":"Хоть дроу и состоят с эльфами в родстве, их в лучшем случае можно считать злыми и подлыми дальними родственниками. Эти хитрые существа, иногда называемые тёмными эльфами, обитают в пещерах и тоннелях глубоко под землёй, где правят огромными городами при помощи силы и страха. Дроу поклоняются демонам и порабощают большинство встреченных народов, поэтому мало кого из подземных обитателей боятся и ненавидят так же сильно, как их. Дроу ниже и стройнее обычных эльфов, но в остальном их телосложение мало отличается. У дроу тёмная кожа, чей цвет варьируется от чёрного до дымчато-лилового. У большинства дроу белые или серебристые волосы, а глаза белые или красные, хотя встречаются и другие цвета. Общество дроу управляется высокорожденными, а они, в свою очередь, находятся под пятой жестоких и опасных матриархов, которые постоянно плетут интриги и стараются уничтожить соперников как в других благородных домах, так и в собственной семье. Большая часть дроу - обычные солдаты и горожане (их параметры и представлены выше), но высокорожденные более сильны и опасны и подробно описаны на следующей странице. В бою дроу абсолютно беспощадны и сражаются без намёка на честь и жалость. Они предпочитают нападать из засады или заманить противника в место, где будут иметь явное преимущество. Если что-то пойдёт не так, дроу немедленно сбегут, оставив рабов и приспешников прикрывать отступление. Примерно один из 20 дроу рождается с особым даром, но подавляющее большинство этих исключительных дроу - женщины, что объясняет матриархат в их обществе. Рождение исключительных дроу можно спланировать, и это поощряется среди правящей верхушки - чаще всего высокорожденный дроу рождается у высокорожденной матери. Интересен тот факт, что вероятность рождения особенного ребёнка никак не зависит от отца. Обычные дети, рождённые в семьях высокорожденных, как правило, приносятся в жертву одному из многочисленных демонических богов, которым поклоняются дроу. У обычных родителей редко рождается особый ребёнок, но если это происходит, он зачастую убивает своих родителей или семью до своего совершеннолетия, стараясь скрыть правду о своём происхождении, чтобы облегчить процесс вхождения в один из благородных домов. Высокорождённые дроу гораздо могущественнее большинства своих сородичей и поэтому быстро приходят к власти в своём доме. Продвижение в иерархии благородного дома обычно достигается различными комбинациями убийств, обольщения и предательства, отчего власть имущие зачастую подозрительны сверх меры.","favoredClass":[{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"}],"kind":"race","nameEn":"Drow Noble","nameRu":"Высокорожденный дроу","physicalDescription":"Эта темнокожая эльфийка приготовилась к бою. У неё серебристые волосы, а глаза абсолютно белые и лишены зрачков.","slug":"drowNoble","traits":[{"description":"Высокорожденные дроу используют уровни в классах - КЗ народа у них нет.","name":""},{"description":"Высокорожденные дроу крайне ловки, наблюдательны и величественны.","name":"+4 Ловкость, +2 Интеллект, +2 Мудрость, +2 Харизма, -2 Выносливость"},{"description":"Дроу - существа среднего размера и не получают ни бонусов, ни штрафов.","name":"Средний размер"},{"description":"Базовая скорость дроу - 30 футов.","name":"Нормальная скорость"},{"description":"Дроу могут видеть в темноте на расстоянии до 120 футов.","name":"Ночное зрение"},{"description":"Дроу невосприимчивы к эффектам магического сна и получают +2 (народ) к испытаниям против заклинаний школы очарования.","name":"Невосприимчивость дроу"},{"description":"Дроу получают +2 (народ) к проверкам Внимания.","name":"Острые чувства"},{"description":"Высокорожденные дроу обладают УкМ, равной числу их уровней в классах + 11.","name":"Устойчивость к магии"},{"description":"Высокорожденные дроу могут неограниченно творить псевдозаклинания кромешная тьма, левитация, плавное падение, пляшущие огоньки, фейское сияние, а также обнаружение магии в качестве постоянного псевдозаклинания. Они могут по разу в день сотворить внушение, милость божества и рассеивание магии. В некоторых случаях набор псевдозаклинаний высокорожденного дроу может отличаться, но их круг остаётся неизменным. УЗ для них равен уровню персонажа.","name":"Псевдозаклинания"},{"description":"Кратковременный яркий свет ослепляет дроу на 1 раунд, в последующих раундах на ярком свету дроу становится растерянным до тех пор, пока не покинет ярко освещённую область.","name":"Световая слепота"},{"description":"Дроу умеют обращаться с ядами и не могут случайно отравить себя. Они предпочитают особый токсин, вызывающий потерю сознания, - это позволяет захватывать рабов без особых усилий. Яд дроу - ранение; Испытание: Стойкости со СЛ 13; Частота: 1/минута до 2 минут; Первичное действие: потеря сознания на 1 минуту; Вторичное действие: потеря сознания на 2d4 часа; Лечение: 1 испытание.","name":"Специалист по ядам"},{"description":"Дроу умеют обращаться с ручным арбалетом, рапирой и коротким мечом.","name":"Оружие дроу"},{"description":"Дроу начинают игру со знанием эльфийского и подземного языков. Дроу с высоким значением Интеллекта могут выбрать дополнительные языки из следующего списка: акван, акло, всеобщий, гномий, гоблинский, демонический, драконий, язык жестов дроу.","name":"Языки"}]},{"alignmentAndReligion":"Обычно принципиальное злое.","book":"Bestiary 1","description":"Двергары - родственники дварфов, отличающиеся скверным характером и отвращением ко всем, кто пожалует в их подземные королевства, но гораздо более сильную ненависть они питают к дварфам, живущим ближе к поверхности. Двергары обитают общинами глубоко под землёй и представляют собой мрачные, искажённые отражения своих более добрых сородичей. Их кожа тёмно-серая, как будто бы в неё втирали пыль или пепел. Это её естественный цвет, позволяющий двергарам не выделяться на фоне окружающей обстановки. Двергары - народ рабовладельцев, но если обычным пленникам уготован тяжёлый труд, то дварфов, угодивших в плен, убивают сразу же. В бою двергары издалека стреляют из арбалетов, а через несколько раундов берут в руки боевой молот. Если противник превосходит числом или слишком опасен (и если есть достаточно места), двергар применит увеличение гуманоида и перейдёт в наступление.","favoredClass":[{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"}],"kind":"race","nameEn":"Duergar","nameRu":"Двергар","physicalDescription":"У этого лысого длиннобородого дварфа тёмно-серая кожа, насупленные брови и глаза, которые, похоже, поглощают, а не отражают свет.","slug":"duergar","traits":[{"description":"Двергары используют уровни в классах - КЗ народа у них нет.","name":""},{"description":"Двергары крепки и наблюдательны, но упрямы и воинственны.","name":"+2 Выносливость, +2 Мудрость, -4 Харизма"},{"description":"Базовая скорость двергаров - 20 футов, но она не снижается из-за доспехов или нагрузки.","name":"Медленно, но верно"},{"description":"Двергары могут видеть в темноте на расстоянии до 120 футов.","name":"Ночное зрение"},{"description":"Двергары невосприимчивы к параличу, фантазмам и ядам. Они получают +2 (народ) к испытаниям против заклинаний и псевдозаклинаний.","name":"Невосприимчивость двергаров"},{"description":"Стоя на твёрдой почве, двергар получает +4 (народ) к ЗБМ против тарана или сбивания с ног.","name":"Непоколебимость"},{"description":"Двергары могут по разу в день сотворить псевдозаклинания невидимость и увеличение гуманоида. Оба эти псевдозаклинания двергар может сотворить только на себя. УЗ для них равен уровню персонажа.","name":"Псевдозаклинания"},{"description":"На ярком свету двергар становится растерянным до тех пор, пока не покинет ярко освещённую область.","name":"Светочувствительность"},{"description":"Двергары начинают игру со знанием дварфийского, подземного и всеобщего языков. Двергары с высоким значением Интеллекта могут выбрать дополнительные языки из следующего списка: акло, великаний, гоблинский, драконий, орочий, терран.","name":"Языки"}]},{"adventurers":"Роль сумеречных странников несколько изменилась с началом Эпохи Утраченных пророчеств, когда пророчества не сбылись. До этого времени только души, которым было суждено выполнять роли, служившие интересам Костяного Двора, перевоплощались в сумеречных странников. Однако, когда пророчества оказались в замешательстве, сумеречные странники начали формировать свои собственные судьбы. Некоторые сумеречные странники время от времени встречают или получают сообщения от психопомпов, призывающих их выполнить определенные задачи, но они не обязаны следовать этим указаниям. Тем не менее, из-за своего происхождения, большинство сумеречных странников обладают врождённым уважением к циклам рождения и смерти. Они, как правило, тяготеют к должностям и профессиям, которые позволяют им защищать этот цикл, таким как охотники на нежить, акушерки, гробовщики и священники.","alignmentAndReligion":"Сумеречные странники, как правило, нейтральны, как и сами психопомпы. Те, кто не придерживается нейтрального, склонны к добрым мировоззрениям, а не к злым. Фаразма - самое популярное божество среди сумеречных странников, но Саренрэй и светозарная владыка Ашава также имеют значительное число последователей. Члены растущего контингента злых сумеречных странников полностью отвергают свою врождённую природу, связывая судьбу с сакилами, которые наслаждаются таким извращением. Эти сумеречные странники могут потерять способности, которые помогают им сражаться с нежитью, и получить силы, более подходящие для того, чтобы наводить страх, но такой выбор также имеет шанс изменить их защиту от разложения особенно тревожным образом. Такие сумеречные странники неизбежно обнаруживают, что не только могут стать нежитью, но и что их смерть почти гарантирует некоторую форму неестественной нежизни после смерти, часто возвращаясь в виде привидения без классической неспособности такого существа удаляться от места своей смерти.","book":"Planar Adventures","description":"Первые сумеречные странники появились в результате сделки двух могущественных психопомпов: матери-олетроса и ямараджа. Мать-олетрос выступила за то, чтобы позволить определенным душам, чьи действия помогли сохранить и защитить цикл душ, но чьи жизни были прерваны раньше уготованного судьбой, один раз перевоплотиться, прежде чем предстать перед своим окончательным судом. После долгих дебатов ямарадж согласился, но наложил строгие ограничения на количество сумеречных странников, которые могут существовать одновременно. Всякий раз, когда этот предел достигнут, мертвые сумеречные странники не могут быть возвращены к жизни. Большинство сумеречных странников принимают это ограничение и понимают, что конец их жизни открывает дверь для начала новой жизни. Некоторые просят, чтобы те, кто оплакивает их смерть, в ближайшем будущем также отпраздновали рождение нового сумеречного странника. Время, необходимое для рождения нового сумеречного странника после его смерти, варьируется, но редко превышает год.","favoredClass":[{"alias":"antipaladin","description":"Добавьте 1/2 очка урона к способности антипаладина прикосновение порчи (независимо от того, используется ли она для лечения или нанесения урона).","name":"Антипаладин"},{"alias":"arcanist","description":"Добавьте 1/4 к УЗ арканиста при использовании заклинаний школы некромантии.","name":"Арканист"},{"alias":"bard","description":"Добавьте 1/2 к бонусу эрудиции барда.","name":"Бард"},{"alias":"witch","description":"Добавьте 1/4 к УЗ ведьмы при использовании заклинаний школы некромантии.","name":"Ведьма"},{"alias":"fighter","description":"Добавьте 2 к показателю Выносливости воина с целью определения смерти от отрицательных ПЗ.","name":"Воин"},{"alias":"wizard","description":"Добавьте 1/4 к УЗ волшебника при использовании заклинаний школы некромантии.","name":"Волшебник"},{"alias":"cleric","description":"Добавьте 1/2 очка урона при использовании позитивной энергии против нежити.","name":"Жрец"},{"alias":"kineticist","description":"Увеличьте емкость внутреннего буфера кинетика на 1/6 очка.","name":"Кинетик"},{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"},{"alias":"vigilante","description":"Добавьте 1/4 к штрафу, налагаемому за поразительную внешность, и бонус +1/2 к проверке Запугивания за пугающую внешность.","name":"Линчеватель"},{"alias":"monk","description":"Добавьте 1/4 очка к запасу энергии ци монаха.","name":"Монах"},{"alias":"paladin","description":"Добавьте 1/2 очка к восстанавливаемым ПЗ способности паладина возложение рук (независимо от того, используется ли она для лечения или нанесения урона).","name":"Паладин"},{"alias":"rogue","description":"Плут получает 1/6 нового воровского приёма.","name":"Плут"},{"alias":"skald","description":"Добавьте 1/2 к бонусу эрудиции барда.","name":"Скальд"},{"alias":"investigator","description":"Добавьте бонус +1/3 к броскам вдохновения, применяемым к проверкам Лечения, Знания и Языкознания.","name":"Следователь"},{"alias":"ranger","description":"Добавьте 1/5 к бонусу заклятого врага следопыта против нежити. Чтобы выбрать этот вариант, у следопыта должен быть заклятый враг (нежить).","name":"Следопыт"},{"alias":"spiritualist","description":"Добавьте 1 фут к базовой скорости фантома спиритуалиста. В бою этот вариант не имеет эффекта, если спиритуалист не выберет ее 5 раз (или еще 5 раз).","name":"Спиритуалист"}],"kind":"race","nameEn":"Duskwalker","nameRu":"Сумеречный странник","physicalDescription":"Сумеречные странники - высокие двуногие серокожие существа, связанные с Кладбищем Фаразмы. Они проявляются непосредственно на Материальном Плане, воплощаясь из душ, заслуживших честь второй жизни. Души, ставшие сумеречными странниками, часто выступали в глазах психопомпов хранителями цикла рождения и смерти. За исключением серой кожи, их физические особенности имеют некоторое сходство с теми, которыми они обладали в предыдущих жизнях. Таким образом, типичный сумеречный странник выглядит в основном человеком, если не считать его необычной окраски. Однако сумеречные странники, чьи предки принадлежали к другим народам, могут проявлять характерные черты, такие как заостренные уши, волосатые ноги или даже перья, рога, чешуя или хвосты, хотя они редко проявляются отличного от среднего размера.","relations":"Поскольку сумеречные странники так редки, их немногие существующие сообщества невелики и формируются в основном из индивидуумов, объединённых общей целью, таких как группы охотников на нежить. Многие сумеречные странники проводят всю свою жизнь, так и не встретив другого представителя своего народа. Вместо этого они обычно живут среди тех народов, которые наиболее распространены вблизи кладбищ, на которых они проявились. Сумеречные странники встречают неоднозначную реакцию со стороны человеческих сообществ. Некоторые люди косо смотрят на их пепельную кожу и способ их создания. Другие находят тревожным то, как сумеречные странники относятся к смерти. Сумеречные странники изо всех сил пытаются понять страх и нерешительность, с которыми большинство других народов говорят о смерти, и даже жизнерадостные сумеречные странники склонны к мрачному и болезненному чувству юмора. Однако другие сообщества ценят или даже почитают сумеречных странников за их мудрость, навыки в медицине и умение сражаться с нежитью. Сумеречные странники особенно хорошо ладят с представителями других народов, которые разделяют планарное наследие, такими как аасимары, афориты, ганзи и тифлинги, но испытывают взаимное недоверие с дампирами. Несмотря на предрассудки, с которыми иногда сталкиваются, сумеречные странники, как правило, компанейские, непредубеждённые и принимающие других. Они ищут дружбы и романтических отношений с представителями самых разных народов. Многие сумеречные странники стремятся создать семью и завести детей на определённом этапе жизни. Они увеличивают свои семьи, усыновляя детей из своих сообществ, отдавая особое предпочтение детям, на которых могут не обратить внимание другие потенциальные родители. Однако большинство из них не заинтересованы в сексуальных отношениях, и ни один сумеречный странник не способен выносить или произвести на свет биологических детей.","slug":"duskwalker","society":"Когда рождается сумеречный странник, он спонтанно появляется в священном месте, связанном со смертью, чаще всего на кладбище или в храме. Сумеречные странники не переживают младенчество, а начинают свою жизнь с внешностью и возможностями примерно 8-летнего человеческого ребенка. Эти загадочные дети всегда появляются в простых белых одеждах, с небольшой сумкой с едой и водой по бокам. Дети Сумеречных странников взрослеют с разной скоростью в зависимости от поддержки, которую они получают. Ребенок, принятый в заботливую семью или взятый под опеку храма, взрослеет со скоростью, сходной со скоростью человеческого ребенка, и развивает здоровый баланс между признательностью к жизни и интересом к смерти. Хотя дети-сумеречные странники почти всегда появляются вблизи поселений, необычные обстоятельства их создания иногда приводят к тому, что они подвергаются остракизму до такой степени, что вынуждены постоять за себя. Дети Сумеречных странников, пережившие такие обстоятельства, быстро достигают физической и интеллектуальной зрелости, но им приходится бороться в социальном и эмоциональном плане.","traits":[{"description":"Сумеречные странники проворны и мудры, но их тела хрупки.","name":"+2 Ловкость, -2 Выносливость, +2 Мудрость"},{"description":"Сумеречные странники - потусторонние существа с подтипом местный.","name":"Местное потустороннее существо (Native Outsider)"},{"description":"Сумеречные странники - существа среднего размера, что не даёт им никаких бонусов или штрафов.","name":"Средний размер (Medium)"},{"description":"Базовая скорость сумеречных странников - 30 футов.","name":"Нормальная скорость (Normal Speed)"},{"description":"Сумеречные странники видят в темноте на 60 футов.","name":"Ночное зрение (Darkvision)"},{"description":"Сумеречные странники получают +2 (народ) к проверкам Знания (религия) и Лечения.","name":"Умелый (Skilled)"},{"description":"Сумеречные странники начинают игру со знанием всеобщего и одного из следующих языков: демонического, небесного или дьявольского. Сумеречные странники с высоким значением Интеллекта могут выбрать дополнительные языки из следующего списка: дварфийский, демонический, драконий, дьявольский, небесный, полуросличий, протеанский или эльфийский.","name":"Языки (Languages)"}]},{"adventurers":"Хотя искателей приключений среди дварфов меньше, чем среди людей, их можно встретить в большинстве регионов мира. Дварфы часто покидают пределы своих крепостей, чтобы прославить свой клан, добыть богатства для родного города или отбить у врагов древние дварфийские цитадели. Военная доктрина дварфов делает упор на подземную войну и ближний бой, поэтому большинство из них тяготеет к таким классам, как варвар или воин.","alignmentAndReligion":"Дварфами движут честь и традиции. И хотя их часто изображают замкнутыми, дварфы тонко чувствуют и ценят справедливость и дружбу. Те, кто смог завоевать их доверие, осознают, что дварфы любят не только работать, но и отдыхать, особенно когда есть хороший эль. Мировоззрение большинства дварфов принципиальное доброе. Они предпочитают поклоняться богам, разделяющим их взгляды на жизнь, поэтому чаще всего выбирают Торага, хотя широко распространено также почитание Абадара и Горума.","altTraits":[{"description":"Дварфы умеют проложить свой путь через поле битвы, с легкостью отбрасывая в сторону меньших противников. Дварфы с этим расовым штрихом получают бонус +2 к проверкам Боевых Маневров, сделанным для того, чтобы протаранить или захватить противника. Этот бонус применяется только тогда, когда оба, дварф и его противник стоят на земле.","name":"Неумолимый","related":["Непоколебимость"]},{"description":"Дварфы с этим расовым штрихом росли, выслеживая мерзости, живущие глубоко под поверхностью. Они получают +2 бонус уклонения к КБ против монстров типа аберраций и +2 расовый бонус к их попыткам МБМ захватывать таких существ (или продолжить Захват).","name":"Глубинный Воин","related":["Умение защищаться"]},{"description":"Дварфы долго были в конфликте, с особенно ненавистными им дроу. Дварфы с этим расовым штрихом получают бонус +1 к броскам атаки против существ гуманоидов подтипа эльф.","name":"Древняя Вражда","related":["Ненависть"]},{"description":"Сходство некоторых дварфов с землей дает им большие силы. Дварфы с этим расовым штрихом рассматриваются как на 1 уровень выше, когда разыгрывают заклинания с дескриптором земли или используют предоставленные силы сферы Земли, силы земного наследия и раскрытия тайны камня Оракула. Не дает доступ к новым силам, а только усиливает те, которые дварф мог использовать и без этой способности.","name":"Каменный Певец","related":["Знание камня"]},{"description":"Дварфы известны своим превосходным мастерством, когда дело доходит до металлических и каменных работ. Дварфы с этим расовым штрихом получают расовый бонус +2 на все проверки Ремесла или Профессии, которыми создают объекты из металла или камня.","name":"Мастер","related":["Жадность"]},{"description":"Дварфы известны тем, что они упрямы. Дварфы с этим расовым штрихом получают +2 расовый бонус на испытания, чтобы противостоять заклинаниям и псевдозаклинаниям школ Очарования (Принуждение) и Очарования (Обольщение). Кроме того, если они потерпят неудачу в таком испытании, они получат еще один раунд испытания позже, чтобы преждевременно завершить эффект (при условии, что он имеет длительность, превышающую 1 раунд). Это второе испытание выполняется с тем же СЛ, что и первое. Если у дварфа есть подобная особенность из другого источника (например, скользкий разум плута), он может использовать только одну из этих особенностей за раунд, но может попробовать один во втором раунде, если первая особенность повтора терпит неудачу).","name":"Упрямый","related":["Крепкий"]},{"description":"Дварфы хранят обширные записи об их истории и мире вокруг них. Дварфы с этой чертой черты получают расовый бонус +2 к проверкам навыков Знания (истории), которые относятся к дварфам или их врагам. Они могут сделать такие проверки навыков неподготовленными.","name":"Хранитель Знаний","related":["Жадность"]},{"description":"Некоторые из старых дварфских кланов особенно устойчивы к магии. Дварфы с этим расовым штрихом получают Устойчивость К Магии, равную 5 + уровень их персонажа. Это сопротивление может быть уменьшено на 1 раунд как основное действие. Дварфы с этим расовым штрихом получают -2 штраф за все проверки концентрации, сделанные в отношении мистических заклинаний","name":"Устойчивость К Магии","related":["Крепкий"]}],"book":"Core Rulebook","description":"Дварфы - это работящий и суровый народ, укрывшийся в городах в сердце гор, всегда готовый отбивать атаки окрестных дикарей, будь то орки или гоблины. Больше, чем кто-либо другой, дварфы соответствуют образу угрюмых подземных мастеров. Можно сказать, что сама история дварфов сформировала их мрачный взгляд на жизнь: они населяют высокие горы и подземные царства, постоянно воюя с великанами, гоблинами и прочими напастями.","favoredClass":[{"alias":"barbarian","description":"Добавляет +1 к общему числу раундов ярости в день.","name":"Варвар"},{"alias":"witch","description":"Добавьте +1/4 (естественная броня) к КБ фамильяра ведьмы.","name":"Ведьма"},{"alias":"fighter","description":"+1 к ЗБМ против проверок тарана и сбивания с ног.","name":"Воин"},{"alias":"cleric","description":"Выберите 1 сферу, от которой получаете бонус использования 3 + модификатор Мудрости раз в день и добавьте 1/2 к этому числу использований в день.","name":"Жрец"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"vigilante","description":"Увеличьте бонус от социальной благодати на проверки Ремесла на +1/2.","name":"Линчеватель"},{"alias":"oracle","description":"Уменьшите штрафы за использование оружия, в котором не квалифицированы на 1. Когда штрафы снижаются до 0, считается, что оракул владеет им как экзотическим или воинским оружием.","name":"Оракул"},{"alias":"paladin","description":"Добавьте +1 к проверкам концентрации при использовании заклинаний паладина.","name":"Паладин"},{"alias":"rogue","description":"Добавьте бонус +1/2 к проверкам Механики каменных ловушек и +1/2 к Чутью На Ловушки относительно каменных ловушек.","name":"Плут"},{"alias":"ranger","description":"Добавьте бонус +1/2 бонус к проверкам Понимания Животных с животными и магическими животными, живущими под землей.","name":"Следопыт"},{"alias":"shaman","description":"Добавьте 1/4 бонуса естественной брони для духовного зверя шамана.","name":"Шаман"},{"alias":"shifter","description":"Добавьте 1/2 к результату проверки Понимания животных для улучшения отношения животных или волшебных зверей, обычно встречающихся в подземных пространствах.","name":"Шифтер"}],"kind":"race","nameEn":"Dwarf","nameRu":"Дварф","names":[{"isMale":true,"name":"Груньяр"},{"isMale":true,"name":"Долгрин"},{"isMale":true,"name":"Казмук"},{"isMale":true,"name":"Моргрим"},{"isMale":true,"name":"Рогар"},{"isMale":true,"name":"Харск"},{"isMale":false,"name":"Агна"},{"isMale":false,"name":"Бодиль"},{"isMale":false,"name":"Ингра"},{"isMale":false,"name":"Котри"},{"isMale":false,"name":"Расилка"},{"isMale":false,"name":"Янгрит"}],"physicalDescription":"Дварфы низкорослы и коренасты. В среднем дварф ниже человека примерно на фут, зато широкоплеч и крепок. И мужчины, и женщины у дварфов гордятся длиной своих волос, мужчины часто заплетают бороды и украшают их заколками и бусинами. Чисто выбритый мужской подбородок у дварфов - явный признак безумия или чего похуже. Те, кто знаком с обычаями этого народа, не доверяют безбородым дварфам!","relations":"Дварфы долгое время обитали по соседству с орками. Они делят историю непрерывной вражды, древней, как оба эти народа. Дварфы обычно не доверяют полуоркам и сторонятся их. Они считают полуросликов, эльфов и гномов слишком хлипкими, ветреными и легкомысленными, чтобы уважать их по-настоящему. Только люди для дварфов представляются родственными душами - трудолюбие и здоровый аппетит хоть как-то приближают людей к дварфийскому идеалу.","slug":"dwarf","society":"Огромные расстояния, разделяющие поселения дварфов, привели к широкому разнообразию их обычаев в разных местах. Но, несмотря на все расхождения, дварфов объединяют любовь к зодчеству, страсть к работе с металлом и камнем и жгучая ненависть к великанам, оркам и гоблиноидам.","traits":[{"description":"Дварфы - народ крепкий и мудрый, хотя и грубоватый.","name":"+2 Выносливость, +2 Мудрость, -2 Харизма"},{"description":"Дварфы - существа среднего размера, что не дает им никаких бонусов или штрафов.","name":"Средний размер"},{"description":"Базовая скорость дварфов - 20 футов, но она никогда не снижается из-за доспехов или нагрузки.","name":"Медленно, но верно"},{"description":"Дварфы видят в темноте на 60 футов.","name":"Ночное зрение"},{"description":"Дварфы получают бонус +4 (уклонение) к КБ от атак противников с подтипом «великан».","name":"Умение защищаться"},{"description":"Дварфы получают +2 (народ) к проверкам Оценки при определении стоимости немагических предметов, содержащих драгоценные металлы и камни.","name":"Жадность"},{"description":"Дварфы получают +1 (народ) к атакам по гуманоидам с подтипами «орк» или «гоблиноид», так как обучены сражаться против своих кровных врагов.","name":"Ненависть"},{"description":"Дварфы получают +2 (народ) к испытаниям против ядов, заклинаний и псевдозаклинаний.","name":"Крепкий"},{"description":"Стоя на земле, дварфы получают +4 (народ) к ЗБМ, когда их пытаются сбить с ног или протаранить.","name":"Непоколебимость"},{"description":"Дварфы получают +2 к проверкам Внимания при обнаружении странностей в каменной кладке (например, ловушек или потайных дверей, скрытых в стенах или полу). Каждый раз, когда дварф оказывается на расстоянии 10 футов от такого места, он автоматически совершает эту проверку, даже если не занимается активным поиском.","name":"Знание камня"},{"description":"Все дварфы умеют пользоваться боевыми топорами, боевыми молотами и тяжелыми клевцами. Любое оружие со словом «дварфийский» в наименовании относится к категории особого оружия для представителей этого народа.","name":"Оружие дварфов"},{"description":"Дварфы начинают игру со знанием дварфийского и всеобщего языков. Дварфы с высоким значением Интеллекта могут выбрать дополнительные языки из следующего списка: великаний, гномий, гоблинский, орочий, подземный, терран.","name":"Языки"}]},{"adventurers":"Многие эльфы отправляются в странствия из желания повидать окружающий мир. Они покидают свои уединенные лесные поселения, чтобы вернуть утраченную магию своего народа или найти затерянные в веках царства, основанные их пращурами тысячелетия назад. Эльфов, выросших среди людей, зачастую привлекает жизнь авантюриста - свободная и непредсказуемая. Из-за своей хрупкости эльфы стараются избегать ближнего боя и предпочитают классы, работающие на дистанции, вроде волшебника или следопыта.","alignmentAndReligion":"Эльфы - существа переменчивые и эмоциональные, но ценящие добро и красоту. Мировоззрение большинства эльфов хаотичное доброе. Они отдают предпочтение богам, разделяющим их интерес к мистическим свойствам мира, особенно Дезне и Нефису. Первой - за ее чудеса и любовь к диким местам, а второму - за его мастерство в магии. Калистрия - самое известное божество эльфийского пантеона, но слава ее скандальна, так как она представляет собой воплощение эльфийских идеалов, доведенных до крайности.","altTraits":[{"description":"Некоторые эльфы процветают в самых глубоких пустынях, вечно бродя по выжженным и пустынным землям. Эльфы с этим расовым штрихом получают расовый бонус +4 к проверкам Выносливости и Стойкости, чтобы избежать усталости, утомления или вредных последствий бега, вынужденных маршей, голодания, жажды, жаркой или холодной среды.","name":"Бегущий По Пустыне","related":["Эльфийская магия"]},{"description":"Эльфы с этим расовым штрихом росли в уединенном, изолированном сообществе, где поколениями сохраняются ссоры как вечная кровная месть. Они получают бонус +1 к броскам атаки против гуманоидов подтипов гном и орк благодаря специальной подготовке против этих ненавистных противников.","name":"Вечная Обида","related":["Эльфийская магия"]},{"description":"Эльфы знают глубокие секреты дикой природы, как никто другой, особенно лесные. Эльфы с этим расовым штрихом получают бонус + 1 к Знанию (природы) и проверкам на Выживание. В лесной местности эти бонусы улучшаются до +2.","name":"Вудкрафт","related":["Эльфийская магия"]},{"description":"Некоторые эльфы приспособились к жизни у моря или у диких рек и озер, а иногда на плавучих домах в самих водоемах. Они получают расовый бонус +4 к проверкам Плавания, по каналам - 10 во время плавания и могут выбрать Акван в качестве дополнительного языка. Они получают Обращение с длинным копьем, трезубцем и сетью.","name":"Дух Воды","related":["Оружие эльфов","Эльфийская магия"]},{"description":"У нескольких эльфов есть способность использовать силу снов, предвидения и мечтаний. Эльфы с этим расовым штрихом добавляют +1 к СЛ бросков для заклинаний школы прорицания и эффектов сна, которые они накладывают. Кроме того, эльфы с Харизмой 15 или выше могут использовать Сон один раз в день как псевдозаклинание (уровень заклинателя равен уровню персонажа самого эльфа).","name":"Онейромант","related":["Эльфийский иммунитет"]},{"description":"Многие эльфы почитают солнце, луны и звезды, но некоторые буквально наполняются сияющей силой небес. Эльфы с этим расовым штрихом - это иммунные эффекты слепоты и ослепления, основанные на рассвете, и рассматриваются на один уровень выше при определении эффектов любого заклинания, основанного на свете, или эффекта, который они накладывают (включая псевдозаклинания и сверхъестественные способности). Эльфы с Интеллектом 10 или выше могут использовать Свет по своему желанию в качестве псевдозаклинания.","name":"Светоносный","related":["Эльфийская магия","Эльфийский иммунитет"]},{"description":"Эльфы славятся своей ловкостью и умением. Эльфы с этим расовым штрихом уменьшают штраф за использование Скрытности при перемещении на 5 и могут проверять Скрытность, выполняя штраф -20 (это число включает уменьшение штрафа от этого расового штриха).","name":"Тихий Охотник","related":["Эльфийская магия"]}],"book":"Core Rulebook","description":"Эльфы - долгожители, дети природы, во многом похожие на фей и все же отличающиеся от них. Эльфы дорожат своими традициями и уединенным образом жизни, с трудом обзаводятся друзьями (как на личном, так и на государственном уровне), но, однажды приняв чужака как друга, могут поддерживать такой союз веками. У эльфов наблюдается любопытная взаимосвязь с окружающим миром - вероятно, из-за их долгой жизни, а может быть, и по другим, более загадочным причинам. Прожив в одном регионе достаточно долго, эльфы физически адаптируются к окружающей среде, что особенно хорошо заметно по изменениям в цвете их кожи, волос и глаз. Эльфы, поселившиеся среди существ, чей век более короток, чем их собственный, зачастую становятся угрюмы и начинают воспринимать бессмертие как бремя, видя, как поколение за поколением товарищей стареет и умирает у них на глазах.","favoredClass":[{"alias":"bard","description":"Добавьте +1 к ЗБМ эльфа, когда сопротивляетесь разоружению или попытке сломать его оружие.","name":"Бард"},{"alias":"barbarian","description":"Добавьте +1 к базовой скорости эльфа. В бою это не действует, если эльф не выбрал этот бонус 5 раз; например, скорость 34 фута фактически равна скорости 30 футов. Этот бонус суммируется с функцией быстрого перемещения класса и применяется только при тех же условиях, что и эта способность.","name":"Варвар"},{"alias":"witch","description":"Добавьте одно заклинание из списка заклинаний ведьмы к фамильяру ведьмы. Это заклинание должно быть как минимум на один уровень ниже заклинания самого высокого уровня, которое она может использовать. Если ведьма заменит своего фамильяра, новый фамильяр будет знать эти дополнительные заклинания.","name":"Ведьма"},{"alias":"witch","description":"Добавьте бонус +1/2 к проверкам Колдовства, чтобы идентифицировать проклятые предметы, и к проверкам Проницательности, чтобы заметить наговор или одержимость.","name":"Ведьма"},{"alias":"fighter","description":"Добавьте +1 к ЗБМ эльфа, когда сопротивляетесь разоружению или попытке сломать его оружие.","name":"Воин"},{"alias":"wizard","description":"Выберите одну магическую школу на 1-м уровне, способность которой можно использовать несколько раз в день, равную 3 + модификатор Интеллекта волшебника. Волшебник добавляет +1/2 к количеству использования в день этой способности школы.","name":"Волшебник"},{"alias":"cavalier","description":"Добавьте +1 ПЗ к скакуну кавалериста. Если эльф когда-либо заменяет своего скакуна, новый скакун получает эти бонусные пункты. Эти бонусы применяются только к одному скакуну, полученному как часть класса кавалериста.","name":"Кавалерист"},{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"},{"alias":"vigilante","description":"Добавьте +1/3 ко всем проверкам Акробатики, Лазания и Скрытности в лесу.","name":"Линчеватель"},{"alias":"ranger","description":"Выберите оружие из следующего списка: длинный лук, длинный меч, рапира, короткий лук, короткий меч или любое оружие с именем «эльфийский». Добавьте +1/2 бонус обстоятельств к броскам подтверждения критического удара с этим оружием (максимальный бонус +4). Этот бонус не суммируется с Критической точностью.","name":"Следопыт"},{"alias":"sorcerer","description":"Выберите силу Наследия на 1-м уровне, которую обычно можно использовать несколько раз в день, равную 3 + модификатор Харизмы чародея. Чародей добавляет +1/2 к количеству использований в день этой силы Наследия.","name":"Чародей"},{"alias":"shaman","description":"Добавьте 5 футов дальности одному из наговоров. Множественные бонуса к дальности могут быть применены на один наговор, максимум добавляя до 30 футов дальности одному конкретному наговору.","name":"Шаман"},{"alias":"shifter","description":"Добавьте 1 к базовой скорости шифтера. Этот бонус никак не влияет на игровой процесс, пока шифтер не возьмет его 5 раз (или количество раз, кратное 5), чтобы увеличить скорость на 5 футов. Бонус применяется, только если шифтер не носит брони.","name":"Шифтер"}],"kind":"race","nameEn":"Elf","nameRu":"Эльф","names":[{"isMale":true,"name":"Вариэль"},{"isMale":true,"name":"Зордлон"},{"isMale":true,"name":"Каладрель"},{"isMale":true,"name":"Ланлисс"},{"isMale":true,"name":"Мейрдрарель"},{"isMale":true,"name":"Сельдлон"},{"isMale":true,"name":"Талафель"},{"isMale":true,"name":"Хельдалель"},{"isMale":false,"name":"Амранелара"},{"isMale":false,"name":"Дарллара"},{"isMale":false,"name":"Джафаль"},{"isMale":false,"name":"Мерисиэль"},{"isMale":false,"name":"Опараль"},{"isMale":false,"name":"Сумраль"},{"isMale":false,"name":"Тессара"},{"isMale":false,"name":"Фаунра"},{"isMale":false,"name":"Яландлара"}],"physicalDescription":"Эльфы обычно выше людей, но обладают более хрупким и изящным сложением и длинными заостренными ушами. У эльфов большие миндалевидные глаза с крупными, ярко окрашенными радужками. Хотя в эльфийских нарядах обычно отражается красота природы, эльфы, живущие в городах, одеваются по последней моде.","relations":"Эльфы склонны считать остальные народы слишком торопливыми и импульсивными, а потому не воспринимают их всерьез, но при этом хорошо разбираются в чужих душах. Эльфу может не нравиться сосед-дварф, но он первым признает кузнечное мастерство этого дварфа. Эльфы считают гномов странными (а порой и опасными) чудаками, а к полуросликам относятся с некоторой жалостью, так как, на эльфийский взгляд, эти малыши живут бродягами, не имея родных земель. Люди эльфов просто очаровывают, что подтверждается большим числом полуэльфов, хотя эльфы обычно не признают таких потомков. К полуоркам эльфы относятся с недоверием и подозрением.","slug":"elf","society":"Многие эльфы чувствуют свою связь с природой и стремятся жить с ней в гармонии. Большинство, впрочем, считает работу с землей и камнем вульгарной и предпочитает ей изящные искусства, а врожденное терпение помогает им в занятиях волшебством.","traits":[{"description":"Эльфы обладают гибким телом и мышлением, но хрупким сложением.","name":"+2 Ловкость, +2 Интеллект, -2 Выносливость"},{"description":"Эльфы - существа среднего размера, что не дает им никаких бонусов или штрафов.","name":"Средний размер"},{"description":"Базовая скорость эльфов - 30 футов.","name":"Нормальная скорость"},{"description":"Эльфы видят в сумерках вдвое дальше людей.","name":"Сумеречное зрение"},{"description":"Эльфы невосприимчивы к магическому сну и получают +2 (народ) к испытаниям против заклинаний и эффектов школы очарования.","name":"Эльфийский иммунитет"},{"description":"Эльфы получают +2 (народ) к проверкам преодоления УкМ. Кроме того, эльфы получают +2 (народ) к проверкам Колдовства для определения свойств волшебных вещей.","name":"Эльфийская магия"},{"description":"Эльфы получают +2 (народ) к проверкам Внимания.","name":"Острые чувства"},{"description":"Все эльфы умеют пользоваться длинными и короткими луками (включая композитные), длинными мечами и рапирами; любое оружие со словом «эльфийский» в наименовании относится к категории особого оружия для представителей этого народа.","name":"Оружие эльфов"},{"description":"Эльфы начинают игру со знанием эльфийского и всеобщего языков. Эльфы с высоким значением Интеллекта могут выбрать дополнительные языки из следующего списка: гнолльский, гномий, гоблинский, драконий, небесный, орочий, сильван.","name":"Языки"}]},{"adventurers":"Вездесущие опасности Теневого плана представляют большую опасность для ловких искателей приключений, но довольно удобны. Из-за их рабского статуса в их родном мире, однако, большинство фетчлингов предпочитают приключения на Материальном плане, который часто предлагает больше свободы и торговых возможностей между двумя мирами. Фетчлинги становятся отличными ниндзя, оракулами, следопытами, плутами и призывателями.","alignmentAndReligion":"Фетчлинги, особенно те, кто живут за пределами Теневого Плана - поклоняются множеству разных богов. На Теневом Плане они в первую очередь поклоняются Дезне и Зон-Кутону, хотя первой скорее почитаются, а последнего скорее умиротворяют, чем поклоняются. А меньшинство злых фетчлингов поклоняется демоническим владыкам тьмы и похоти.","book":"Advanced Race Guide","description":"Произошли от людей, пойманных в ловушку на Теневом Плане, фетчлинги - это сплетенные между собой создания тьмы и света. Поколения соприкосновений с этим странным планом и его жителями сделали фетчлингов народом, отличным от человечества. Признавая свое происхождение, они демонстрируют мало физического или культурного сходства со своими предками с материального плана, и их часто оскорбляют, сравнивая с людьми. Некоторые представители народа также обижаются на «фетчлингов», которых так назвали люди, видевшие в них не более чем сборщиков редких материалов с Теневого Плана. Вместо этого большинство фетчлингов предпочитают называться каял, слово, заимствованное с Акло, что примерно переводится как «теневые люди» или «обитатели сумерек». Пропитанные сущностью Теневого Плана и обладающие человеческой кровью, смешанной с кровью из иного плана, у фетчлингов развились черты характера и способности, которые дополняют мрачную и бесцветную местность их родного мира. Хотя большинство фетчлингов считают Теневой План домом, они часто торгуют и имеют дело с существами с Материального Плана. Иногда это доходит до создания анклавов на Материальном Плане, чтобы устанавливать союзы и торговые пути в областях, где Граница между двумя мирами менее четкая. Эти фетчлинги часто служат торговцами, посредниками и направляющими для сделок по обе стороны планарной границы.","favoredClass":[{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"}],"kind":"race","nameEn":"Fetchling","nameRu":"Фетчлинг","names":[{"isMale":true,"name":"Арим"},{"isMale":true,"name":"Дросил"},{"isMale":true,"name":"Джеган"},{"isMale":true,"name":"Сомар"},{"isMale":true,"name":"Йетар"},{"isMale":true,"name":"Зока"},{"isMale":false,"name":"Асера"},{"isMale":false,"name":"Амелис"},{"isMale":false,"name":"Инва"},{"isMale":false,"name":"Ренза"},{"isMale":false,"name":"Заитерин"}],"physicalDescription":"Внешне фетчлинги похожи на неестественно гибких - граничащих с хрупкими - людей. Их новый дом лишил их кожу и волосы света. Их цвет лица варьируется от совершенно белого до глубокого черного и включает в себя все оттенки серого между этими двумя крайностями. Их глаза без зрачков и ярко выражены, и они обычно светятся люминесцентным оттенком желтого или зеленовато-желтого, но редко фетчлинги обладают сине-зелеными глазами. В то время как их волосы имеют тенденцию быть белыми или бледно-серыми, многие фетчлинги красят волосы в черный цвет. Некоторые представители высшего положения или те, кто живет на Материальном плане, окрашивают волосы в более яркие цвета, часто предпочитая глубокие оттенки фиолетового, синего и малинового.","relations":"Из-за общего происхождения легче всего взаимодействуют с людьми, хотя они также находят родство с гномами и другими народами, которые были отрезаны от своих домашних планов или не являются родными для Материального Плана. Их прагматизм и адаптивность поставили их в противоречии с воинственными или разрушительными народами, и когда им приходится иметь дело с орками, гоблиноидами или другими дикарями, фетчлинги часто играют роль льстецов, пользуясь тактикой, усвоенной в служении теневым драконам и тем, кого они считают ключом к выживанию своего народа. Как ни странно, их отношения с дварфами и эльфами скорее напряженные. Дварфы находят фетчлингов двуличными и жуткими, в то время как напряжение с эльфами так тонко и необъяснимо, что это трудно объяснить обоим народам.","slug":"fetchling","society":"Фетчлинги - существа, которые легко приспосабливаются, и как таковые не проявляют особого предпочтения в моральной философии или верховенстве закона. Большинство имитирует культурные нормы и правительственные структуры тех, рядом с кем они живут, или существ, которым они служат. В то время как фетчлинги, возможно, самая многочисленная раса на Теневом Плане, они редко правят своими собратьями; большинство служат вассалами или подданными великим теневым драконам своей родины или причудливым существам, обитающим в глубокой тьме. Однако, фетчлинги остались в живых. Их упорство, универсальность и коварный прагматизм помогли им пережить суровые окрестности Теневого Плана и заговоры могущественных существ, живущих в нем. На Материальном Плане, особенно если они не могут по желанию вернуться в родной мир, фетчлинги, как правило, собираются в небольшие замкнутые сообщества себе подобных, подражая культурным нормам и политическим структурам тех, с кем они торгуют.","traits":[{"description":"Фетчлинги используют уровни в классах - КЗ народа у них нет.","name":""},{"description":"Фетчлинги быстрые и сильные, но часто странные и легко отвлекаются на посторонние мысли.","name":"+2 Ловкость, +2 Харизма, -2 Мудрость"},{"description":"Фетчлинги - потусторонние существа с подтипом местное.","name":"Местное потусторонне существо"},{"description":"Фетчлинги - существа среднего размера и не получают никаких бонусов или штрафов из-за их размера.","name":"Средний размер"},{"description":"Базовая скорость фетчлингов составляет 30 футов.","name":"Нормальная скорость"},{"description":"Фетчлинги могут видеть в темноте до 60 футов.","name":"Ночное зрение"},{"description":"Фетчлинги могут видеть вдвое дальше, чем люди, в условиях тусклого света.","name":"Сумеречное зрение"},{"description":"Фетчлинги имеют бонус народа +2 к проверкам Знания (планы) и Скрытности.","name":"Умелый"},{"description":"Атаки против фетчлингов при тусклом свете имеют 50% шанс промаха вместо обычных 20%. Эта способность не дает состояния отсутствия видимости, она просто увеличивает шанс промаха.","name":"Смешение теней (Св)"},{"description":"У Фетчлингов имеется устойчивость холоду и электричеству 5.","name":"Устойчивость теней"},{"description":"Фетчлинг может использовать изменение облика один раз в день как псевдозаклинание. Он может принять форму любого гуманоида, используя эту способность. Когда фетчлинг достигает 9-го уровня в любой комбинации классов, он получает путь в тенях (только для себя) как псевдозаклинание, которое можно использовать один раз в день, и на 13-м уровне он получает планарный переход (только для себя, только на Теневой План или только на Материальный План), который можно использовать один раз в день. Уровень заклинателя фетчлинга равен его общему количеству КЗ.","name":"Псевдозаклинания (Пс)"},{"description":"Фетчлинги начинают игру, говоря на всеобщем. Фетчлинги с высоким значением Интеллекта могут выбрать один из следующих языков: Акло, Акван, Ауран, Драконий, Д'зириак (только понимать, не может говорить), Игнан, Терран и любой региональный человеческий язык.","name":"Языки"}]},{"adventurers":"Учитывая их связь с Лазурной Пустотой и ее жителями, ганзи, осознающие свое наследие и ресурсы для планарных путешествий, нередко отправляются в Мальстрём. Некоторые ганзи совершают это паломничество в поисках протеан, валькирий или других обитателей Мальстрёма в надежде понять свое место в космосе, в то время как других привлекает идея общения с огромной и могущественной силой самого первородного хаоса. Ганзи обычно обладают глубоким любопытством и мощным творческим талантом, благодаря чему многие из них становятся художниками или бардами, в то время как другие наслаждаются дихотомическим мастерством алхимика в создании и разрушении. Неудивительно, что среди ганзи распространены чародейские таланты и оракульские тайны всех разновидностей.","alignmentAndReligion":"Как и положено их хаотичному происхождению, личности и мировоззрение отдельных ганзи могут значительно различаться. Часто хаотично настроенные, без особой склонности к добру или злу, многие обнаруживают, что их тянет к жизни странствующего искателя приключений.","book":"Planar Adventures","description":"Ганзи - конечный результат планарного хаоса, затрагивающего живых существ. Там, где планы соприкасаются с Материальным Планом или где хаотические обитатели (будь то звери хаоса, протеане, валькирии или другие) взаимодействуют или влияют на жизнь смертных, ганзи рождаются на их пути, как рябь в пруду.","favoredClass":[{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"}],"kind":"race","nameEn":"Ganzi","nameRu":"Ганзи","physicalDescription":"Хотя внешне ганзи похожи на людей, у них часто есть черты, которые отличают их от остального человечества. Эти особенности могут сильно различаться; у одного ганзи может быть обесцвеченная рука, которая мерцает энтропийной (но безвредной) энергией, у другого может быть яркая чешуя, покрывающая плечи и спину, а у третьего могут быть рога и светящиеся зеленые глаза. Точно так же рост и вес ганзи могут сильно различаться, даже по человеческим меркам, но средний ганзи имеет рост от 5 до 6 футов и весит от 100 до 300 фунтов.","relations":"Многих ганзи при рождении принимают за аасимаров или тифлингов, но на самом деле рождение ганзи очень редко происходит в результате смешивания смертных с потусторонними существами. Подавляющее большинство рождаются после того, как один или оба родителя подверглись воздействию силы хаотической или энтропийной энергии. Таким образом, обстоятельства детства ганзи могут сильно различаться и зависеть от терпимости родителей к неожиданностям. Склонность ганзи к хаосу усугубляет ситуацию, поскольку многие ганзи приобретают среди своих сверстников общительную, иконоборческую или ищущую острых ощущений репутацию. Значительное меньшинство ганзи в раннем возрасте выглядит полностью человеком, их анархическое наследие проявляется вскоре после полового созревания в хаотическом и травматическом спазме быстрой эволюции. Хотя ганзи чаще всего происходят от людей, нередко ганзи рождаются среди других народов. Эти ганзи несут поверхностные признаки своего нечеловеческого происхождения, но их характеристики и способности идентичны тем, что рождены людьми.","slug":"ganzi","society":"Как и другие местные потусторонние существа гуманоидного происхождения, ганзи чаще всего встречаются разбросанными среди обществ своих родительских народов. Те редкие ганзи, которые предпочитают не странствовать, могут прожить всю свою жизнь, не встретив никого из своего вида. Из-за разрозненного происхождения и склонности к кочевому образу жизни ганзи редко собираются в значительные количества и почти никогда не образуют собственной культуры. Иногда общество Материального плана в регионе, связанном с другими планами, со временем производит достаточно ганзи, чтобы они могли сформировать свою собственную субкультуру, но такие общества действительно редки.","traits":[{"description":"Ганзи используют уровни в классах - КЗ народа у них нет.","name":""},{"description":"Ганзи страстны, креативны и устойчивы, но им трудно сосредоточиться на интеллектуальной деятельности.","name":"+2 Выносливость, +2 Харизма, -2 Интеллект"},{"description":"Ганзи - потусторонние существа с подтипом местный.","name":"Местное потустороннее существо (Native Outsider)"},{"description":"Ганзи - существа среднего размера, что не даёт им никаких бонусов или штрафов.","name":"Средний размер (Medium)"},{"description":"Базовая скорость ганзи - 30 футов.","name":"Нормальная скорость (Normal Speed)"},{"description":"Ганзи видят в темноте на 60 футов.","name":"Ночное зрение (Darkvision)"},{"description":"Ганзи получают +2 (народ) к проверкам Выживания и Проницаемости.","name":"Умелый (Skilled)"},{"description":"Ганзи получают устойчивость к звуку 5, устойчивость к кислоте 5, устойчивость к электричеству 5 и +2 (народ) к испытаниям против заклинаний подшколы полиморфизма.","name":"Устойчивость Мальстрёма (Maelstrom Resistance)"},{"description":"Будучи существами, наполненными энтропийными силами Мальстрёма, все ганзи обладают ярко выраженной и необычной странностью, которая проявляется в физических или магических способностях, которые отличают ганзи от других. Обычно странность ганзи выбирается из наиболее распространенных проявлений энтропии, перечисленных ниже, но, безусловно, могут существовать и другие, более уникальные странности. Перечисленные числа для каждого варианта могут быть использованы для случайного определения того, какую форму странности Ганзи может иметь конкретный Ганзи, по усмотрению ведущего, но способность каламбура является наиболее распространенной. 1–2: Чемпион Хаоса (Chaos Champion) (Св): Ганзи, родословная которого связана с эйнхерьи, часто становится крестоносцем сил энтропии и преуспевает в бою против принципиальных существ. Ганзи могут сокрушить принципиальность один раз в день быстрым действием, нацелившись на принципиального противника. Он добавляет свой модификатор Харизмы в качестве бонуса к броскам атаки и получает бонус к броскам урона, равный его КЗ. После активации сокрушение принципиальности действует до тех пор, пока цель не умрет или ганзи не успокоится, в зависимости от того, что наступит раньше. 3–4: Энтропическая плоть (Entropic Flesh) (Экс): Ганзи, родословная которого тесно связана со зверями хаоса, сохраняют часть устойчивости своих предков к трансформации. В дополнение к получению бонуса +2 к проверкам Изворотливости и ЗБМ против боевых маневров захвата, когда на таких ганзи действует враждебный эффект трансмутации (например, полиморф или окаменение), он может попытаться пройти новое испытание в начале их следующего хода, чтобы закончить эффект. Он получает бонус +4 к этому второму испытанию, но если он провалится, эффект трансмутации сохраняется до тех пор, как это происходит обычно. 5–6: Цепкий хвост (Prehensile Tail) (Экс): Ганзи, на родословную которого особенно влияет присутствие протеан, часто имеют разноцветные перья, чешую или кожу, а также длинный змеиный хвост. Этот хвост можно использовать для переноски предметов. Хотя ганзи с этой странностью не могут владеть оружием хвостом, они могут использовать хвост для быстрого извлечения небольших предметов, которые они несут при себе. 7–14: Каламбур (Quibble) (Св): Для большинства ганзи влияние хаоса относительно тонкое и проявляется как способность заражать других энтропией и неожиданной удачей (будь то удача или неудача). Один раз в день в качестве прерывающего действия ганзи может исказить вероятность и изменить удачу одного существа в пределах 20 футов, заставляя его перебросить один только что сделанный бросок d20. Цель должна принять второй результат, даже если он хуже. Ганзи может использовать эту способность после того, как цель совершила бросок, но должен использовать ее до того, как ведущий объявит, был ли бросок успешным или неудачным. Несогласные существа могут сопротивляться калабмуру ганзи с помощью успешного испытания Воли (СЛ = 10 + 1/2 уровня ганзи + модификатор Харизмы ганзи). Это эффект проклятия. 15–18: Псевдозаклинание (Spell-Like Ability) (Пс): Ганзи, чье хаотическое влияние исходит из регионов, отличных от Мальстрёма или его жителей, часто проявляет странность, которая дублирует эффекты определенного заклинания. Такие ганзи получают одно из следующих псевдозаклинаний, которые можно использовать один раз в день с УЗ, равном КХ ганзи: иной облик, расплывчатость, чтение мыслей, безудержный смех, малый образ, разбивающий звук или паучьи лапы. 19–20: Игра с оружием (Weaponplay) (Экс): Ганзи, родословная которых связана с валькириями, проявляют свое наследие в своих боевых навыках. Такие ганзи всегда владеют всем простым и особым оружием, и они могут претендовать на черты, обычно доступные только воинам (например, Привычное оружие), даже если у них нет уровней класса воина.","name":"Странность ганзи (Ganzi Oddity)"},{"description":"Ганзи начинают игру со знанием всеобщего и одного из следующих языков: демонического, небесного или протеанского. Ганзи с высоким значением Интеллекта могут выбрать в качестве дополнительного любой из этих языков, а также дополнительные языки из следующего списка: акван, акло, ауран, игнан, сильван или терран.","name":"Языки (Languages)"}]},{"adventurers":"Гатлейны стремятся развлечь себя и удовлетворить безмерное любопытство к окружающему миру, и те, кто решает стать авантюристами, часто мигрируют на Материальный План для исследования. Те, кто остался в Первом Мире, ищут самые странные уголки родного плана и пытаются узнать о его самых необычных обитателях. Они предпочитают классы заклинателей и классы с большим количеством навыков, такие как бард или плут.","alignmentAndReligion":"Озорные и капризные гатлейны имеют противоречивый темперамент. Большинство из них хаотичны и, как правило, морально нейтральны. Типичный гатлейн находит религии смертных странными; как и многие феи, они обменивают уважение и символические подношения богоподобным феям в обмен на защиту, но они не видят большой разницы между этим и подношениями меньшим королям и королевам.","book":"Ultimate Wilderness","description":"Согласно некоторым балладам о феях гатлейны были одним первых народов, появившихся в мире Фей. Они были созданы из семян огромного волшебного дерева, с омелой внутри их плоти, которая формирует их странные крылья. Озорные и капризные, эти существа имеют противоречивые темпераменты. Все что они хотят это развлекаться и утолять свое безмерное любопытство к окружающему миру. Как раз именно чувство любопытства и заставило многих представителей этой расы мигрировать в материальный мир и начать искать приключение на одно место там. Подобные приключенцы всегда ищут способ примешаться к гномам. Тем не менее, зачастую гномы воспринимают этих фей несерьезно, находя их не дисциплинированными, непостоянными и дурашливыми из-за их пристрастий.","favoredClass":[{"alias":"witch","description":"Добавьте одно заклинание из списка заклинаний друида фамильяру ведьмы. Это заклинание должно быть, как минимум на один уровень ниже самого высокого уровня заклинания, которое может сотворить ведьма. Если ведьма заменит своего фамильяра, новый фамильяр будет знать эти дополнительные заклинания.","name":"Ведьма"},{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"shaman","description":"Добавьте 1 заклинание из списка заклинаний друида к списку заклинаний, которые знает шаман. Заклинание должно быть хотя бы на 1 круг меньше максимального круга, который может применять шаман.","name":"Шаман"}],"kind":"race","nameEn":"Gathlain","nameRu":"Гатлейн","names":[{"isMale":false,"name":"Аголия"},{"isMale":false,"name":"Армат"},{"isMale":false,"name":"Арнонви"},{"isMale":false,"name":"Бразиал"},{"isMale":false,"name":"Гаммоу"},{"isMale":false,"name":"Двиннен"},{"isMale":false,"name":"Инирха"},{"isMale":false,"name":"Маркант"},{"isMale":false,"name":"Нириалу"},{"isMale":false,"name":"Соллови"},{"isMale":false,"name":"Тилтиу"},{"isMale":false,"name":"Уриод"},{"isMale":false,"name":"Финнат"},{"isMale":false,"name":"Эйргара"}],"physicalDescription":"Крылья из дерева и лозы вырастают из тел этих гибких фей. Гатлейны предпочитают носить смешанную одежду, состоящую из натуральных материалов, таких как юбки из травы или просто тканые туники в сочетании с кусочками нарядов, собранных из разных мест.","relations":"Гатлейны общаются с множеством других фей так же свободно, как и с себе подобными. Эти смешанные сообщества фей называются дворами и имеют сложные титулы для тех членов, которые считаются наиболее интересными или достойными восхищения. Когда гатлейн решает присоединиться к другому сообществу, это, как правило, временное членство, независимо от того, длится ли оно только сезон или сохраняется десятилетиями. Гатлейны-авантюристы часто ищут гномов-единомышленников и пытаются смешаться с ними; однако гномы часто находят гатлейнов слишком взбалмошными, глупыми и недисциплинированными на их вкус.","slug":"gathlain","society":"Общество гатлейнов построено на искусстве, открытиях, экспериментах и ​​рассказывании историй. Эти феи постоянно ищут новые способы смотреть на мир. Лидеры гатлейнов часто являются популярными исследователями, за которыми следуют в первую очередь как за достойными подражания идолами и источниками интригующих сплетен. Хотя гатлейны склонны вступать в бурные романы, порождённые мелодраматическими или причудливыми встречами, обычно они не производят потомство от таких пар, даже если эти двое оказываются разного физического пола. Гатлейны не проявляют особого интереса к полу, находя его странным, когда другие народы используют его в качестве основы для распределения ролей или выбора партнёров.","traits":[{"description":"Гатлейны используют уровни в классах - КЗ народа у них нет.","name":""},{"description":"Фея.","name":"Тип"},{"description":"Гатлейны быстрые, энергичные и привлекательные личности, но довольно хрупкие.","name":"+2 к Ловкости, -2 к Выносливости, +2 к Харизме"},{"description":"Гатлейны - существа небольшого размера, поэтому они получают +1 (размер) к КБ, +1 (размер) к атакам, -1 к МБМ и ЗБМ и +4 (размер) к проверкам Скрытности.","name":"Небольшой размер"},{"description":"Гатлейны имеют базовую скорость 30 футов, а также скорость полета 40 футов.","name":"Обычная скорость"},{"description":"Гатлейны видят в сумерках вдвое дальше людей.","name":"Сумеречное зрение"},{"description":"Гатлейны обладают бонусом +1 к естественной броне.","name":"Естественная броня"},{"description":"1/день - опутывание, легкий шаг (УЗ равен уровню персонажа).","name":"Псевдозаклинания"},{"description":"Гатлейны начинают игру со знанием общего и сильванского языков. Гатлейны с высоким показателем Интеллекта могут выбрать следующие языки: драконий, эльфийский, гоблинский, полуросличий и орочий.","name":"Языки"}]},{"adventurers":"Из-за своей восхитительной природы гораны редко узнают мир так, как это делают гуманоидные народы, потому многие вынуждены бороться с природой и учиться сражаться в качестве средства самозащиты от захвата и потребления. Большинство ведут приключенческий образ жизни либо для помощи друзьям и товарищам, либо из более темного стремления отомстить. Другие присоединяются к группам искателей приключений в надежде накопить достаточно сил и знаний, чтобы, возможно, найти решение центральной проблемы воспроизводства своего народа, хотя до сих пор ни один горан не решил эту важную загадку.","alignmentAndReligion":"Гораны редко следуют гуманоидным божествам, вместо этого предпочитая поклоняться самой природе посредством Зеленой Веры или других могущественных духов природы, таких как Старейший из Первого Мира. Гораны не имеют предрасположенности к принципиальности, хаосу, добру или злу, но многие изо всех сил пытаются отличить правильное от неправильного, как это определено большинством обществ.","altTraits":[{"description":"Связь некоторых горан с их прошлыми жизнями искажается, из-за чего их вкус становится особенно отвратительным. Такие гораны получают бонус народа +2 к Изворотливости и проверкам боевых маневров, чтобы избежать захвата против любого существа, которое имеет атаку укусом со способностью захвата.","name":"Отвратительный (Disgusting)","related":["Вкусный (Delicious) (Экс)","Знание прошлых жизней (Past-Life Knowledge) (Экс)"]},{"description":"Некоторые гораны эволюционируют, пересаживаясь в разные места. С каждым новым семенем эти гораны приобретают некоторые черты областей, окружающих их новый рост. Гораны с этим штрихом выбирают одну местность из списка излюбленных местностей следопыта, кроме планов, городов или воды. Эти гораны получают бонус народа +4 к проверкам Скрытности, когда находятся в выбранной ими местности.","name":"Естественный камуфляж (Natural Camouflage)","related":["+2 к естественной броне (+2 Natural Armor)"]},{"description":"Некоторые гораны обладают невероятно отвлекающим запахом. Один раз в день, как псевдозаклинание, горан с этим штрихом народа может испускать опьяняющий аромат, который завораживает существ в пределах 30 футов на 1d4 раунда. Каждое целевое существо в пределах дистанции может попытаться пройти испытание Воли (СЛ = 10 + половина уровня персонажа горана + модификатор Харизмы горана), чтобы свести эффект на нет.","name":"Опьяняющий аромат (Intoxicating Aroma)","related":["Природная магия (Natural Magic) (Пс)"]},{"description":"Наполненные друидической магией своего создателя, гораны быстро овладевают природными заклинаниями и колдовством. Гораны кровавые ярости и чародеи с растительным наследием считают, что их показатель Харизмы на 2 пункта выше для заклинаний чародея и классовых способностей. Гораны жрецы и друиды со сферой растений используют силы и заклинания своей сферы с +1 уровнем заклинателя. Это не дает горанам ранний доступ к способностям, основанным на уровне; влияет только на способности, которые уже можно было бы использовать без этой черты.","name":"Наследие Создателя","related":["Знание прошлых жизней (Past-Life Knowledge) (Экс)"]},{"description":"Созданные частично в результате эзотерического ритуала, многие гораны врожденно чувствительны к экстрасенсорным силам и влияниям. Горан получает Экстрасенсорную чувствительность в качестве бонусной черты и рассматривает Знание (магия) и Знание (планы) как классовые навыки.","name":"Оккультный отпрыск (Occult Scion)","related":["Знание прошлых жизней (Past-Life Knowledge) (Экс)"]},{"description":"Гораны были созданы, чтобы кормить существ, но Горус также хотел, чтобы гораны помогали земле вокруг них расти и процветать. Один раз в день горан с этим штрихом народа может использовать рост растений как псевдозаклинание с уровнем заклинателя, равным уровню персонажа горана.","name":"Плодородная Земля (Fecund Earth)","related":["Знание прошлых жизней (Past-Life Knowledge) (Экс)","Природная магия (Natural Magic) (Пс)"]},{"description":"Многие гораны устойчивы к магии или способны рассеять ее. Некоторые гораны даже питаются от поглощения магии. Всякий раз, когда такой горан преуспевает в испытании против заклинания или псевдозаклинания, он восстанавливает 1 ПЗ за уровень заклинания, хотя это влияет на горана, только если его ПЗ выше 0. Горан может использовать эту способность количество раз в день, равное его уровню.","name":"Магическое поглощение (Magical Absorption)","related":["Знание прошлых жизней (Past-Life Knowledge) (Экс)","Природная магия (Natural Magic) (Пс)"]},{"description":"Изначально гораны были созданы, чтобы выживать и процветать в разрушенной магией пустоши, и на протяжении веков некоторые гораны адаптировали свои способности для преодоления магии в целом. Один раз в день горан может использовать рассеивание магии как псевдозаклинание с уровнем заклинателя, равным уровню персонажа горана. Если предпочитаемым классом горана является колдовской класс, горан получает бонус народа +2 к проверкам рассеивания.","name":"Пожиратель заклинаний (Spelleater)","related":["Знание прошлых жизней (Past-Life Knowledge) (Экс)","Природная магия (Natural Magic) (Пс)"]},{"description":"Личная история многих горанов отмечена отчаянной борьбой за выживание, и воспоминания об этом конфликте глубоко укоренились в их семенах. Всякий раз, когда гораны с этим штрихом народа выращивают новые тела из своих семян, они перевыбирают все известные боевые черты вместо того, чтобы перераспределять ранги навыков.","name":"Военные воспоминания (Martial Recollection) (Экс)","related":["Природная магия (Natural Magic) (Пс)","Семя (Seed) (Экс)"]}],"book":"Ultimate Wilderness","description":"Первые гораны появились тысячи лет назад во время великой войны между двумя народами, управляемыми соперничающими архимагами. Когда могущественные некромантские проклятия поразили земли одного народа, оставив его жителей на грани голодной смерти, их хитрый лидер заключил сделку с друидом-изменником Горусом, попросив его использовать свои запретные таланты для спасения королевства. Решением друида было создание народа выносливых и быстро адаптирующихся растений, способных процветать даже на проклятой земле. Эти растения, которые друид назвал в честь себя горанами, быстро развили способность передвигаться самостоятельно, выискивая наиболее питательную почву и постоянно приспосабливаясь к выживанию во все более и более опасных условиях. По мере роста интеллекта гораны эволюционировали в человекоподобные формы в качестве защитного механизма, вызывающего симпатию и предотвращающего дальнейшую резню. Когда Горус умер, он унес секреты создания новых горанов в могилу, и с этого момента количество горанов в мире стало неизменным. В то время как каждый горан мог увековечить себя с помощью одного бессмертного семени, невозможность выращивать или размножать их вид гарантировала, что новые гораны никогда не появятся. С каждой смертью горана в результате несчастного случая или насилия их популяция в целом сокращалась. Тот факт, что их «мясо» стало считаться деликатесом, только еще больше усложнил их роль в обществе, и хотя в большинстве регионов вскоре добыча и употребление в пищу вновь обретших разум горан были запрещены, на них по-прежнему охотятся те, кто распробовал их сочный вкус.","favoredClass":[{"alias":"witch","description":"Добавьте 1/4 к УЗ ведьмы при проверке рассеивания с помощью рассеивания магии, разрушения чар и подобных эффектов.","name":"Ведьма"},{"alias":"mesmerist","description":"Выберите один воздействующий на разум гипнотический трюк, известный гипнотизеру. С помощью этого трюка или заклинания гипнотизер может воздействовать на разумных растительных существ, как если бы они не были невосприимчивы к воздействующим на разум эффектам.","name":"Гипнотизёр"},{"alias":"druid","description":"При произнесении заклинаний, нацеленных на растения или растительных существ, добавьте 1/3 к эффективному уровню заклинателя, но только с целью определения длительности.","name":"Друид"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"hunter","description":"Добавьте 1 ранг навыка к верному растению охотника. Если охотник заменяет свое верное растение, новое верное растение получает эти дополнительные ранги навыков.","name":"Охотник"},{"alias":"rogue","description":"Выберите один тип заклятого врага следопыта (или один подтип в случае гуманоида или потустороннего существа). Плут добавляет 1/2 к своему урону от атаки исподтишка при использовании атаки исподтишка против существ выбранного типа (максимум +3).","name":"Плут"},{"alias":"ranger","description":"Добавьте бонус +1/4 к проверкам инициативы и проверкам Выживания, когда следопыт находится в излюбленной местности.","name":"Следопыт"},{"alias":"sorcerer","description":"При использовании заклинаний чародея/волшебника, которые также находятся в списке заклинаний друида, добавьте 1/3 к эффективному уровню класса, но только с целью определения длительности.","name":"Чародей"},{"alias":"shaman","description":"Добавьте одно заклинание из списка заклинаний друида, которого нет в списке заклинаний шамана, к списку заклинаний, которые он знает. Это заклинание должно быть как минимум на 1 уровень ниже заклинания самого высокого уровня, которое может сотворить шаман.","name":"Шаман"},{"alias":"shifter","description":"Добавьте 1/5 к бонусу естественной брони шифтера, когда он использует «Природный облик» для принятия высшей формы аспекта.","name":"Шифтер"}],"kind":"race","nameEn":"Ghoran","nameRu":"Горан","physicalDescription":"Типичный горан ростом примерно с человека и имеет похожий силуэт, но на этом их сходство с людьми заканчивается. «Кожа» горана представляет собой сложный слой волокнистых лоз и кожуры с текстурой, похожей на покрытую мхом кору. Лица горан состоят из многослойных лепестков, которые вспыхивают и трепещут по прихоти, что позволяет им имитировать поведение своих потенциальных пожирателей. У них нет недостатка в эмоциях как таковых, но горанские «чувства» первобытны и абстрактны, что делает их совершенно чуждыми большинству не-горанов. Горан может смеяться, улыбаться или повышать голос, но его спутники редко понимают, является ли это проявлением настоящих эмоций или просто более адаптивной эволюцией, предназначенной — как и многие другие аспекты их физиологии — просто для поддержания их жизни. Гораны в значительной степени контролируют свою массу и могут формировать свое тело по своему желанию в пределах основных границ гуманоидного силуэта; эта черта часто производит впечатление шорохов, особенно когда они напуганы или взволнованы. Гораны, которые часто имеют дело с гуманоидами, склонны принимать мужской или женский силуэт в зависимости от своих предпочтений, но пол остается для них текучим и несколько неуловимым понятием — эволюционная адаптация более важна для комфорта их спутников, чем для самих горан. Горан имеет глубокую полость в животе, в которой находится одно семя размером со сжатый человеческий кулак. Примерно каждые 20 лет тело горана становится достаточно дряхлым, чтобы больше не функционировать. Горан запечатлевает свои способности и воспоминания в этом семени, а затем сажает его в землю. Через 1-2 месяца из семени рождается новое тело горана, сознание из оригинала переходит в полностью выросшее тело и оставляет старое тело в виде безмозглой массы инертной растительной материи. Таким образом, наследие горана живет с каждым отрастанием; в то время как тело регенерирует, внутреннее «я» и воспоминания о прошлом сохраняются.","relations":"Гораны чувствуют себя наиболее комфортно с другими разумными растениями (такими как древни и лиановые лешие) и настороженно относятся к растительноядным существам (включая людей, которые, как известно горанам, создали их как источник пищи). Поскольку их регенерация приносит с собой незначительные изменения личности с каждым воплощением, горанам трудно установить длительные отношения с такими народами, как эльфы, дварфы и гномы. Гораны глубоко не доверяют воинствующим гуманоидам, таким как гоблины и гноллы, особенно склонным к пиромании. Отношения горанов с человечеством самые сложные, поскольку, хотя они восхищаются людьми за их способности и благодарны за их создание, они очень боятся аппетитов людей, и горанам трудно поверить, что человек не хочет их просто съесть.","slug":"ghoran","society":"Инопланетный мыслительный процесс горана (не говоря уже о пустых отверстиях на его лепестковом лице, приблизительно равных его глазам и рту) очень затрудняет понимание и сочувствие другими народами, заставляя многих горанов держаться в сегрегированных сообществах космополитических и богатых магией городов-государств или в самых глубоких диких местах своей бесплодной родины и соседних королевств. Горанская архитектура представлена круглыми многоэтажными тепличными башнями, состоящих из волокнистого растительного материала, покрытого органическими смолами, которые придают им твердость камня. У башен нет крыш и несколько широких стилизованных окон, дающих колонии горанов, живущих поблизости, широкий доступ к жизненно важным лучам солнца. Внутри воздух наполнен органическими ароматами, которые часто вызывают у не-горанов усыпляющее воздействие, делая их податливыми к предложениям горанов и не стремящимися к агрессивным действиям. Гораны, принадлежащие к одной и той же колонии, если их не наблюдать, иногда выстраиваются вокруг краев внутренних балконов башни, синхронно покачиваясь в каком-то неслыханном ритме и греясь в общем тепле дневного света.","traits":[{"description":"Гораны выносливы, коварны и стремятся исследовать свои эмоции, но медленно обрабатывают сложные мысли.","name":"+2 Выносливость, +2 Харизма, -2 Интеллект"},{"description":"Гораны имеют тип растение, но отсутствует невосприимчивость к воздействующим на разум эффектам, параличу, яду, полиморфизму, сну и шоку, которые обычно имеет тип.","name":"Растение (Plant)"},{"description":"Гораны - существа среднего размера, что не дает им никаких бонусов или штрафов.","name":"Средний размер (Medium)"},{"description":"Гораны имеют жесткую, грубую кожу.","name":"+2 к естественной броне (+2 Natural Armor)"},{"description":"Гораны получают штраф -2 к Изворотливости и проверкам боевых маневров, чтобы избежать захвата против существа, у которого есть атака укусом со способностью захвата.","name":"Вкусный (Delicious) (Экс)"},{"description":"Гораны со значением Харизмы 11 или выше получают следующие псевдозаклинания: 1/день — обнаружение ядов, вкусные ягоды (создает ягодные почки из собственного тела горана) и очищение еды и питья. Уровень заклинателя равен уровню горана. СЛ для этих заклинаний равна 10 + уровень заклинания + бонус Харизмы горана.","name":"Природная магия (Natural Magic) (Пс)"},{"description":"Действием полного хода горан может извергнуть семя из отверстия в животе. Если посадить в плодородную почву и оставить в покое на 2d6 дней, семя вырастет в здоровую копию исходного горана, за исключением того, что копия может перераспределить все ранги навыков после прорастания. Как только горан извергает это семя, он получает 1 отрицательный уровень и умирает, как только дубликат прорастает. Этот дубликат заменяет предыдущего горана-персонажа.","name":"Семя (Seed) (Экс)"},{"description":"Гораны получают 1d4 пунктов урона Выносливости каждый день, когда они не подвергаются воздействию солнечного света.","name":"Светозависимый (Light Dependent)"},{"description":"Гораны хранят воспоминания, закодированные в их семенах. Они рассматривают все навыки Знания как классовые навыки.","name":"Знание прошлых жизней (Past-Life Knowledge) (Экс)"},{"description":"Гораны начинают игру, говоря на всеобщем и сильване. Гораны с высоким показателем Интеллекта могут изучить любые дополнительные языки (кроме тайных, таких как друидический).","name":"Языки (Languages)"}]},{"alignmentAndReligion":"Обычно нейтральное.","book":"Inner Sea World Guide","description":"Загадочные и скрытные рыболюды (известные также как низшие ацланти) являются подводными потомками исчезнувшего народа ацланти. Когда на Голарион о6рушилось Низвержение и континент Ацлант раскололся, большая часть поселений анланти сгорела или ушла под воду. Но некоторым жителям пришли на помощь их же враги - аболеты. По непонятным причинам (но явно не из милосердия) аболеты спасли небольшую часть тонущих людей и деформировали их тела, чтобы те могли жить в подводном мире, где прежде безраздельно царствовали аболеты. Правда, после этого аболеты, похоже, утратили интерес к своим творениям, и с тех пор вот уже несколько тысяч лет рыболюды живут самостоятельно.","favoredClass":[{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"}],"kind":"race","nameEn":"Gillman","nameRu":"Рыболюд","physicalDescription":"Из воды выходит красивый, хорошо сложенный мужчина. Внешне рыболюды напоминают своих предков: у них высокие выразительные брови, бледная кожа, темные волосы и ярко-фиолетовые глаза. На шее с двух сторон видно по три жаберные щели. Но рыболюды достаточно похожи на людей, чтобы на время сойти за человека, не опасаясь разоблачения.","slug":"gillman","traits":[{"description":"Рыболюды используют уровни в классах - у них нет КЗ народа","name":""},{"description":"Рыболюды красивы и полны сил, но жизнь под властью аболетов сделала их слабовольными.","name":"+2 Выносливость, +2 Харизма, -2 Мудрость"},{"description":"Рыболюды имеют подводный подтип, но могут дышать как на суше, так и под водой. Однако они не любят надолго покидать воду, поскольку их кожа быстро сохнет.","name":"Амфибии"},{"description":"телу рыболюда требуется постоянное пребывание в пресной или соленой воде. Рыболюду, пробывшему более 1 дня без полного погружения в воду, грозит отказ внутренних органов, болезненное растрескивание кожи и смерть в течение 4d6 часов.","name":"Зависимость от воды (Экс)"},{"description":"рыболюды служат непостижимым замыслам аболетов. Но пока рыболюд не нарушает приказы своих хозяев-аболетов (о чем он не всегда знает заранее, поскольку приказы спрятаны в памяти и активируются в ответ на определенные события), он волен действовать как пожелает. В ходе игры такие приказы остаются целиком на усмотрение ведущего, то есть игрок отчасти уступает ведущему контроль над своим персонажем-рыболюдом, когда это нужно для сюжета.","name":"Прислужник"},{"description":"рыболюд получает бонус +2 (народ) к испытаниям против неаболетских заклинаний и эффектов очарования, но штраф -2 к испытаниям против таких же эффектов и заклинаний аболетов.","name":"Устойчивость к очарованию (Экс)"},{"description":"рыболюды начинают игру со знанием всеобщего и аболетского. Рыболюды с высоки значением Интеллекта могут выбрать дополнительные языки из следующего списка: акван, акло, ацланти, драконий, сахваджинский или эльфийский.","name":"Языки"}]},{"adventurers":"Гномья страсть к путешествиям делает их прирожденными авантюристами. Они часто отправляются в странствия ради новых впечатлений, ведь нет ничего увлекательнее, чем бессчетные опасности, поджидающие искателей приключений. Гномы компенсируют свою физическую слабость талантом к колдовству и бардовскому искусству.","alignmentAndReligion":"Хотя гномы - неисправимые проказники с неясными мотивациями и странными подходами к любому делу, душа у них редко лежит ко злу. Гномы подвержены бурным всплескам эмоций и лучше всего себя чувствуют на природе. Мировоззрение гномов чаще всего нейтральное доброе, они предпочитают поклоняться богам, ценящим личность и природу, таким как Шелин, Гозрей, Дезна и, все чаще, Кайден Кайлин.","altTraits":[{"description":"Некоторые гномы более академически склонны, чем их родственники. Гномы с этим расовым штрихом получают бонус +2 к любому навыку Знания.","name":"Академик","related":["Увлеченность"]},{"description":"Гномы редко теряют надежду и всегда уверены, что даже безнадежные ситуации сработают. Гномы с этим расовым штрихом получают бонус народа +2 к испытаниям против эффектов страха и отчаяния. Один раз в день, бросив 1 на d20, гном может перебросить и использовать второй результат.","name":"Вечная Надежда","related":["Ненависть","Умение защищаться"]},{"description":"Гномы любят языки и изучают тех, с кем встречаются. Гномы с этим расовым штрихом получают бонус +1 к проверкам Блефа и Дипломатии, и они изучают один дополнительный язык каждый раз, когда увеличивают ранг в навыке Языкознание.","name":"Дар Языков","related":["Ненависть","Умение защищаться"]},{"description":"Гномы изучают языки как в их мирских, так и в сверхъестественных проявлениях. Гномы с этим расовым штрихом добавляют +1 к СЛ заклинаний, которые они произносят с языковым дескриптором, или тех, которые создают глифы, символы или другие магические надписи. Они получают бонус народа +2 к испытаниям против таких заклинаний. Гномы с Харизмой 11 или выше также получают следующие псевдозаклинания: 1/день - Мистическая Метка, Понимание Языков, Сообщение, Чтение Магических Текстов. Уровень заклинателя для этих эффектов равен уровню персонажа.","name":"Магический Лингвист","related":["Сопротивление иллюзиям"]},{"description":"Гномы экспериментируют со всеми видами механических устройств. Гномы с этим расовым штрихом получают бонус + 1 к проверкам Механика и Знание (инженерное дело). Они считаются опытными с любым оружием, которое они создали лично.","name":"Мастер Инженер","related":["Ненависть","Умение защищаться"]},{"description":"Гномы с этим расовым штрихом рассматриваются на один уровень выше при чтении заклинаний с огненным дескриптором, с использованием предоставленных способностей сферы Огня, с использованием сил огненного наследия или раскрытия тайны пламени огня и при определении урона от бомб алхимика, наносящих урон от огня (эта способность не дает гномам раннего доступа к силам, основанным на уровнях, а затрагивает только способности, которые они могут использовать без этой способности). Гномы с Харизмой 11 или выше также приобретают следующие псевдозаклинания: 1/день - Пляшущие Огоньки, Вспышка, Мелкие Фокусы, Сотворить Пламя. Уровень заклинателя для этих эффектов равен уровню гнома; СЛ основана на Харизме.","name":"Пироман","related":["Гномья магия","Сопротивление иллюзиям"]},{"description":"Гномы часто должны защищать свои дома от неестественных или вредных заражений. Гномы с этим расовым штрихом получают +2 бонус уклонения к КБ против аберраций, жиж и паразитов, а также бонус +1 к атакам против них из-за их специальной подготовки.","name":"Страж Природы","related":["Ненависть","Умение защищаться"]}],"book":"Core Rulebook","description":"Гномы происходят из таинственного царства фей - места, где все краски ярче, природа более дикая, а эмоции - ближе к первобытным. Давным-давно некая сила изгнала гномов из этого царства, заставив искать убежища в мире людей. Несмотря на прошедшие века, гномы не разорвали окончательно своей связи с миром фей и так и не адаптировались к обществу смертных. В результате гномы широко известны среди других народов как существа чуждые и странные.","favoredClass":[{"alias":"alchemist","description":"Добавьте +1/2 к числу бомб в день, которое может создать алхимик.","name":"Алхимик"},{"alias":"bard","description":"Добавьте 1 к общему количеству раундов выступления бардов в день.","name":"Бард"},{"alias":"witch","description":"Ведьма получает 1/6 нового наговора ведьмы.","name":"Ведьма"},{"alias":"wizard","description":"Добавьте +1/2 к числу использований в день способности школы. Это увеличение относится только к магическим силам школы, доступным на 1-м уровне и обычно используемым количество раз в день, равное 3 + модификатор Интеллекта волшебника.","name":"Волшебник"},{"alias":"druid","description":"Получает устойчивость 1 к кислоте, огню, холоду или электричеству. Когда друид выбирает этот бонус, увеличьте устойчивость к одной из стихий на 1 (максимум 10 для любой стихии).","name":"Друид"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"vigilante","description":"Добавьте +1/2 к проверкам Блефа при попытке сказать ложь, которая была бы правдой с точки зрения текущей личности линчевателя.","name":"Линчеватель"},{"alias":"oracle","description":"Считайте уровень гнома на +1/2 выше, чтобы определить эффект проклятия оракула.","name":"Оракул"},{"alias":"rogue","description":"Гномы-плуты получают бонус +1 к проверкам Механика и Использование Магических Устройств, связанных с символами, свитками и другими магическими надписями, каждый раз, когда получают уровень плута.","name":"Плут"},{"alias":"summoner","description":"Добавьте +1 к Пунктам Здоровья Эйдолона.","name":"Призыватель"},{"alias":"ranger","description":"Добавьте СУ 1/магия к животному-компаньону следопыта. Каждый раз, когда следопыт выбирает это преимущество, СУ/магия увеличивается на +1/2 (максимум СУ 10/магия). Если гном когда-либо заменяет своего животного-компаньона, новый компаньон получает этот СУ.","name":"Следопыт"},{"alias":"shaman","description":"Шаман получает 1/6 нового наговора шамана.","name":"Шаман"},{"alias":"shifter","description":"Дает 1 сопротивление энергии против кислоты, холода, электричества или огня. Каждый раз, когда шифтер выбирает этот бонус, увеличьте это сопротивление на 1, до максимума в 10. Если этот бонус берется уже при условии, что получено 10 единиц сопротивления таким способом, выберите другой тип энергии и увеличивайте сопротивление к нему.","name":"Шифтер"}],"kind":"race","nameEn":"Gnome","nameRu":"Гном","names":[{"isMale":true,"name":"Аброштор"},{"isMale":true,"name":"Бастаргри"},{"isMale":true,"name":"Зарзукет"},{"isMale":true,"name":"Затквальми"},{"isMale":true,"name":"Крольмнит"},{"isMale":true,"name":"Пошмент"},{"isMale":true,"name":"Халунгалом"},{"isMale":false,"name":"Беш"},{"isMale":false,"name":"Квек"},{"isMale":false,"name":"Лини"},{"isMale":false,"name":"Неджи"},{"isMale":false,"name":"Маджит"},{"isMale":false,"name":"Пай"},{"isMale":false,"name":"Триг"},{"isMale":false,"name":"Фиджит"}],"physicalDescription":"Гномы - один из самых низкорослых народов, их рост чуть выше 3 футов. Их волосы обычно очень яркого цвета: оранжевые, как осенние листья; зеленые, как листва весной; темно-красные или пурпурные, как распустившиеся цветы. Варьируется и цвет кожи - от коричнево-земляного до цветочно-розового без особой связи с наследственностью. Гномы сильно отличаются друг от друга чертами лица, у них часто встречаются очень большие глаза или рты, что в одном случае может выглядеть пугающе, а в другом - привлекательно.","relations":"Гномы испытывают трудности во взаимодействии с другими народами как на эмоциональном, так и на физическом уровне. Гномий юмор плохо переводится и часто воспринимается посторонними как злобный или абсурдный, ну а сами они воспринимают другие народы как скучных и неуклюжих великанов. Гномы хорошо ладят с полуросликами и людьми, но любят пошутить над дварфами и полуорками, считая их слишком мрачными. Они уважают эльфов, но эльфийская медлительность в принятии решений часто выводит их из себя. Для гномов действие всегда лучше бездействия, и многие из них носят с собой незавершенные устройства, чтобы было чем развлечься на отдыхе.","slug":"gnome","society":"В отличие от большинства народов, гномы не имеют четкой общественной структуры. Гномы по природе существа переменчивые и обычно странствуют в одиночку или с временными попутчиками в поисках новых волнующих приключений. У них редко складываются длительные отношения друг с другом или с представителями других народов. Зачастую гномы занимаются работой или коллекционированием с рвением, граничащим с фанатизмом. Мужчины у гномов имеют странное пристрастие к необычным шляпам и другим головным уборам, тогда как женщины гордо демонстрируют сложные и эксцентричные прически.","traits":[{"description":"Гномы физически слабы, но на удивление выносливы, а особый взгляд на мир делает их приятнее в общении.","name":"+2 Выносливость, +2 Харизма, -2 Сила"},{"description":"Гномы - существа небольшого размера, поэтому они получают +1 (размер) к КБ, +1 (размер) к атакам, -1 к МБМ и ЗБМ и +4 (размер) к проверкам Скрытности.","name":"Небольшой размер"},{"description":"Базовая скорость гномов - 20 футов.","name":"Низкая скорость"},{"description":"Гномы видят в сумерках вдвое дальше людей.","name":"Сумеречное зрение"},{"description":"Гномы получают +4 (уклонение) к КБ от атак противников с подтипом «великан».","name":"Умение защищаться"},{"description":"СЛ испытаний против заклинаний школы иллюзии, сотворенных гномами, повышается на +1. Гномы с Харизмой 11 и выше также получают возможность творить раз в день следующие псевдозаклинания: мелкие фокусы, пляшущие огоньки, призрачный звук, разговор с животными. УЗ для этих эффектов равен общему уровню гнома, а СЛ испытаний против них равна 10 + круг заклинания + модификатор Харизмы гнома.","name":"Гномья магия"},{"description":"Гномы получают +1 (народ) к атакам по гуманоидам с подтипами «рептилоид» или «гоблиноид», так как обучены сражаться против своих кровных врагов.","name":"Ненависть"},{"description":"Гномы получают +2 (народ) к испытаниям против заклинаний и эффектов школы иллюзии.","name":"Сопротивление иллюзиям"},{"description":"Гномы получают +2 (народ) к проверкам Внимания.","name":"Острые чувства"},{"description":"Гномы получают +2 (народ) к проверкам навыка одного Ремесла или Профессии по своему выбору.","name":"Увлеченность"},{"description":"Любое оружие со словом «гномий» в наименовании относится к категории особого оружия для представителей этого народа.","name":"Оружие гномов"},{"description":"Гномы начинают игру со знанием всеобщего, гномьего и сильван. Гномы с высоким значением Интеллекта могу выбрать дополнительные языки из следующего списка: великаний, гоблинский, дварфийских, драконий, орочий, эльфийский.","name":"Языки"}]},{"alignmentAndReligion":"Обычно нейтральное злое.","book":"Bestiary 1","description":"Гоблины предпочитают жить в пещерах, среди высоких и густых зарослей чертополоха и колючих кустарников или в заброшенных зданиях, построенных другими существами, - у самих гоблинов редко возникает желание строить что-то самостоятельно. Гоблины любят побережье - вода приносит много хлама и обломков, в которых они самозабвенно копаются, надеясь найти сокровища в мусоре, оставленном более цивилизованными народами. Гоблины ненавидят практически всё, но особенно гномов (которые издавна сражались с гоблинами), лошадей (которые пугают гоблинов до чёртиков) и обычных собак (которые, по мнению гоблинов, представляют собой жалкую пародию на гоблиновых собак). Гоблины очень суеверны и испытывают к магии раболепную смесь страха и восхищения. Они имеют привычку приписывать магические свойства самым обычным вещам, например огню и письменности, которые в глазах гоблинов обладают мистической силой. Огонь гоблины любят, ведь он способен причинять огромный вред и не требует для обращения с ним ни особой силы, ни размера, а вот письменность терпеть не могут. Гоблины уверены, что письмо крадёт слова из головы, и в результате этого суеверия все гоблины сплошь безграмотны. Эти существа прожорливы и способны каждый день съедать столько же, сколько весят сами, при этом не толстея, так что в логове гоблинов обязательно найдётся множество кладовок и погребов. Гоблины предпочитают мясо людей и гномов, но едят всё что угодно, за исключением, пожалуй, овощей.","favoredClass":[{"alias":"witch","description":"Добавьте одно заклинание из списка заклинаний ведьмы к фамильяру ведьмы. Это заклинание должно быть, как минимум на один уровень ниже самого высокого уровня заклинания, которое она может сотворить. Если ведьма заменит своего фамильяра, новый фамильяр будет знать эти дополнительные заклинания.","name":"Ведьма"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"}],"kind":"race","nameEn":"Goblin","nameRu":"Гоблин","physicalDescription":"Это существо ростом всего три фута, а его щуплое тельце выглядит совсем маленьким по сравнению с несуразно массивной головой.","slug":"goblin","traits":[{"description":"Гоблины используют уровни в классах - КЗ народа у них нет.","name":""},{"description":"гоблины быстрые, но слабые, и рядом с ними неприятно находиться.","name":"-2 Сила, +4 Ловкость, -2 Харизма"},{"description":"гоблины - существа небольшого размера, поэтому они получают +1 (размер) к КБ, +1 (размер) к атакам, -1 к МБМ и ЗБМ и +4 (размер) к проверкам Скрытности.","name":"Небольшой размер"},{"description":"невзирая на размер, гоблины очень быстры, их базовая скорость - 30 футов.","name":"Быстрый"},{"description":"гоблины могут видеть в темноте на расстоянии до 60 футов.","name":"Ночное зрение"},{"description":"+4 (народ) к проверкам Верховой езды и Скрытности.","name":"Умелый"},{"description":"гоблины начинают игру со знанием гоблинского языка. Гоблины с высоким значением Интеллекта могут выбрать дополнительные языки из следующего списка: всеобщий, гнолльский, гномий, дварфийский, драконий, орочий, полуросличий.","name":"Языки"}]},{"alignmentAndReligion":"Обычно нейтральное.","book":"Bestiary 2","description":"Эти маленькие разумные гуманойдные древесные лягушки живут примитивными сообществами глубоко в лесах и болотах всего мира. К их рациону можно отнести гигантских насекомых, на которых они охотятся, и фрукты с цветами, которые они собирают с деревьев, являющихся их домом. Они часто торгуют с более продвинутыми расами с целью обмена на металл и украшения из драгоценных камней. Гриппли достигают зрелого возраста в течении первого года жизни. Они способны достичь возраста 60 лет, если только джунгли не поглотят раньше. С возрастом их кожа тускнеет и теряет было величие.","favoredClass":[{"alias":"witch","description":"Добавьте 1/3 к СЛ испытания против яда фамильяра ведьмы.","name":"Ведьма"},{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"shaman","description":"Добавьте 1 заклинание из списка заклинаний друида, которого нет в списке заклинаний шамана, к списку заклинаний, которые знает шаман. Заклинание должно быть хотя бы на 1 круг меньше максимального круга, который может применять шаман.","name":"Шаман"}],"kind":"race","nameEn":"Grippli","nameRu":"Гриппли","physicalDescription":"Скользкая кожа, пестрящая узорами ярких красок. Этот проворный лягушкоподобный гуманойд носит при себе лук и облачен в кожаные доспехи. Гриппли перемещаются на двух лапах и весят в среднем 15 килограмм.","slug":"grippli","traits":[{"description":"Гриппли используют уровни в классах - КЗ народа у них нет.","name":""},{"description":"Гриппли быстры и очень внимательны, но хлипкие.","name":"+2 к Ловкости, +2 к Мудрости, -2 к Силе"},{"description":"Гриппли - существа небольшого размера, поэтому они получают +1 (размер) к КБ, +1 (размер) к атакам, -1 к МБМ и ЗБМ и +4 (размер) к проверкам Скрытности.","name":"Небольшой размер"},{"description":"Гриппли имеют базовую скорость передвижения 30 футов и карабкаются со скоростью 20 футов.","name":"Быстроногий"},{"description":"Гриппли видят в темноте на расстоянии 60 футов.","name":"Ночное зрение"},{"description":"+4 к Скрытности в болотах и лесной среде.","name":"Камуфляж"},{"description":"Гриппли не имеют штрафов при перемещении по неудобной поверхности пока они идут по болоту. Магически созданная местность влияет на Гриппли как обычно.","name":"Болотный гуляка"},{"description":"Гриппли искусно владеют сетями.","name":"Опыт с оружием"},{"description":"Гриппли разговаривают на общем языке и языке гриппли. Гриппли с высоким показателем Интеллекта могут выбрать следующие языки: боггардский, драконий, эльфийский, гномий, гоблинксий, сильван.","name":"Языки"}]},{"adventurers":"Полуэльфы - бродяги, странствующие в поисках края, который они могли бы назвать домом. Желание проявить себя перед обществом, отвоевать себе в нем место, а может быть, и оставить свой след в истории толкает многих из них на подвиги.","alignmentAndReligion":"Отчуждение сильно влияет на характер и философию полуэльфов. Жестокость им не свойственна, так же как и стремление смешаться с толпой, стать как все и следовать общим правилам. Как результат, мировоззрение большинства полуэльфов - хаотичное доброе. Из-за отсутствия у полуэльфов единой кудьтуры они реже обращаются к религии, но те, кто делает это, обычно поклоняются богам, популярным на их родине.","altTraits":[{"description":"Смешанная родословная некоторых полуэльфов делает их устойчивыми к умственным атакам. Полуэльфы с этим расовым штрихом получают бонус +2 к испытаниям Воли.","name":"Двойственное Отношение","related":["Приспособляемость"]},{"description":"Некоторые полуэльфы рождаются от эльфов, приспособленных к жизни на воде или рядом с ней. Эти полуэльфы получают расовый бонус +4 к проверкам Плавания, всегда могут взять 10 во время плавания и могут выбрать Акван в качестве дополнительного языка.","name":"Дитя Воды","related":["Приспособляемость","Разносторонний"]},{"description":"Многие полуэльфы искусны встраивать себя в сообщество, как если бы они были аборигенами. Полуэльфы с этим расовым штрихом получают бонус +1 к проверкам Блефа, Маскировки и Знаний (краеведение).","name":"Интегрированность","related":["Приспособляемость"]},{"description":"Полуэльфы умеют очаровывать других. Если полуэльфы с этим расовым штрихом пытаются изменить отношение существа с проверкой Дипломатии и терпят неудачу на 5 или более, они могут попытаться воздействовать на существо второй раз, даже если не прошло 24 часа.","name":"Общительный","related":["Приспособляемость"]},{"description":"Некоторые полуэльфы обучаются необычному оружию. Полуэльфы с этим расовым штрихом получают Обращение с экзотическим оружием или Обращение с особым оружием с одним оружием в качестве дополнительной черты на 1-м уровне.","name":"Родовое Оружие","related":["Приспособляемость"]},{"description":"Полуэльфы иногда ищут учителей, чтобы помочь им овладеть магией в своей крови. Полуэльфы с этим расовым штрихом имеют только один избранный класс, и это должен быть класс Мистических заклинателей. Они могут использовать триггер заклинания и предметы для завершения заклинания для своего избранного класса, как будто на 1 уровень выше (или как персонаж 1-го уровня, если у них нет уровней в этом классе).","name":"Тайное Обучение","related":["Разносторонний"]}],"book":"Core Rulebook","description":"С давних времен эльфы притягивали к себе завистливые взгляды прочих народов. Их невероятное долголетие, способность к магии и врожденная грация пробуждали в соседях либо восхищение, либо жгучую зависть. Людей же более всего очаровывала эльфийская красота. Со времен первых контактов люди считали эльфов образцом физического совершенства, видя в дивном народе идеализированную версию самих себя. В свою очередь, многие эльфы также испытывают влечение к людям: несмотря на варварские обычаи, молодой народ очаровывает их энергией и страстью, с которыми проживает свой недолгий век. Иногда взаимный интерес перерастает в романтические отношения, и хотя подобные связи обычно оказываются краткими даже по человеческим меркам, результатом частенько становится рождение полуэдьфа - потомка двух народов, которого не признают ни те, ни другие. Полуэльфы могут вступать в брак с себе подобными, но даже их «»чистокровные‎ дети-подуэльфы воспринимаются как изгои и людьми, и эльфами.","favoredClass":[{"alias":"bard","description":"Добавьте 1 к общему числу раундов бардовского исполнения в день.","name":"Бард"},{"alias":"witch","description":"Добавьте одно заклинание из списка заклинаний ведьмы к фамильяру ведьмы. Это заклинание должно быть, как минимум на один уровень ниже самого высокого уровня заклинания, которое она может сотворить. Если ведьма заменит своего фамильяра, новый фамильяр будет знать эти дополнительные заклинания.","name":"Ведьма"},{"alias":"fighter","description":"Добавьте +1 к ЗБМ воина, когда сопротивляетесь разоружению или захвату.","name":"Воин"},{"alias":"druid","description":"Выберите одну силу сферы жреца на 1-м уровне, которую обычно можно использовать несколько раз в день, равную 3 + модификатор Мудрости друида. Друид добавляет 1/2 к числу использований в день силы этой сферы. Для друидов-полуэльфов, чья природная связь дает им компаньона-животного, добавьте +1 ранг навыка к компаньону-животному. Если полуэльф когда-либо заменяет своего компаньона-животного, новый компаньон получает эти ранги навыков.","name":"Друид"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"vigilante","description":"Добавьте +1/2 к проверкам Маскировки от бесшовного обличья.","name":"Линчеватель"},{"alias":"rogue","description":"Добавьте +1/2 бонуса к проверкам на Блеф к финту и Дипломатии для сбора информации.","name":"Плут"},{"alias":"summoner","description":"Добавьте +1/4 к пулу эволюции эйдолонов.","name":"Призыватель"},{"alias":"ranger","description":"Добавьте +1 пункт навыка к животному-компаньону рейнджера. Если полуэльф когда-либо заменяет своего компаньона, новый компаньон получает эти бонусные пункты навыков.","name":"Следопыт"},{"alias":"shaman","description":"Добавьте 1 заклинание из списка заклинаний жреца, которого нет в списке заклинаний шамана, к списку заклинаний, которые знает шаман. Заклинание должно быть хотя бы на 1 круг меньше максимального круга, который может применять шаман.","name":"Шаман"},{"alias":"shifter","description":"Добавьте 1/2 к проверкам Выживания, чтобы определить направление ветра, не потеряться и избежать любых естественных угроз.","name":"Шифтер"}],"kind":"race","nameEn":"Half-Elf","nameRu":"Полуэльф","names":[{"isMale":true,"name":"Зирал"},{"isMale":true,"name":"Кайрас"},{"isMale":true,"name":"Калафес"},{"isMale":true,"name":"Квайрэй"},{"isMale":true,"name":"Нарцисо"},{"isMale":true,"name":"Селтиэль"},{"isMale":true,"name":"Сэтиндер"},{"isMale":true,"name":"Энсинал"},{"isMale":false,"name":"Йандоли"},{"isMale":false,"name":"Киэянна"},{"isMale":false,"name":"Кэтрэн"},{"isMale":false,"name":"Лиальда"},{"isMale":false,"name":"Маддела"},{"isMale":false,"name":"Реда"},{"isMale":false,"name":"Тамари"},{"isMale":false,"name":"Элсбет"}],"physicalDescription":"Полуэльфы выше людей, но ниже эльфов. Они наследуют стройность и красоту своих эльфийских предков, а человеческая сторона определяет цвет их кожи. Уши полуэльфов более округлые и менее острые, чем у эльфийских предков. Их глаза похожи на человеческие, но радужка бывает самых разных цветов: от янтарного до фиолетового и от изумрудного до темно-синего.","relations":"Полуэльфы отлично понимают, что такое одиночество, и знают, что жизненный опыт значит больше, чем происхождение. Они открыты к союзам и дружбе с представителями других народов и не склонны судить новых знакомых, полагаясь на первое впечатление.","slug":"halfElf","society":"Отсутствие единой родины и культуры заставляет полуэльфов быть гибкими и приспосабливаться к любому окружению. Несмотря на привлекательность для обоих народов, полуэльфы редко вливаются в людское или эльфийское общество: слишком много «чуждого» видят в них и люди, и эльфы. Подобное неприятие давит тяжелым грузом на плечи многих полуэльфов, но есть среди них и те, кто считает такое положение дел выгодным: отсутствие собственной культуры дарует им абсолютную свободу, чем не может похвастаться никто другой. Полуэльфы - чрезвычайно гибкий народ, способный подстроить свой образ мыслей и таланты под нужды окружения, в котором оказывается.","traits":[{"description":"Персонаж-полуэльф получает +2 к одной характеристике по выбору игрока, что отражает разностороннюю природу этого народа.","name":"+2 к значению одной характеристики"},{"description":"Полуэльфы - существа среднего размера, что не дает им никаких бонусов или штрафов.","name":"Средний размер"},{"description":"Базовая скорость полуэльфов - 30 футов.","name":"Нормальная скорость"},{"description":"Полуэльфы видят вдвое дальше людей в сумерках.","name":"Сумеречное зрение"},{"description":"Полуэльфы получают на 1 уровне дополнительную черту Эксперт в навыке по выбору игрока.","name":"Приспособляемость"},{"description":"Для эффектов, воздействующих на определенный народ, полуэльфы считаются и людьми, и эльфами.","name":"Смешанная кровь"},{"description":"Полуэльфы невосприимчивы к магическому сну и получают +2 (народ) к испытаниям против заклинаний и эффектов школы очарования.","name":"Эльфийский иммунитет"},{"description":"Полуэльфы получают +2 (народ) к проверкам Внимания.","name":"Острые чувства"},{"description":"Полуэльфы выбирают два предпочитаемых класса на 1 уровне и получают 1 пункт навыков или 1 пункт здоровья каждый раз, когда берут уровень в одном из этих классов.","name":"Разносторонний"},{"description":"Полуэльфы начинают игру со знанием эльфийского и всеобщего языков. Полуэльфы с высоким значением Интеллекта могут изучить любые дополнительные языки (кроме тайных, таких как друидический).","name":"Языки"}]},{"adventurers":"Крайне независимые полуорки нередко выбирают жизнь искателей приключений по необходимости, надеясь порвать со своим тяжелым прошлым или стремясь силой вырвать у судьбы лучшую долю. Те из них, кто больше уверен в себе или отчаянно жаждет признания, избирают путь героев, чтобы доказать всему миру, чего они стоят.","alignmentAndReligion":"Жизнь изгоя - что среди грубых орков, что в цивилизованных землях - зачастую превращает полуорка в озлобленного и жестокого одиночку. Они легко становятся злыми, хотя по натуре таковыми не являются. Мировоззрение большинства полуорков хаотичное нейтральное, так как они на своем опыте знают, что нет смысла браться за то, что не сулит выгоды лично тебе. Если они утруждают себя религией, то предпочитают божеств, связанных с войной и личным могуществом, таких как Горум, Кайден Кайлин, Ламашту или Ровагут.","altTraits":[{"description":"Некоторые полуорки сбежали из рабства и превратили цепи своего заключения в смертоносное оружие. Полуорки с этим расовым штрихом могут обращаться с Цепами и тяжелыми Цепами, и относятся к Двусторонним цепам и Шипастой цепи как к боевому оружию.","name":"Боец Цепей","related":["Оружие орков"]},{"description":"Кровь орков некоторых полуорков проявляется в форме особенно выдающихся черт орков, усиливая их звериный облик, но улучшая их и без того острые чувства. Они получают расовый бонус +2 к проверкам Внимания.","name":"Звероподобный","related":["Орочья свирепость"]},{"description":"Некоторые рудиментарные клыки полуорка массивные и острые, что дает атаку укусом. Это первичная естественная атака, которая наносит 1d4 пунктов колющего урона.","name":"Зубастый","related":["Орочья свирепость"]},{"description":"Многие полуорки наслаждаются актами бессмысленного уничтожения. Полуорки с этим расовым штрихом получают +2 бонус на проверки Силы, чтобы разбить объекты и +2 бонус на попытки Разрушения.","name":"Крушитель","related":["Орочья свирепость"]},{"description":"Некоторые полуорки роются в кучах мусора и должны научиться отделять редкие находки от неизбежного шлака. Полуорки с этим расовым штрихом получают расовый бонус +2 на проверки Оценки и проверки Внимания, чтобы найти скрытые объекты (включая ловушки и секретные двери), определить, испорчена ли еда, или идентифицировать зелье по вкусу.","name":"Мусорщик","related":["Устрашающий вид"]},{"description":"Некоторые полуорки живут далеко от поверхности, ища утешения в извилистых пещерных комплексах. Полуорки с этим расовым штрихом получают бонус +1 к проверкам Знаний (подземелий) и Выживания, сделанным под землей.","name":"Пещерный Дух","related":["Устрашающий вид"]},{"description":"Некоторые полуорки имеют духовное родство с фантастическими животными, захватив их для спорта или жизни и охоты с ними. Полуорк с этой чертой рассматривает кнут и сеть как боевое оружие и получает бонус +2 к проверкам Дрессировки.","name":"Повелитель Зверей","related":["Орочья свирепость"]},{"description":"Татуировки, пирсинг и ритуальное шрамирование являются священными знаками для многих полуорков. Полуорки с этим расовым штрихом получают бонус +1 к удаче ко всем испытаниям.","name":"Священная Татуировка","related":["Орочья свирепость"]},{"description":"Полуорки из горных районов - отличные альпинисты, а иногда устраивают засаду, спрыгивая сверху. Полуорки с этим расовым штрихом получают бонус +1 на проверки Акробатики и Лазания.","name":"Скалолаз","related":["Устрашающий вид"]},{"description":"Полуорки иногда вынуждены жить на прогорклых и антисанитарных окраинах общества, становясь приученными ко всем видам болезней. Полуорки с этим расовым штрихом получают расовый бонус +2 к испытаниям против болезней, проглатываемых ядов, Тошноте или Дезориентации.","name":"Чумной Ребенок","related":["Орочья свирепость","Устрашающий вид"]}],"book":"Core Rulebook","description":"Полуорки - уроды, трагический, противоестественный результат насилия... По крайней мере, так о них думают другие народы. Полуорки действительно редко появляются от союзов по любви, поэтому детство их проходит трудно, а взросдение начинается рано - им постоянно приходится отстаивать право на жизнь и доброе имя. Им не доверяют, их унижают, их боятся, но полуорки регулярно удивляют своих притеснителей великими деяниями и неожиданной мудростью. Хотя иногда, конечно, было бы проще расколоть пару черепов.","favoredClass":[{"alias":"alchemist","description":"Добавьте +1/2 к урону от бомбы.","name":"Алхимик"},{"alias":"barbarian","description":"Добавь 1 к общему числу раундов ярости в день.","name":"Варвар"},{"alias":"witch","description":"Добавьте +1 пункт навыку фамильяра ведьмы. Если полуорк заменяет своего фамильяра, новый фамильяр получает эти дополнительные пункты навыков.","name":"Ведьма"},{"alias":"fighter","description":"Добавьте +2 к броскам на первую помощь при смерти.","name":"Воин"},{"alias":"inquisitor","description":"Добавьте +1/2 к проверкам Запугивание и проверкам Знания для опознания существ.","name":"Инквизитор"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"vigilante","description":"Добавьте 1/2 к увеличению СЛ от непоколебимости.","name":"Линчеватель"},{"alias":"ranger","description":"Добавьте +1 к очкам жизни животного-компаньона. Если полуорк когда-либо заменит своего компаньона-животного, новый компаньон-животное получает эти бонусные очки жизни.","name":"Следопыт"},{"alias":"sorcerer","description":"Добавьте +1/2 к урону от заклинаний огня.","name":"Чародей"},{"alias":"shaman","description":"Добавьте 1 заклинание из списка заклинаний жреца, которого нет в списке заклинаний шамана, к списку заклинаний, которые знает шаман. Заклинание должно быть хотя бы на 1 круг меньше максимального круга, который может применять шаман.","name":"Шаман"},{"alias":"shifter","description":"Добавьте 1/3 к результату при подтверждении критического удара при использовании «когтей шифтера» (максимум 5). Не суммируется с Критической точностью.","name":"Шифтер"}],"kind":"race","nameEn":"Half-Orc","nameRu":"Полуорк","names":[{"isMale":true,"name":"Дейвор"},{"isMale":true,"name":"Киззиар"},{"isMale":true,"name":"Макоа"},{"isMale":true,"name":"Нестерук"},{"isMale":true,"name":"Оск"},{"isMale":true,"name":"Хакак"},{"isMale":true,"name":"Цадок"},{"isMale":false,"name":"Ганан"},{"isMale":false,"name":"Горуза"},{"isMale":false,"name":"Дрогеда"},{"isMale":false,"name":"Зельжка"},{"isMale":false,"name":"Мазон"},{"isMale":false,"name":"Тевага"},{"isMale":false,"name":"Шириш"}],"physicalDescription":"Полуорки обоих полов имеют рост от 6 до 7 футов, мощное телосложение и сероватую или зеленоватую кожу. Их клыки часто вырастают настолько длинными, что торчат изо рта, и это, в сочетании с низким лбом и слегка заостренными ушами, делает внешность полуорка звероподобной. Внешность полуорка может быть впечатляющей, но мало кто назовет их красивыми.","relations":"Постоянные гонения делают полуорков недоверчивыми и гневливыми, но те же, кто сумеет пробиться сквозь налет внешней грубости, могут найти в душе полуорка сочувствие и понимание. Эльфы и дварфы наименее терпимы к полуоркам, находя в них слишком много общего со своими кровными врагами. Впрочем, остальные народы в этом вопросе недалеко от них ушли. Человеческие поселения, не испытывающие проблем с орками, воспринимают полуорков лучше всего, и здесь полукровка часто может сделать карьеру наемника или стражника.","slug":"halfOrc","society":"В отличие от полуэльфов, неприязнь к которым отчасти проистекает из зависти, полуоркам не позавидуешь: от обеих рас они унаследовали худшее. Уступая в силе своим родичам-оркам, они вызывают в окружающих такой же страх. На полукровок частенько нападают, не видя особой разницы между ними и настоящими орками. Тем не менее в цивилизованном обществе полуорков если и не принимают полностью, то по крайней мере уважают за боевые качества. Известны случаи, когда орочьи вожаки намеренно плодили полуорков, зная, что недостаток силы те компенсируют хитростью и агрессивностью, а значит, отлично подходят на роль полководцев и военных советников.","traits":[{"description":"Персонаж-полуорк получает +2 к одной характеристике по выбору игрока, что отражает разностороннюю природу этого народа.","name":"+2 к значению одной характеристики"},{"description":"Полуорки - существа среднего размера, что не дает им никаких бонусов или штрафов.","name":"Средний размер"},{"description":"Базовая скорость полуорков - 30 футов.","name":"Нормальная скорость"},{"description":"Полуорки видят в темноте на 60 футов.","name":"Ночное зрение"},{"description":"Полуорки получают +2 (народ) к проверкам Запугивания благодаря своему грозному виду.","name":"Устрашающий вид"},{"description":"Для любых эффектов, воздействующих на определенный народ, полуорки считаются и людьми, и орками.","name":"Смешанная кровь"},{"description":"Раз в день, если ПЗ полуорка опустились ниже 0, но он не погиб, он может продолжить сражаться еще один раунд, как если бы был едва жив. К концу своего следующего хода полуорк немедленно теряет сознание и оказывается при смерти, если он не восстановил ПЗ.","name":"Орочья свирепость"},{"description":"Все полуорки умеют пользоваться двуручными топорами и фальшионами; любое оружие со словом «орочий» в наименовании относится к категории особого оружия для представителей этого народа.","name":"Оружие орков"},{"description":"Полуорки начинают игру со знанием всеобщего и орочьего языков. Полуорки с высоким значением Интеллекта могут выбрать дополнительные языки из следующего списка: великаний, гнолльский, гоблинский, демонический, драконий.","name":"Языки"}]},{"adventurers":"Врожденное везение вкупе с ненасытной жаждой странствий делает полуросликов идеальными искателями приключений. Другие бродяги часто присоединяются к маленьким непоседам в надежде, что и им перепадет часть знаменитой удачи полуросликов.","alignmentAndReligion":"Полурослики верны своей семье и друзьям, но, так как мир вокруг населен существами по меньшей мере вдвое большими по росту, они принимают как факт, что для выживания иногда приходится воровать и попрошайничать. По этой причине мировоззрение большинства полуросликов нейтральное. Из богов они почитают тех, кто покровительствует маленьким сплоченным сообществам, будь то добрые божества (например, Эрастил) или злые (Норгорбер).","altTraits":[{"description":"Полурослики являются экспертами в использовании пращи. Полурослики с этим расовым штрихом могут перезарядить пращу как свободное действие. Перезарядка пращи все еще требует двух рук и провоцирует внеочередную атаку.","name":"Военный Пращник","related":["Проворный"]},{"description":"Некоторые полурослики специализируются в конном бою. Полурослики с этим расовым штрихом получают бонус +2 к проверкам Дрессировка и Верховая езда.","name":"Всадник","related":["Проворный"]},{"description":"В то время как большинство героев бесстрашны, некоторые - пугливые, что делает их особенно бдительными. Полурослики с этим расовым штрихом получают бонус +1 к проверкам Инициативы и +1 бонус к броскам атаки при фланкировании. Они получают штраф -2 на испытания от страха и не получают никакой выгоды от морального бонуса за спасение от страха. При воздействии эффекта страха их базовая скорость увеличивается на 10 футов, и они получают +1 бонус уклонения к классу брони.","name":"Опасливый","related":["Бесстрашный","Удача полурослика"]},{"description":"Полурослик должен упорно тренироваться, чтобы эффективно бороться с противником выше него. Полурослики с этим расовым штрихом получают бонус уклонения +1 к КБ против противников, которые больше их самих, и бонус +1 к испытаниям Реакции, чтобы избежать атак Затаптыванием","name":"Под Ногами","related":["Удача полурослика"]},{"description":"Полуросликам помогает выживать тяжелый труд и здравый смысл. Полурослики с этим расовым штрихом получают бонус +2 к любому навыку Ремесла или Профессии, а также к проверке Проницательности и спасению от иллюзий.","name":"Практицизм","related":["Бесстрашный","Проворный"]},{"description":"Некоторые полурослики интенсивно учатся атаковать более крупных существ. Полурослики с этим расовым штрихом получают бонус +1 к броскам критического подтверждения против противников, которые больше их самих.","name":"Удар Ниже Пояса","related":["Острые чувства"]},{"description":"Полурослики любят путешествия и карты. Полурослики с этим расовым штрихом получают бонус +2 к проверкам Знания (география) и Выживания. При использовании заклинаний или использовании способностей, которые обеспечивают или улучшают движение, полурослики рассматривают уровень заклинателя на +1 выше, чем обычно.","name":"Страсть К Путешествиям","related":["Бесстрашный","Удача полурослика"]},{"description":"Полурослики обладают невероятной скрытностью, даже когда они перемещаются по затрудненной местности. Полурослики с этим расовым штрихом уменьшает штраф за использование Скрытности при движении на 5, и уменьшает штраф за проверку Скрытности за снайперскую стрельбу на 10.","name":"Стремительно, Как Тень","related":["Проворный"]}],"book":"Core Rulebook","description":"Оптимистичные и веселые по натуре, обладающие сверхъестественной удачей и движимые жаждой странствий полурослики компенсируют свой малый рост избытком хвастовства и любопытства. Они легки на подъем и открыты новому, но не склонны терять голову и всегда готовы подождать более удобного случая. Они не так склонны к вспышкам эмоций или насилия, как более горячие народы. Даже в отчаянном положении полурослик почти никогда не теряет своего чувства юмора. Полурослики - неисправимые охотники за удачей. Будучи неспособны физически защитить себя от сурового окружающего мира, они знают, когда надо плыть по течению, а когда лучше спрятаться. Впрочем, любопытство полуросликов часто берет верх над здравым смыслом, что зачастую ставит их в опасное положение. Хотя любопытство гонит их на поиски новых впечатлений, полурослики любят свой дом и родные места. Из-за этого они часто тратят на домашний уют слишком большие для их кошелька суммы.","favoredClass":[{"alias":"bard","description":"Добавьте +1/2 к проверкам Блефа для передачи секретных сообщений, +1/2 к проверкам Дипломатии для сбора информации и +1/2 к проверкам Маскировка, чтобы выглядеть как эльфийский, полуэльфийский или человеческий ребенок.","name":"Бард"},{"alias":"witch","description":"Добавьте +1/4 к УЗ ведьмы при определении эффектов заклинаний, дарованных ей ее покровителем.","name":"Ведьма"},{"alias":"fighter","description":"Добавьте +1 к ЗБМ воина при сопротивлении захвату или сбить с ног.","name":"Воин"},{"alias":"cleric","description":"Выберите одну силу сферы, предоставленную на 1-м уровне, которая обычно используется количество раз в день, равную 3 + модификатор Мудрости жреца. Жрец добавляет 1/2 к числу использований в день силы этой сферы.","name":"Жрец"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"vigilante","description":"Получите 1/6 нового социального таланта.","name":"Линчеватель"},{"alias":"monk","description":"Добавьте +1 к ЗБМ монаха, когда сопротивляетесь захвату, и +1/2 к числу ошеломляющих атак, которые он может предпринять в день.","name":"Монах"},{"alias":"paladin","description":"Добавьте +1/2 ПЗ к способности паладина Возложение Рук (будь то для излечения или повреждения).","name":"Паладин"},{"alias":"rogue","description":"Выберите оружие из следующего списка: праща, кинжал или любое оружие с «полуросликом» в названии. Добавьте +1/2 бонус обстоятельств к броскам подтверждения критического удара с этим оружием (максимальный бонус +4). Этот бонус не суммируется с Критической точностью.","name":"Плут"},{"alias":"summoner","description":"Добавьте +1 к пунктам навыков эйдолона призывателя.","name":"Призыватель"},{"alias":"ranger","description":"Добавьте +1/3 бонус уклонения к классу брони против избранных врагов.","name":"Следопыт"},{"alias":"shaman","description":"Добавьте 1/2 к эффективному классовому уровню шамана для определения бонуса естественной брони, Интеллекта и специальных способностей его духовного зверя.","name":"Шаман"},{"alias":"shifter","description":"Увеличьте КБ от «Защитного инстинкта» на 1/4 против существ размера Большой или большего.","name":"Шифтер"}],"kind":"race","nameEn":"Halfling","nameRu":"Полурослик","names":[{"isMale":true,"name":"Антал"},{"isMale":true,"name":"Борам"},{"isMale":true,"name":"Джамир"},{"isMale":true,"name":"Калеб"},{"isMale":true,"name":"Лем"},{"isMale":true,"name":"Миро"},{"isMale":true,"name":"Сумак"},{"isMale":true,"name":"Эван"},{"isMale":false,"name":"Анафа"},{"isMale":false,"name":"Беллис"},{"isMale":false,"name":"Лисса"},{"isMale":false,"name":"Марра"},{"isMale":false,"name":"Риллка"},{"isMale":false,"name":"Систра"},{"isMale":false,"name":"Филью"},{"isMale":false,"name":"Этьюн"},{"isMale":false,"name":"Ямира"}],"physicalDescription":"Полурослики вырастают не выше 3 футов. Их широкие загорелые столы сверху покрыты густой курчавой шерстью. Подошва обычно огрубевшая, так как полурослики предпочитают ходить босиком. Их кожа имеет насыщенный миндальный оттенок, а цвет волос чаще всего русый. Уши у них заостренные, но по пропорциям примерно соответствуют человеческим.","relations":"Полурослики гордятся своей способностью не привлекать внимания других народов, Ведь именно она помогает им достичь мастерства в воровстве и обмане. Понимая, что нечестный образ жизни плохо сказывается на их репутации, многие полурослики стараются быть приветливыми и дружелюбными с представителями больших народов, когда хотят, чтобы их заметили. Они хорошо ладят с гномами, хотя и относятся к этим эксцентричным созданиям с изрядной долей осторожности. С людьми полурослики, как правило, вполне уживаются, но бдительности не теряют, памятуя о том, что многие воинственные представители этого народа ценят низкорослых соседей только в качестве рабов. Полурослики уважают эльфов и дварфов, но общаются с ними не слишком часто, поскольку и те и другие живут в регионах, удаленных от цивилизации, благами которой так любит пользоваться этот маленький народец. И только полуорков они избегают: слишком уж большими и страшными кажутся те большинству полуросликов.","slug":"halfling","society":"У полуросликов нет исторической родины и даже собственных земель, не считая горстки вольных городков и деревень. Куда чаще полуросликов можно встретить на задворках крупных людских поселений, где они пробавляются тем, что перепадает им от «старших братьев» - людей. И хотя многих из них вполне устраивает жизнь в тени высокорослых соседей, некоторые полурослики пускаются в странствия, чтобы повидать мир и познать его тайны и чудеса.","traits":[{"description":"Полурослики - ловкие и волевые создания, но из-за малых размеров они слабее прочих народов.","name":"+2 Ловкость, +2 Харизма, -2 Сила"},{"description":"Полурослики - существа небольшого размера, поэтому они получают +1 (размер) к КБ, +1 (размер) к атакам, -1 к МБМ и ЗБМ и +4 (размер) к проверкам Скрытности.","name":"Небольшой размер"},{"description":"Базовая скорость полуросликов - 20 футов.","name":"Низкая скорость"},{"description":"Полурослики получают +2 (народ) ко всем испытаниям против ужаса. Этот модификатор складывается с модификатором за Удачу полурослика.","name":"Бесстрашный"},{"description":"Полурослики получают +1 (народ) ко всем испытаниям.","name":"Удача полурослика"},{"description":"Полурослики получают +2 (народ) к проверкам Внимания.","name":"Острые чувства"},{"description":"Полурослики получают +2 (народ) к проверкам Акробатики и Лазания.","name":"Проворный"},{"description":"Все полурослики умеют пользоваться пращами; любое оружие со словом «полуросличий» в наименовании относится к категории особого оружия для представителей этого народа.","name":"Оружие полуросликов"},{"description":"Полурослики начинают игру со знанием всеобщего и полуросличьего языков. Полурослики с высоким значением Интеллекта могут выбрать дополнительные языки из следующего списка: гномий, гоблинский, дварфийский, эльфийский.","name":"Языки"}]},{"alignmentAndReligion":"Обычно принципиальный злой.","book":"Bestiary 1","description":"Хобгоблины воинственны и плодовиты и поэтому в ряде регионов могут представлять существенную угрозу. Они быстро множатся, заменяя павших новыми солдатами и увеличивая численность, невзирая на потери. Для объявления войны им не нужна особая причина, но зачастую ею является потребность в новых рабах - жизнь пленника хобгоблинов коротка и сурова, поэтому на замену съеденным и погибшим постоянно требуются новые. Из всех гоблиноидов хобгоблины - самые цивилизованные. Более крупные и любящие одиночество багберы для них всего лишь инструмент, используемый по необходимости, в основном для выполнения заданий, требующих от исполнителя скрытности и умения убивать; гоблины же воспринимаются ими как досадные недоразумения. Хобгоблины поражаются гоблинскому упорству, но взбалмошность и чрезмерная любовь гоблинов к огню делают их нежеланными гостями в хобгоблинских поселениях. Несмотря на это, в большинстве племён хобгоблинов есть небольшая группа гоблинов, обитающая в самых убогих уголках. Многие хобгоблинские племена подходят к искусству войны с умом. Большинство этих существ интересуются созданием осадных орудий, алхимией и инженерным делом, а особо умелые индивиды становятся героями и всегда занимают высокое положение в племени. Умные рабы также представляют особую ценность, поэтому набеги на дварфийские города случаются довольно часто. Широко известно, что хобгоблины не доверяют магии, особенно мистической, и даже презирают её. К шаманам относятся со страхом и почтением, но обычно заставляют жить особняком на краю логова. Хобгоблин, практикующий мистическую (или, как её называют хобгоблины, эльфийскую) магию, - исключительнейший случай. Ненависть этих существ к магии - следствие глубочайшей ненависти к эльфам. Рост хобгоблина - 5 футов, а вес - 160 фунтов.","favoredClass":[{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"}],"kind":"race","nameEn":"Hobgoblin","nameRu":"Хобгоблин","physicalDescription":"Это мускулистое серокожее существо ростом с человека внимательно осматривает окрестности крошечными глазами.","slug":"hobgoblin","traits":[{"description":"Хобгоблины используют уровни в классах - КЗ народа у них нет.","name":""},{"description":"Хобгоблины быстрые и крепкие.","name":"+2 Ловкость, +2 Выносливость"},{"description":"Хобгоблины могут видеть в темноте на расстоянии до 60 футов.","name":"Ночное зрение"},{"description":"Хобгоблины получают +4 (народ) к проверкам Скрытности.","name":"Скрытный"},{"description":"Хобгоблины начинают игру со знанием всеобщего и гоблинского языков. Хобгоблины с высоким значением Интеллекта могут выбрать дополнительные языки из следующего списка: великаний, дварфийский, драконий, дьявольский, орочий.","name":"Языки"}]},{"adventurers":"Людским народом движут амбиции, и для многих из них приключения - лишь средство для достижения цели, будь то богатство, слава, положение в обществе или тайные знания. Мало кто ввязывается в авантюры, чтобы просто пощекотать себе нервы. Люди населяют все уголки мира и занимаются всем, чем только возможно, поэтому способны взять на себя любую роль в отряде искателей приключений.","alignmentAndReligion":"Люди - самый неоднородный по мировоззрению народ, способный и на великое добро, и на великое зло. Одни его представители собирают огромные орды варваров, другие возводят раскинувшиеся на мили города. В целом мировоззрение людей нейтральное, но они часто формируют нации и культуры вокруг какого-то конкретного мировоззрения. У людей также наблюдается самое большое разнообразие религий. В отсутствие традиционных для других народов связей с богами люди поклоняются тому, кто обещает им славу или защиту. Они приняли даже таких богов, как Калистрия и Тораг, которые тысячелетиями были связаны с более древними народами. Кроме того, с ростом и процветанием человечества в его пантеоне стали появляться молодые боги, рожденные новыми легендами.","altTraits":[{"description":"Люди обладают большой интуицией и скрытым потенциалом. Они получают бонус +2 к проверкам Проницательности. Кроме того, когда они приобретают компаньона-животного, ездовое животное, последователя или фамильяра, это существо получает бонус +2 к одному показателю способности по выбору персонажа.","name":"Око Таланта","related":["Дополнительная черта"]},{"description":"Люди, родившиеся в сельской местности, привыкли к тяжелому труду. Они получают бонус, равный половине уровня своего персонажа, к любому навыку Ремесла или Профессии, и один раз в день они могут игнорировать эффект, который приведет к их Утомлению или Бессилию.","name":"Сердце Полей","related":["Умелый"]},{"description":"Люди из шумных городов умеют толпиться. Они получают бонус +1 к испытаниям Реакции и бонус (уклонения) +1 к классу брони, если они находятся рядом хотя бы с двумя другими союзниками. Толпы не считаются сложным ландшафтом для них.","name":"Сердце Улиц","related":["Умелый"]},{"description":"Люди, выросшие в дикой природе, учатся выживать и бороться с трудностями, чтобы становится сильнее. Они получают бонус, равный половине уровня персонажа на проверках Выживания. Они также получают бонус +5 к испытаниям Выносливости, чтобы стабилизироваться при смерти, и добавляют половину уровня своего персонажа к своему счету Выносливости при определении общего количества отрицательных очков жизни, необходимого для их убийства.","name":"Сердце Дикой Природы","related":["Умелый"]}],"book":"Core Rulebook","description":"Люди наделены исключительной предприимчивостью, живучестью и плодовитостью, что сделало их самым многочисленным народом мира. Людские империи и государства огромны, а их жители добывают себе славу силой оружия и мощью магии. Энергичность и многообразие - вот главные отличительные черты человеческой культуры, в которой можно встретить и дикие, но благородные племена варваров, и декадентствующих дворян-дьяволопоклонников в огромных многолюдных городах. Человеческое любопытство и амбиции часто берут верх над стремлением к спокойной жизни. Люди часто покидают дома ради исследования новых земель или ведут в завоевательные походы могучие армии просто потому, что могут это сделать.","favoredClass":[{"alias":"alchemist","description":"Добавьте один экстракт из списка алхимика в книгу формул персонажа. Эта формула должна быть как минимум на один уровень ниже самого высокого уровня формул, который может создать алхимик.","name":"Алхимик"},{"alias":"bard","description":"Добавьте одно заклинание, известное из списка заклинаний барда. Это заклинание должно быть, как минимум на один уровень ниже самого высокого уровня заклинания, которое может произнести бард.","name":"Бард"},{"alias":"barbarian","description":"Добавьте +1/2 бонус к чутью на ловушки или +1/3 к бонусу от суеверной силы ярости.","name":"Варвар"},{"alias":"witch","description":"Добавьте одно заклинание из списка заклинаний ведьмы к фамильяру ведьмы. Это заклинание должно быть, как минимум на один уровень ниже самого высокого уровня заклинания, которое она может использовать. Если ведьма заменит своего фамильяра, новый фамильяр будет знать эти дополнительные заклинания.","name":"Ведьма"},{"alias":"fighter","description":"Добавьте +1 к ЗБМ воина, когда будете сопротивляться двум боевым маневрам по выбору персонажа.","name":"Воин"},{"alias":"wizard","description":"Добавьте одно заклинание из списка заклинаний волшебника в книгу заклинаний волшебника. Это заклинание должно быть как минимум на один уровень ниже самого высокого уровня заклинания, которое он может использовать.","name":"Волшебник"},{"alias":"druid","description":"Добавьте +1/2 бонус к проверкам Дипломатии и Запугивания, чтобы изменить отношение существа.","name":"Друид"},{"alias":"cleric","description":"Добавьте +1 к проверкам уровня заклинателя, чтобы преодолеть устойчивость к магии потусторонних существ.","name":"Жрец"},{"alias":"inquisitor","description":"Добавьте одно заклинание, известное из списка заклинаний инквизитора. Это заклинание должно быть, как минимум на один уровень ниже самого высокого уровня заклинания, которое может использовать инквизитор.","name":"Инквизитор"},{"alias":"cavalier","description":"Добавьте +1/4 бонусу знамени кавалериста.","name":"Кавалерист"},{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"},{"alias":"vigilante","description":"Добавьте +1/2 к проверкам Маскировки от бесшовного обличья.","name":"Линчеватель"},{"alias":"monk","description":"Добавьте +1/4 в запас ци монаха.","name":"Монах"},{"alias":"oracle","description":"Добавьте одно заклинание, известное из списка заклинаний оракула. Это заклинание должно быть, как минимум на один уровень ниже самого высокого уровня заклинания, которое может произнести оракул.","name":"Оракул"},{"alias":"paladin","description":"Добавьте +1 сопротивляемости паладина к энергии к одному виду энергии (максимум +10).","name":"Паладин"},{"alias":"rogue","description":"Человек получает +1/6 от нового воровского приема.","name":"Плут"},{"alias":"summoner","description":"Добавьте +1 ПЗ или +1 к навыку эйдолона.","name":"Призыватель"},{"alias":"ranger","description":"Добавьте +1 ПЗ или +1 к рангу навыков животному-компаньону следопыта. Если следопыт когда-либо заменяет своего компаньона, новый компаньон получает эти бонусные очки жизни или ранги умений.","name":"Следопыт"},{"alias":"sorcerer","description":"Добавьте одно заклинание, известное из списка заклинаний чародея. Это заклинание должно быть как минимум на один уровень ниже самого высокого уровня заклинания, которое может сотворить чародей.","name":"Чародей"},{"alias":"shaman","description":"Добавьте 1 заклинание из списка заклинаний жреца, которого нет в списке заклинаний шамана, к списку заклинаний, которые знает шаман. Заклинание должно быть хотя бы на 1 круг меньше максимального круга, который может применять шаман.","name":"Шаман"},{"alias":"shifter","description":"Добавьте 1/3 к количеству минут, на которое шифтер может принимать его низшую форму аспекта ежедневно.","name":"Шифтер"}],"kind":"race","nameEn":"Human","nameRu":"Человек","physicalDescription":"Физические характеристики людей столь же разнообразны, как и условия их обитания. От смуглых кочевников южных земель до бледных варваров северных морей. Люди отличаются разнообразием цвета кожи, типом сложения и чертами лица. В целом чем ближе люди живут к экватору, тем темнее у них кожа.","relations":"Люди плодовиты, и в периоды территориальной экспансии и колонизации их напористость и многочисленность часто ведут к контактам с другими народами. Во многих случаях такие встречи заканчиваются конфликтами и войнами, но люди легко прощают бывших врагов и вступают в союз с народами, которые не пытаются состязаться с ними в жестокости. Гордые до высокомерия, люди могут считать дварфов скаредными пьяницами, эльфов - легкомысленными щеголями, полуросликов - трусливыми воришками, гномов - одержимыми безумцами, а полуэдьфов и полуорков - одним сплошным недоразумением. В то же время разнообразие среди самих людей делает их способными воспринимать чужаков такими, какие они есть, без предубеждений.","slug":"human","society":"Человечество складывается из множества различных общественных строев, мироощущений и образов жизни. Хотя история самых старых человеческих государств насчитывает тысячи лет, по сравнению с государствами дварфов или эльфов людское общество выглядит как кипящий котел, в котором распадаются империи и новые королевства поглощают старые. В целом люди славятся своей гибкостью, изобретательностью и амбициозностью.","traits":[{"description":"Персонаж-человек получает +2 к одной характеристике по выбору игрока, что отражает разностороннюю природу этого народа.","name":"+2 к значению одной характеристики"},{"description":"Люди - существа среднего размера, что не дает им никаких бонусов или штрафов.","name":"Средний размер"},{"description":"Базовая скорость людей - 30 футов.","name":"Нормальная скорость"},{"description":"Люди получают одну дополнительную черту на 1 уровне.","name":"Дополнительная черта"},{"description":"Люди получают один дополнительный пункт навыков на 1 и на каждом последующем уровне.","name":"Умелый"},{"description":"Люди начинают игру со знанием всеобщего языка. Люди с высоким значением Интеллекта могут изучить любые дополнительные языки (кроме тайных, таких как друидический).","name":"Языки"}]},{"adventurers":"Африты ищут приключений для настоящих ощущений и возможности проверить свое мастерство на достойных врагах, но больше всего они ищут приключения в поисках силы. Когда африты ставят перед собой цель, они ее преследуют непоколебимо, никогда не переставая думать об опасностях впереди них. Когда эта наглость, наконец, карает их, африты часто полагаются на магию чародеев или бардов, чтобы бороться с вытекающими из этого проблемами.","alignmentAndReligion":"Африты двуличны - с одной стороны, яростные и независимые, а с другой - властные и требовательные. Их часто обвиняют в моральном обнищании, но их проблемное поведение редко мотивируется истинным злым умыслом. Африты обычно имеют принципиальное нейтральное или хаотичное нейтральное мировоззрение, с некоторыми предпосылками к истинному нейтральному мировоззрению. Большинство афритов не желают следовать учениям какого-то бога или ограничиваться строгими рамками, возложенными на них организованной верой. Когда африты принимают решение поклоняться (обычно почитая божество, связанное с огнем), они проявляют рьяность и преданность.","book":"Advanced Race Guide","description":"Люди, чья родословная связана с огненными элементалями, например, ифритами, африты - раса страстная и непостоянная. Ни одному африту не нравится сидячая жизнь; как лесной пожар, африты должны продолжать движение или сгореть в небытие. Африты не только обожают пламя, но и олицетворяют множество его аспектов, воплощающих в себе динамику огня, постоянно меняющуюся энергию и ее разрушительную безжалостную природу.","favoredClass":[{"alias":"witch","description":"Ведьма получает 1/6 нового наговора ведьмы.","name":"Ведьма"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"}],"kind":"race","nameEn":"Ifrit","nameRu":"Африт","names":[{"isMale":true,"name":"Аджа"},{"isMale":true,"name":"Денат"},{"isMale":true,"name":"Эфит"},{"isMale":true,"name":"Элум"},{"isMale":true,"name":"Джалидж"},{"isMale":true,"name":"Македж"},{"isMale":true,"name":"Урах"},{"isMale":false,"name":"Алайи"},{"isMale":false,"name":"Этва"},{"isMale":false,"name":"Макан"},{"isMale":false,"name":"Кари"},{"isMale":false,"name":"Сами"},{"isMale":false,"name":"Зетая"}],"physicalDescription":"Африты различаются по внешнему виду, так же широко, как и их элементальные предки. Большинство из них имеют заостренные уши, красные или пятнистые рога на лбу и волосы, которые дрожат, будто пламя. Некоторые обладают кожей цвета полированной латуни или угольного оттенка чешуёй, покрывающей их руки и ноги. Африт выступает в раскрытой и показной одежде ярко-оранжевого и красного цветов, желательно в паре с яркими украшениями.","relations":"Даже самые добродушные африты склонны смотреть на других людей как на инструменты для использования, и как таковые они лучше всего ладят с народами, которых они могут очаровать или подчинить. Полуэльфы и гномы часто находят себя пойманными на замыслах африта, в то время как полурослики, полуорки и дварфы обычно обуздывают контроль природы афритов. Как ни странно, африты иногда образуют невероятно близкие узы с эльфами, чей спокойный, отстраненный характер, кажется, уравновешивает импульсивность африта. Большинство афритов отказываются общаться с сильфами, но в остальном у них миролюбивые условия с другими народами, затронутыми стихиями.","slug":"ifrit","society":"Африты чаще всего рождаются в людских сообществах и редко они выходят из собственных обществ. Те, кто вырос в городе, почти всегда заключаются в тюрьму или изгоняются, так и не дожив до совершеннолетия; большинство же просто слишком вспыльчивы и независимы, чтобы влиться в это цивилизованное общество, и их склонность к пиромании не вызывает у местных властей расположения. Те, кто родился в кочевых или племенных обществах, многое переживают лучше, поскольку инстинктивное побуждение афритов исследовать и завоевать свое окружение может легко заработать им место среди лидеров своего племени.","traits":[{"description":"Африты используют уровни в классах - КЗ народа у них нет.","name":""},{"description":"Африты страстны и быстры, но стремительны и разрушительны.","name":"+2 Ловкость, +2 Харизма, -2 Мудрость"},{"description":"Африты - потусторонние существа с подтипом природный.","name":"Природное потусторонне существо"},{"description":"Африты - существа среднего размера и не получают бонусов или штрафов из-за их размера.","name":"Средний размер"},{"description":"Африты имеют базовую скорость 30 футов.","name":"Нормальная скорость"},{"description":"Африты могут видеть в темноте до 60 футов.","name":"Ночное зрение"},{"description":"пылающие руки 1/день (уровень заклинателя равен уровню африта; СЛ 11 + модификатор Харизмы).","name":"Псевдозаклинания"},{"description":"Африты обладают сопротивлением к огню 5.","name":"Сопротивление энергии"},{"description":"Чародеи африты со стихийным (огненным) наследием рассматривают свою Харизму на 2 пункта выше для всех заклинаний чародея и классовых способностей. Жрецы африты со сферой Огня используют свои силы сфер и заклинания как если бы УЗ африта был на 1 выше.","name":"Родство с огнём"},{"description":"Африты начинают игру, говоря на Всеобщем и Игнане. Африты с высокими показателями Интеллекта могут выбрать дополнительные языки из следующего списка: Акван, Ауран, Дварфийский, Эльфийский, Гномий, Полуросличий и Терран.","name":"Языки"}]},{"alignmentAndReligion":"Обычно принципиальное нейтральное.","book":"Bestiary 4","description":"Изгнанники засушливого мира, кружащегося вокруг красной звезды. Нынешние Касатхи понятия не имеют, как они покинули свой дом или как вернуться, но они продолжают искать дорогу назад. Они ведут скрытный образ жизни и живут кланами, которыми управляют матриархаты. Другие расы не могут отличить мужскую и женскую особь Касатх в виду их минимального физического различия. Представители этой расы скрывают свои рты за одеждой, и никогда не раздеваются в присутствии других рас. Они всеядны, но предпочитают мясо и соленые продукты. Достигнув совершеннолетия, многие касатхи покидают свои кланы, в поисках приключений, сокровищ и способа наконец-то вернуться на родину.","favoredClass":[{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"}],"kind":"race","nameEn":"Kasatha","nameRu":"Касатха","physicalDescription":"Этот загадочный четырех рукий гуманойд с гладкой кожей, мускулистым телом замер в боевой стойке с двумя зазубренными мечами и готов к атаке.","slug":"kasatha","traits":[{"description":"Касатхи используют уровни в классах - КЗ народа у них нет.","name":""},{"description":"Касатхи проворны и проницательны.","name":"+2 к Ловкости, +2 к Мудрости"},{"description":"Касатхи - существа среднего размера, что не дает им никаких бонусов или штрафов.","name":"Средний размер (Medium)"},{"description":"Базовая скорость касатх - 30 футов.","name":"Нормальная скорость (Normal Speed)"},{"description":"Касатхи получают +2 бонус уклонения к классу брони.","name":"Тренировка защиты (Экс)"},{"description":"Касатхи получают +4 расовый бонус к проверке стойкости чтобы избежать усталости, истощения, и других эффектов от бега, а также последствия голода, жажды, жары и холода.","name":"Пустынный бегун (Экс)"},{"description":"Касатха двигается с нормальной скоростью по пустыне где есть немагические затрудненные для перемещения зоны.","name":"Пустынный шаг (Экс)"},{"description":"При прыжке Касатха всегда считается разогнанным.","name":"Прыгун (Экс)"},{"description":"У Касатх 4 руки. Одна рука - основная, в то время как остальные три будут считаться не ведущими. Это не мешает ему биться одной рукой, а свободные руки использовать для других нужных целей.","name":"Мульти-вооруженный (Экс)"},{"description":"Внимание и Скрытность - классовые навыки Касатх.","name":"Сталкер (Экс)"},{"description":"Касатхи начинают игру зная языки общий и касатх. Касатхи с высоким показателем Интеллекта могут выбрать следующие языки: дварфийский, драконий, гнолльский, орочий и язык сфинксов.","name":"Языки"}]},{"adventurers":"Из сообразительных и ловких кицунэ получаются отличные барды и плуты. Нередко кицуне становятся чародеями, тогда как те немногие, кто родился с белым мехом и светлыми глазами, обычно становятся оракулами.","book":"Advanced Race Guide","description":"Кицунэ, или лисий народ - вульпийские оборотни, известные своей любовью, как к обману, так и к искусству. Кицунэ обладают двумя формами: привлекательным человеком стройного телосложения с выпуклыми глазами и истинной формой антропоморфной лисы. Несмотря на неудержимую склонность к обману, кицунэ ценят верность и становятся лояльными товарищами. Они увлекаются искусством, особенно загадками и рассказыванием историй, и поселяются в кланах предков, черпая мудрость, как у живых, так и у духов.","favoredClass":[{"alias":"witch","description":"Получите 1/6 от новой черты Магический хвост. Любой персонаж кицунэ может выбрать этот бонус после получения уровня в своем предпочитаемом классе.","name":"Ведьма"},{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"shaman","description":"Получите 1/6 черты нового Магического хвоста. Любой персонаж кицунэ может выбрать этот бонус после получения уровня в своем избранном классе.","name":"Шаман"},{"alias":"shaman","description":"Добавьте 1 заклинание очарования из списка заклинаний волшебника/чародея, которого нет в списке заклинаний шамана, к списку заклинаний, которые знает шаман. Заклинание должно быть хотя бы на 1 круг меньше максимального круга, который может применять шаман.","name":"Шаман"}],"kind":"race","nameEn":"Kitsune","nameRu":"Кицунэ","slug":"kitsune","traits":[{"description":"Кицунэ проворны и дружелюбны, но имеют тенденцию быть физически слабыми.","name":"+2 Ловкость, +2 Харизма, -2 Сила"},{"description":"Кицунэ - существа среднего размера, не имеющие бонусов или штрафов из-за своего размера.","name":"Средний размер"},{"description":"Кицунэ - гуманоиды с подтипами кицунэ и перевёртыш.","name":"Кицунэ"},{"description":"Кицунэ имеют базовую скорость 30 футов.","name":"Нормальная скорость"},{"description":"Кицунэ может видеть вдвое дальше людей в условиях тусклого света.","name":"Сумеречное зрение (Экс)"},{"description":"Кицунэ может принимать вид определенного человека того же пола. Кицунэ всегда принимает эту особую форму, когда использует эту способность. Человеческая форма кицунэ не может использовать атаку укусом, но получает бонус народа +10 на проверки Маскировки, заставляющие казаться человеком. Смена формы - основное действие. В остальном эта способность функционирует как иной облик, за исключением того, что кицунэ не изменяет свои очки характеристик и может оставаться в этой форме на неопределенный срок.","name":"Смена формы (Св)"},{"description":"Кицунэ получает бонус народа +2 на проверки Акробатики.","name":"Проворство (Экс)"},{"description":"Кицунэ добавляет +1 к СЛ любых испытаний от произнесенных ими заклинаний очарования. Кицунэ с показателем Харизмы 11 или выше получает следующее псевдозаклинание: 3/день - пляшущие огоньки (УЗ равен уровню кицунэ).","name":"Магия Кицунэ (Экс/Пс)"},{"description":"В своей естественной форме кицунэ имеет атаку укусом, которая наносит 1d4 пунктов урона.","name":"Естественное оружие (Экс)"},{"description":"Кицунэ начинает игру, говоря на Всеобщем и Сильван. Кицунэ с высокими показателями Интеллекта может выбирать дополнительные языки из следующего списка: любой человеческий язык, Акло, Небесный, Эльфийский, Гномий и Тенгу.","name":"Языки"}]},{"alignmentAndReligion":"Обычно принципиальное злое.","book":"Bestiary 1","description":"Кобольды предпочитают тьму и поэтому обитают в огромных норах под землёй или в тёмных уголках леса, скрытых от солнечных лучей. Из-за внешнего сходства кобольды провозглашают себя наследниками драконов, призванными править землями, простёршимися под крыльями их огромных богоподобных родичей, но самим драконам эти настырные существа в общем и целом не нужны. Сами кобольды прекрасно знают о своей слабости, хоть вслух и заявляют о священных правах и предназначении. Если у кобольдов есть возможность получить преимущество в бою, они обязательно ей воспользуются: будучи существами трусливыми, но хитроумными, они предпочтут устроить засаду, предать, спрятаться в норе, отгородившись от противника множеством грубых, но затейливых ловушек, или в крайнем случае с гиканьем и криками навалиться на него всей толпой. Окраска шкур кобольдов может соответствовать оттенку чешуи любого из цветных драконов, причём даже у кобольдов, вылупившихся из яиц одной кладки, цвета могут отличаться. Самый распространённый - красный, но белые, зелёные, синие и чёрные кобольды тоже не редкость.","favoredClass":[{"alias":"witch","description":"Добавьте +5 футов к расстоянию, на которое ее фамильяр дает черту Бдительность (максимум +20 футов).","name":"Ведьма"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"}],"kind":"race","nameEn":"Kobold","nameRu":"Кобольд","physicalDescription":"У этого небольшого ящероподобного гуманоида длинный хвост,чешуйчатая кожа и пасть, полная мелких зубов.","slug":"kobold","traits":[{"description":"Кобольды используют уровни в классах - КЗ народа у них нет. Кобольд с уровнями в классах персонажа ведущего получает штраф -3 к своему КО (вместо обычных -2).","name":""},{"description":"Кобольды быстрые, но хилые.","name":"-4 Сила, +2 Ловкость, -2 Выносливость"},{"description":"Кобольды - существа небольшого размера, поэтому они получают +1 (размер) к КБ, +1 (размер) к атакам, -1 к МБМ и ЗБМ и +4 (размер) к проверкам Скрытности.","name":"Небольшой размер"},{"description":"Базовая скорость кобольдов - 30 футов.","name":"Нормальная скорость"},{"description":"Кобольды могут видеть в темноте на расстоянии до 60 футов.","name":"Ночное зрение"},{"description":"Кобольды получают +1 (естественная броня) к КБ.","name":"Броня"},{"description":"Кобольды получают +2 (народ) к проверкам Внимания, Профессии (рудокоп) и Ремесла (капканщик). Для кобольдов навыки Ремесло (капканщик) и Скрытность всегда классовые.","name":"Пройдоха"},{"description":"Светочувствительность.","name":"Слабые стороны"},{"description":"Кобольды начинают игру, зная лишь драконий язык. Кобольды с высоким значением Интеллекта могут выбрать дополнительные языки из следующего списка: всеобщий, гномий, дварфийский и подземный.","name":"Языки"}]},{"alignmentAndReligion":"Обычно нейтральный.","book":"Bestiary 1","description":"Выше пояса мерфолки выглядят как красивые люди, некоторыми чертами своего облика напоминающие эльфов и других сухопутных гуманоидов. Вместо ног у мерфолков рыбий хвост и плавники. Цвет чешуи зависит от места обитания и может иметь множество оттенков, включая серебристый, бледно-зелёный или даже синий с жёлтыми и красными полосами. Длина мерфолков колеблется от 6 до 8 футов, вес превышает 200 фунтов, женщины чуть меньше мужчин. Мерфолки - амфибии, но на суше передвигаются с большим трудом и редко отходят от моря дальше чем на милю. Эти существа редко общаются с представителями других народов и в большинстве своём прилагают массу усилий, чтобы отвадить моряков подальше от своей территории, при необходимости даже прибегая к насилию. Древние записи упоминают об ужасном секрете, охраняемом мерфолками в глубинах моря. Неизвестно, что это за тайна, но раз мерфолки так стараются избегать прочих существ, это наверняка нечто крайне важное. На первый взгляд этот народ прекрасен и силён, но некоторые мудрецы и моряки рассказывают, что в самых глубоких и недоступных частях морей и океанов обитают выродившиеся и мутировавшие мерфолки. Некоторые признаки позволяют сделать вывод, что такие существа в какой-то момент начали поклоняться извращённым зловещим силам, обитающим в морской пучине, но ряд теорий включает в это число всех мерфолков, утверждая, что даже те из них, кто считает себя хозяином собственной судьбы, на самом деле не более чем марионетка, управляемая могущественными существами из глубин.","favoredClass":[{"alias":"witch","description":"Добавьте +1 к УЗ одного из заклинаний покровителей ведьмы (максимум +3 УЗ к любому заклинанию).","name":"Ведьма"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"}],"kind":"race","nameEn":"Merfolk","nameRu":"Мерфолк","physicalDescription":"Эта красивая дева с изящным рыбьим хвостом резвится в волнах, выныривая то здесь, то там.","slug":"merfolk","traits":[{"description":"Мерфолки используют уровни в классах - КЗ народа у них нет.","name":""},{"description":"Мерфолки грациозны, красивы и выносливы.","name":"+2 Ловкость, +2 Выносливость, +2 Харизма"},{"description":"Мерфолки обитают в воде и могут ей дышать. Их наземная скорость - 5 футов, а скорость плавания - 50 футов. Несмотря на то, что мерфолки - амфибии, им не нравится покидать воду надолго.","name":"Подводный"},{"description":"Мерфолки покрыты прочной чешуёй.","name":"+2 естественная броня"},{"description":"Мерфолки видят в сумерках вдвое дальше людей.","name":"Сумеречное зрение"},{"description":"Мерфолки начинают игру со знанием всеобщего языка и аквана. Мерфолки с высоким значением Интеллекта могут выбрать дополнительные языки из следующего списка: аболетский, акло, драконий, сахваджинский, сильван и эльфийский.","name":"Языки"}]},{"adventurers":"Обезьяны-гоблины ведут варварский образ жизни, и многие из них переходят в класс настоящих варваров. Однако воины и плуты также довольно распространены среди представителей этой расы. При том, что многие из них даже не слышали о магических классах, жрецы обезьян-гоблинов, состоящие на службе у темных богов, пользуются у других обезьян-гоблинов должным уважением, граничащим со страхом.","alignmentAndReligion":"Обычно нейтральное злое.","book":"Bestiary 6","description":"Обезьяны-гоблины являются ответвлением расы гоблинов, которые охотно приспособились к образу жизни в высоких, покрытых листвой кронах деревьев тропических лесов. Имея довольно цепкие хвосты, напоминающие крысиные, обезьяны-гоблины одинаково превосходно чувствуют себя как на деревьях, так и на земле.","favoredClass":[{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"}],"kind":"race","nameEn":"Monkey goblin","nameRu":"Обезьяна-гоблин","physicalDescription":"У этого существа широкая голова и зубастая пасть гоблина, пятнистая зеленая кожа, обезьяньи руки и ноги и крысиный хвост.","slug":"monkeyGoblin","traits":[{"description":"Обезьяны-гоблины используют уровни в классах - КЗ народа у них нет.","name":""},{"description":"обезьяны-гоблины быстрые, но слишком импульсивные и неприятные.","name":"+4 к Ловкости, -2 к Мудрости, -2 к Харизме"},{"description":"Обезьяны-гоблины - существа небольшого размера, поэтому они получают +1 (размер) к КБ, +1 (размер) к атакам, -1 к МБМ и ЗБМ и +4 (размер) к проверкам Скрытности.","name":"Небольшой размер"},{"description":"Обезьяны-гоблины имеют базовую скорость 20 футов.","name":"Медленный"},{"description":"Обезьяны-гоблины видят в сумерках вдвое дальше людей.","name":"Сумеречное зрение"},{"description":"Обезьяны-гоблины получают +2 к проверкам Акробатики и Скрытности.","name":"Акробатика"},{"description":"Обезьяны-гоблины получают расовый бонус +2 ко всем проверкам против страха.","name":"Бесстрашие"},{"description":"Скорость лазания у обезьян-гоблинов - 30 футов","name":"Прирожденный скалолаз"},{"description":"Все обезьяны-гоблины имеют длинные гибкие хвосты, которые могут использовать для того, чтобы носить предметы. Они не могут держать в нем оружие, но они способны выхватывать им небольшие предметы для использования их в собственных нуждах в качестве свободного движения.","name":"Цепкий хвост"},{"description":"Гоблины-обезьяны начинают игру, говоря на гоблинском. Обезьяны-гоблины с высоким показателем Интеллекта могут выбрать следующие языки: общий, драконий, дварфийский, гноллий, гномий, полуросличий, орочий.","name":"Языки"}]},{"alignmentAndReligion":"Обычно хаотчное доброе.","book":"Bestiary 6","description":"Эти бледные гуманоиды, которые родом из дальних берегов таинственных подземных океанов, ведут давнюю войну с вторгшимися урдефанами. Мунаври управляют кораблями с фиолетовыми парусами, замысловато вырезанными из слоновой кости, сквозь иссиня черные глубины подземных океанных вод. Они – настоящие знатоки военно-морского дела.","favoredClass":[{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"}],"kind":"race","nameEn":"Munavri","nameRu":"Мунаври","physicalDescription":"Нефритовая броня покрывает этого худого гуманоида-альбиноса, а в ее бледных глазах - жуткий блеск.","relations":"Иногда они находят союзников среди темного народа, но такие договоренности совсем не общеприняты и чаще всего не пользуются особым доверием.","slug":"munavri","traits":[{"description":"Мунаври используют уровни в классах - КЗ народа у них нет. Несмотря на отсутствие КЗ народа, мунаври - могущественное существо, и его КО на 1 выше, чем у человека того же уровня.","name":""},{"description":"Обреченные людьми на суровую жизнь в недрах земли, мунаври обладают исключительными способностями.","name":"-2 к Силе, +4 к Ловкости, +2 к Выносливости, +2 к Интеллекту, +2 к Мудрости, +2 к Харизме"},{"description":"Мунаври - средние по размеру существа.","name":"Средний"},{"description":"Базовая скорость мунаври - 30 футов.","name":"Нормальная скорость"},{"description":"Мунаври видят в темноте на расстоянии 120 футов.","name":"Ночное зрение"},{"description":"Общая черта монстров.","name":"Светобоязнь"},{"description":"Мунаври может мгновенно научиться, как использовать практически любое устройство. Раз в день она может выбирать одно оружие, доспехи или предмет для активации заклинаний, на который она использует чтение предмета. За количество минут, соответствующее ее уровню персонажа, она приобретает навык профессионального владения этим предметом или может использовать магический предмет, как если бы она была заклинателем соответствующего класса.","name":"Усиленное чтение предмета"},{"description":"УкМ мунаври равен 8 + ее общий уровень классов.","name":"Устойчивость к магии"},{"description":"Мунаври может использовать чтение предмета по желанию (уровень заклинателя равен уровню персонажа).","name":"Псевдозаклинание"},{"description":"Мунаври умеет мысленно общаться с другими мунаври в пределах 60 футов.","name":"Телепатия"},{"description":"Мунаври начинают игру, говоря на языке мунаври. Мунаври с высоким показателем Интеллекта могут выбирать следующие языки: акло, аболет, акван, тмного народа, драконий, терран и подземный.","name":"Языки"}]},{"alignmentAndReligion":"Обычно принципиальное нейтральное.","book":"Bestiary 4","description":"Нагаджи - раса змееподобных гуманоидов, созданных нагами для службы в качестве рабов. Едва напоминающие человека Нагаджи обладают чешуйчатой кожей походящую окрасом и узором на кожу Наг. Помимо этого у них раздвоенный язык и глаза не имеют век, что в итоге дает им никогда не мигающий взгляд, что представители других рас находят весьма раздражительным. Нагаджи почитают Наг как своих создателей, дойдя даже до того, что начали обожествлять их и поклоняться как богам. Несмотря на большое влияние Наг на жизнь своих созданий, Нагаджи имеют свою собственную культуру, представляющую собой помесь культур Наг и людей. Они предпочитают тепло тропических районов и селятся в диких, изолированных местах таких как дымящиеся джунгли, обширные болота или вулканические горы, где они воздвигают большие храмы в честь своих создателей. Эти величественные храмы окружены десятками грязевых лачуг и домишками из глиняных кирпичей, служащих Нагаджам домами и общественными зданиями.","favoredClass":[{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"}],"kind":"race","nameEn":"Nagaji","nameRu":"Нагаджи","physicalDescription":"У этой человекоподобной рептилии темная чешуя, глаза без век, а из клыкастой пасти без губ прорывается змеиный язык. Нагаджи достигают роста примерно 5-6 футов и весит около 175 фунтов.","slug":"nagaji","traits":[{"description":"Нагаджи используют уровни в классах - КЗ народа у них нет.","name":""},{"description":"Нагаджи - это сильные духом и телом личности, у которых ум не в почете.","name":"+2 к Силе, +2 к Харизме, -2 к Интеллекту"},{"description":"Нагаджи средние по размеру существа не имеющие бонусы и штрафы по габаритам.","name":"Средний"},{"description":"Нагаджи имеют базовую скорость 30 футов.","name":"Обычная скорость"},{"description":"Нагаджи видят в сумерках вдвое дальше людей.","name":"Сумеречное зрение"},{"description":"Нагаджи имеют бонус к броне +1 за счет своей прочной чешуйчатой плоти.","name":"Чешуйчатая броня"},{"description":"Нагаджи получают +2 расового сопротивления к проверкам против ядов и заклятий воздействующих на разум.","name":"Сопротивление (Экс)"},{"description":"Нагаджи получают +2 расового бонуса к Дрессировке животных (рептилий) и +2 к проверке Внимания.","name":"Змеиное чувство (Экс)"},{"description":"Нагаджи начинают игру зная общий и драконий языки. Нагаджи с высоким показателем Интеллекта могут выбрать следующие языки: любой человеческий язык, абиссал, акло, небесный, великаний, адский, сильван.","name":"Языки"}]},{"alignmentAndReligion":"Обычно хаотичный злой.","book":"Bestiary 1","description":"Орки невероятно сильны, но не особо умны. Главное их отличие от цивилизованных народов состоит во взглядах на мир. Диким и воинственным обществом орков правит сильнейший, держа других в страхе жестокостью. Орки привыкли брать всё силой и даже глазом не моргнут, вырезав или поработив целые поселения, если будут уверены в собственной безнаказанности. Им нет дела до порядка и чистоты, поэтому их лагеря и деревни похожи на грязные притоны, где орки развлекаются: устраивают пьяные потасовки, сражаются в бойцовских ямах или придумывают другие жестокие забавы. Оркам недостаёт терпения, чтобы заниматься земледелием, а из животных у них выживают лишь самые крепкие и самодостаточные, поэтому орку почти всегда легче отобрать нужную ему вещь, нежели сделать её самому. Эти существа заносчивы, вспыльчивы и вспоминают о чести лишь тогда, когда им это выгодно. Рост взрослого орка-мужчины - около 6 футов, а вес - 210 фунтов. Орки и люди часто скрещиваются между собой, но почти всегда это результат набегов и угона в рабство, а не добровольный союз. Многие племена специально выращивают полуорков и сами занимаются их воспитанием, поскольку из более умных полукровок получаются отличные стратеги и вожди.","favoredClass":[{"alias":"witch","description":"Добавьте одно заклинание из списка заклинаний ведьмы фамильяру ведьмы. Это заклинание должно быть, как минимум на один уровень ниже самого высокого уровня заклинания, которое она может сотворить. Если ведьма заменит своего фамильяра, новый фамильяр будет знать эти дополнительные заклинания.","name":"Ведьма"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"}],"kind":"race","nameEn":"Orc","nameRu":"Орк","physicalDescription":"Этот дикарь напоминает озверевшего и одичалого человека с серо-зелёной кожей и копной грязных чёрных волос.","slug":"orc","traits":[{"description":"Орки используют уровни в классах - КЗ народа у них нет.","name":""},{"description":"Орки жестокие и дикие.","name":"+4 Сила, -2 Интеллект, -2 Мудрость, -2 Харизма"},{"description":"Орки могут видеть в темноте на расстоянии до 60 футов.","name":"Ночное зрение"},{"description":"Орки могут оставаться в сознании и продолжать бой даже с отрицательными ПЗ. Орк остаётся ошеломлённым и каждый раунд теряет 1 ПЗ. Орк всё равно умирает, когда количество отрицательных ПЗ сравнивается со значением его Выносливости.","name":"Свирепость"},{"description":"Орк становится растерянным, пока находятся на ярком солнечном свету или в области действия заклинания дневной свет.","name":"Светочувствительность"},{"description":"Орки умеют обращаться с двуручными топорами и фальшионами; любое оружие со словом «орочий» в наименовании относится для них к категории особого оружия.","name":"Оружие орков"},{"description":"Орки начинают игру со знанием всеобщего и орочьего языков. Орки с высоким значением Интеллекта могут выбрать дополнительные языки из следующего списка: великаний, гнолльский, гоблинский, дварфийский и подземный.","name":"Языки"}]},{"alignmentAndReligion":"Ореды, возможно, прежде всего, настроены на свой лад, и любое нарушение их распорядка встречает тихое неодобрение. Ореады яростно защищают своих друзей, но, похоже, не особо заботятся о благополучии тех, кто находится за пределами их узкого круга знакомых. Таким образом, большинство оредов законно нейтральны. Религиозная жизнь легко приходит на Землю. Они ценят спокойную, созерцательную жизнь монашеского ордена и в большинстве своем посвящают себя поклонению земным или связанным с природой божествам.","book":"Advanced Race Guide","description":"Ореады - это люди, чья родословная включает в себя прикосновение элементального существа Земли где-то по линии, часто это шайтан. Стойкие и созерцательные, ореады - это раса, которую нелегко сдвинуть с места, но которую почти невозможно остановить, когда она побуждается к действию. Они остаются загадкой для большей части мира благодаря своей затворнической природе, но те, кто ищет их в своих уединенных горных убежищах, находят ореады тихими, надежными и защищающими своих друзей.","favoredClass":[{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"}],"kind":"race","nameEn":"Oread","nameRu":"Ореад","physicalDescription":"Ореады крепкие и стойкие, с каменными оттенками кожи и волос черного, коричневого, серого или белого цвета. В то время как все ореады кажутся частично каменными, некоторые из них имеют более выраженные признаки их изначальной кожи, которая сияет, как полированный оникс, выступающие из их тела каменные выступы, светящиеся драгоценные камни вместо глаз или волосы, похожие на кристаллические шипы. Они часто одеваются в естественных тонах, носят практичную одежду, хорошо подходящую для энергичных физических нагрузок, и предпочитают свежие цветы, простые драгоценные камни и другие природные творения сложным ювелирным изделиям.","relations":"Ореады комфортно чувствуют себя в компании дварфов, с которыми у них много общего. Они считают гномов слишком странными, а многих полуросликов - слишком дерзкими, поэтому избегают этих рас в целом. Ореады с удовольствием общаются с полуорками и полуэльфами, испытывая чувство родства с другими полулюдьми, несмотря на неизбежные личные конфликты. Среди рас, затронутых стихиями, у оредов мало друзей, но нет настоящих врагов.","slug":"oread","society":"Как незначительное ветка развития человеческого рода, ореады не имеют собственного устоявшегося общества. Вместо этого большинство ореад растут в человеческих сообществах, изучая обычаи своих родителей. Взрослые ореады пользуются среди других рас заслуженной репутацией отшельников и одиночек. Немногие хорошо переносят суету городской жизни, предпочитая вместо этого проводить свои дни в спокойном созерцании на вершине какого-нибудь удаленного горного пика или глубоко под землей в уединенной пещере. Ореады с большей терпимостью к жизни среди людей часто присоединяются к городской страже или находят другой способ служить своему сообществу в ответственной роли.","traits":[{"description":"Ореады используют уровни в классах - КЗ народа у них нет.","name":""},{"description":"Ореады сильны, тверды, стабильны и стоичны.","name":"+2 Сила, +2 Мудрость, -2 Харизма"},{"description":"Ореады - потусторонние существа с подтипом природный.","name":"Природное потусторонне существо"},{"description":"Ореады - существа среднего размера, не имеющие бонусов или штрафов из-за своего размера.","name":"Средний"},{"description":"базовая скорость ореадов составляет 20 футов.","name":"Медленная скорость"},{"description":"Ореады могут видеть в темноте до 60 футов.","name":"Ночное зрение"},{"description":"Волшебный камень 1/день (уровень заклинателя равен общему уровню ореда).","name":"Псевдозаклинание"},{"description":"Ореады обладают сопротивлением кислоте 5.","name":"Устойчивость к энергии"},{"description":"Ореады чародеи со стихийным (земляным) наследие рассматривают свою Харизму на 2 пункта выше для всех заклинаний чародея и способностей класса. Жрецы ореады со сферой Земли используют дарованные силы и заклинания с уровнем заклинателя +1.","name":"Родство с землей"},{"description":"Ореады начинают игру, говоря на общем и терране. Ореады с высокими показателями Интеллекта могут выбирать из следующего: акван, ауран, гномий, эльфийский, дварфский, полуросличий, игнан и подземный.","name":"Языки"}]},{"adventurers":"Крысолюдами часто движет желание искать новые возможности для торговли, как для себя, так и для своих логовищ. Авантюристы крысолюдов могут искать потенциальные рынки сбыта для товаров своего клана, следить за источниками новых товаров или просто бродить, в надежде найти сокровища, чтобы профинансировать менее опасные деловые предприятия. Битвы крысолюдов часто решаются хитрыми ловушками, засадами или саботажем позиций врага, и, соответственно, молодые герои крысолюдов часто берут такие классы, как алхимик, стрелок или плут.","alignmentAndReligion":"Крысолюдами движет желание приобретать интересные предметы и любовь возиться со сложными вещами. Прочные связи сообществ крысолюдов дают им возможность оценить преимущества упорядоченного сообщества, даже если они готовы нарушить эти правила, когда они заинтересованы в достижении своих личных целей. Большинство крысолюдов нейтральны, а те, кто принимает религию, склонны поклоняться божествам, представляющим торговлю и семью.","book":"Advanced Race Guide","description":"Крысолюды это маленькие, похожие на грызунов гуманоиды; первоначально они обитали в подземных районах сухих пустынь и равнин, а теперь всё чаще встречаются в кочевых торговых караванах. Подобно вьючным крысам, на которых они похожи, крысолюды по своей природе лудильщики и кладовщики, в целом являясь мастерами торговли, особенно когда речь заходит о приобретении и ремонте механических или магических устройств. Хотя некоторые из них проницательные торговцы, которые тщательно ориентируются в изменчивых союзах черных рынков и базаров, многие крысолюды любят свои запасы интересных предметов гораздо больше, чем деньги, и предпочитают продолжать накопление диковинок, чем запасаться простыми монетами. Часто можно видеть, как успешная команда торговцев крысолюдов выкатывается из города с еще большим грузом, чем на входе, и все их вещи возвышаются угрожающе высокой кучей над телегой, запряженной гигантскими крысами.","favoredClass":[{"alias":"witch","description":"Добавьте +5 футов к дистанции одного наговора с дистанцией отличной от «касание».","name":"Ведьма"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"}],"kind":"race","nameEn":"Ratfolk","nameRu":"Крысолюд","names":[{"isMale":true,"name":"Агиз"},{"isMale":true,"name":"Брихз"},{"isMale":true,"name":"Джир"},{"isMale":true,"name":"Ниннек"},{"isMale":true,"name":"Редрал"},{"isMale":true,"name":"Тамок"},{"isMale":true,"name":"Скиввен"},{"isMale":true,"name":"Риккан"},{"isMale":false,"name":"Бессель"},{"isMale":false,"name":"Фар"},{"isMale":false,"name":"Джикс"},{"isMale":false,"name":"Кич"},{"isMale":false,"name":"Куби"},{"isMale":false,"name":"Немм"},{"isMale":false,"name":"Рисси"},{"isMale":false,"name":"Тикка"}],"physicalDescription":"Типичные крысолюды имеют средний рост четыре с половиной фута. Они часто носят мантии, чтобы сохранять прохладу в пустыне или скрывать свой силуэт в городах, поскольку они знают, что другие гуманоиды находят их черты грызунов неприятными. Крысолюды очень любят блестящие украшения, особенно медь, бронзу и золото, и многие украшают свои уши и хвосты маленькими кольцами из таких металлов. Они, как известно, обучают гигантских крыс (Свирепая крыса с простым шаблоном «великанский»), которых они часто используют в качестве вьючных животных и лошадей.","relations":"Крысолюды, как правило, довольно хорошо ладят с людьми и часто создают сообщества крысолюдов, живущие в канализации, переулках и тени человеческих городов. Крысолюды находят дварфов слишком ограниченными и территориальными и часто принимают даже умеренную критику дварфов за личные нападки. Крысолюды не испытывают особых чувств к гномам или полуросликам, хотя в областях, где эти расы и крысолюды должны бороться за ресурсы, клановые войны могут стать догмой для поколений. Крысолюдам нравятся компания эльфов и полуэльфов, они часто считают их самыми спокойными и разумными из цивилизованных гуманоидных рас. Крысолюды особенно любят эльфийскую музыку и искусство, и многие логова крысолюдов украшены предметами эльфийского искусства, приобретенными в результате дружеской торговли в течение поколений.","slug":"ratfolk","society":"Крысолюды чрезвычайно общительны и живут в больших логовищах с множеством скрытых закоулков, которые используются для сокрытия своих сокровищ или побега от опасности, тяготея к подземным туннелям или плотно набитым жилым домам в городских трущобах. Они чувствуют сильную связь со своими большими семьями и родами, а также с обычными грызунами всех видов, живя в хаотической гармонии и отчаянно сражаясь, чтобы защитить друг друга в случае угрозы. Они не помедлят использовать свои запасы снаряжения в бою, но предпочтут уладить разногласия и разрешить споры путем взаимовыгодных сделок. Когда конкретное логово крысолюдов становится переполненным, а окружающая среда не может поддержать более крупное сообщество, молодые крысолюды инстинктивно ищут новые места, где можно поселиться. Если достаточно большая группа иммигрантов крысолюдов поселится в новом плодородном районе, они могут создать новое логовище, часто с прочными политическими связями с их первоначальной родиной. В противном случае отдельные крысолюды склонны просто покинуть дом и поселиться в другом месте или бродить с караванами, которые перемещаются большую часть года, что снижает критическую переполненность дома.","traits":[{"description":"Крысолюды используют уровни в классах - КЗ народа у них нет.","name":""},{"description":"Крысолюды проворны и умны, но физически слабы.","name":"+2 к Ловкости, +2 к Интеллекту и -2 к Силе"},{"description":"Крысолюды - существа небольшого размера, поэтому они получают +1 (размер) к КБ, +1 (размер) к атакам, -1 к МБМ и ЗБМ и +4 (размер) к проверкам Скрытности.","name":"Небольшой размер"},{"description":"Базовая скорость крысолюдов 20 футов.","name":"Низкая скорость"},{"description":"Крысолюды получают бонус +2 (народ) к Ремесло (Алхимия), Вниманию и Использование Магических Устройств","name":"Ремесленник"},{"description":"Крысолюды получают бонус +4 (народ) к проверкам навыка Дрессировки, совершаемых в отношении грызунов.","name":"Понимание грызунов"},{"description":"Крысолюды привыкли жить и сражаться сообща, и они умеют теснить врагов в скопище ради собственной выгоды и во вред противникам. В одной клетке одновременно могут находиться до двух крысолюдов. Если два крысолюда в одной клетке атакуют одного и того же врага, считается, что они берут этого врага в тиски, как если бы они находились в двух противоположных клетках.","name":"Скопище"},{"description":"Крысолюды видят в темноте на 60 футов.","name":"Ночное зрение"},{"description":"Крысолюды начинают игру со знанием всеобщего. Крысолюды с высоким значением Интеллекта могут выбрать дополнительные языки из списка: акло, драконий, дварфийский, гнолльский, гномий, гоблинский, орочий, подземный и полуросличий.","name":"Языки"}]},{"alignmentAndReligion":"Обычно нейтральное.","book":"Bestiary 4","description":"Самсаран - это гуманоид, чей дух перевоплощается в другого самсаранца после смерти. У них темные волосы, бледно-голубоватая кожа и глаза без видимых зрачков или радужек. Кровь самсарана чиста, как вода. Каждый самсаран рождается со знанием того, что он жил до и продолжит жить после смерти через цикл реинкарнации. Когда самсаран умирает, его тело исчезает из этого мира, и где-то рождается самсаран ребенок. Самсараны могут вступать в связь с людьми и производить человеческое потомство. Типичные самсараны ведут простую, аскетическую жизнь, подальше от крупных сообществ. Они живут в маленьких изолированных фермерские сообщества как отдельные лица или пары, а старшие самсараны усыновляют вновь родившихся детей. Некоторые обретают себя в качестве консультантов, посредников, пророков или провидцев.","favoredClass":[{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"}],"kind":"race","nameEn":"Samsaran","nameRu":"Самсаран","physicalDescription":"Этот безмятежно выглядящий стройный человек имеет бледно-голубую кожу и пустые глаза, облаченный в простую одежду.","slug":"samsaran","traits":[{"description":"Самсараны используют уровни в классах - КЗ народа у них нет.","name":""},{"description":"Самсараны проницательны, и сильны умом, но их тела довольно хрупкие.","name":"+2 к Интеллекту, +2 к Мудрости, -2 Выносливости"},{"description":"Самсараны средние по размеру существа не имеющие бонусы и штрафы по габаритам.","name":"Средний"},{"description":"Самсараны имеют базовую скорость 30 футов.","name":"Обычная скорость"},{"description":"Самсараны видят в сумерках вдвое дальше людей.","name":"Сумеречное зрение"},{"description":"самсараны получают +2 (народ) к испытаниям против смертельных эффектов, негативной энергии, для снятия отрицательных уровней и проверкам Выносливости для стабилизации.","name":"Обреченный на жизнь (Экс)"},{"description":"Самсаран с показателем Харизмы 11 и выше получают следующие пседвозаклинания: 1/день - понимание языков, зрение некроманта, первая помощь. Уровень заклинателя в этом случае равен уровню персонажа.","name":"Псевдозаклинания (Пс)"},{"description":"Самсаран получает +2 бонуса к любым 2-м навыкам и эти навыки становятся классовыми.","name":"Осколки прошлого (Экс)"},{"description":"Самсаран начинает игру со знанием языков общий и самсаранский. Самсаран с высоким показателем Интеллекта могут выбрать следующие языки: любой человеческий язык, абиссал, акван, ауран, драконий, небесный, великаний, игнан, адский, терран.","name":"Языки"}]},{"adventurers":"Освобождённые шабти часто исследуют планы, стремясь заменить ложные воспоминания уникальным опытом.","book":"Bestiary 5","description":"Шабти — это копии богатых или влиятельных смертных, стремящихся избежать наказания за свои грехи после смерти. Выросшие из осколков смертных душ, шабти переносят любые космические наказания и труды, которые могут ожидать их создателей в загробной жизни, если только их не обнаружат и не освободят психопомпы.","favoredClass":[{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"}],"kind":"race","nameEn":"Shabti","nameRu":"Шабти","physicalDescription":"Шабти обычно выглядят как идеализированные люди с идеальным телосложением и безупречными чертами лица. Обычно они имеют рост 6 футов и весят около 175 фунтов.","slug":"shabti","traits":[{"description":"Шабти используют уровни в классах - КЗ народа у них нет.","name":""},{"description":"У шабти мощные тела и соответствующее им умение держать себя.","name":"+2 Выносливость, +2 Харизма"},{"description":"Шабти - потусторонние существа с подтипом местный.","name":"Местное потустороннее существо (Native Outsider)"},{"description":"Шабти - существа среднего размера, что не даёт им никаких бонусов или штрафов.","name":"Средний размер (Medium)"},{"description":"Базовая скорость шабти - 30 футов.","name":"Нормальная скорость (Normal Speed)"},{"description":"Шабти видят в темноте на 60 футов.","name":"Ночное зрение (Darkvision)"},{"description":"Шабти не стареют естественным путем и не могут умереть от старости. Хотя некоторые из них могут появиться в других возрастных категориях, кроме совершеннолетия, они никогда не покидают свои первоначальные возрастные категории. Заклинания и эффекты, вызывающие старение, действуют на шабти как обычно.","name":"Бессмертный (Immortal) (Экс)"},{"description":"Шабти не может стать нежитью. Заклинания и способности, превращающие шабти в нежить, не оказывают никакого эффекта.","name":"Невосприимчивость к нежизни (Immune to Undeath) (Экс)"},{"description":"Шабти помнят кусочки своих прошлых жизней. В результате они рассматривают все навыки Знания как классовые навыки.","name":"Знания прошлых жизней (Past-Life Knowledge) (Экс)"},{"description":"Шабти не получает штрафов от эффектов вытягивания жизни, хотя его все равно можно убить, если его отрицательные уровни превышают количество КЗ. Через 24 часа любые отрицательные уровни, полученные шабти, автоматически удаляются без необходимости дополнительных испытаний.","name":"Устойчивость к вытягиванию уровня (Resist Level Drain) (Экс)"},{"description":"Убитых шабти чрезвычайно трудно вернуть к жизни. Любой, кто пытается вернуть шабти к жизни, используя возвращение к жизни, воскрешение или подобное заклинание, должен преуспеть в проверке уровня заклинателя, СЛ которой равна 10 + КЗ шабти. Если попытка не удалась, заклинание терпит неудачу, и заклинатель не может вернуть шабти к жизни в течение следующих 24 часов (хотя по истечении этого периода заклинатель может попытаться еще раз).","name":"Расколотая душа (Shattered Soul) (Экс)"},{"description":"Шабти могут использовать внушение один раз в день в качестве псевдозаклинания с уровнем заклинателя равным классовому уровню шабти.","name":"Псевдозаклинание (Spell-Like Ability)"},{"description":"Шабти начинают игру со знанием всеобщего языка. Шабти с высоким значением Интеллекта могут изучить любые дополнительные языки (кроме тайных, таких как друидический).","name":"Языки (Languages)"}]},{"book":"Bestiary 5","description":"Большинство людей верят, что шкурокожие — это полукровки ликантропов или что они обладают более слабой версией проклятия ликантропии. Однако шаманы-шкурокожие утверждают, что их народ был избран богами в качестве моста между человечеством и животными. В любом случае, шкурокожие большую часть времени напоминают людей, но обладают сверхъестественной способностью превращаться в звероподобных гуманоидов с мощными и устрашающими аспектами животных.","favoredClass":[{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"}],"kind":"race","nameEn":"Skinwalker","nameRu":"Шкурокожий","slug":"skinwalker","traits":[{"description":"Шкурокожие используют уровни в классах - КЗ народа у них нет.","name":""},{"description":"Шкурокожие настроены на естественный порядок и ценят страсть выше разума. Их звериные формы укрепляют тела различными способами.","name":"+2 Мудрость, -2 Интеллект, +2 к значению одной физической характеристике в звериной форме"},{"description":"Шкурокожие - существа среднего размера, что не даёт им никаких бонусов или штрафов.","name":"Средний размер (Medium)"},{"description":"Базовая скорость шкурокожих - 30 футов.","name":"Нормальная скорость (Normal Speed)"},{"description":"Шкурокожие видят вдвое дальше людей в сумерках.","name":"Сумеречное зрение (Low-Light Vision)"},{"description":"Шкурокожие с Мудростью 11 и выше получают возможность творить раз в день псевдозаклинание разговор с животными, используя модификатор Мудрости для проверок концентрации. Уровень заклинателя для этой способности равен уровню персонажа.","name":"Псевдозаклинание (Spell-Like Ability)"},{"description":"Шкурокожие получают +2 (народ) к проверкам Дрессировки и пониманию животных.","name":"Животный разум (Animal-Minded)"},{"description":"Шкурокожий может сменить форму на звериную в качестве основного действия. В звериной форме он получает +2 (народ) к Силе, Ловкости или Выносливости на выбор. В этой форме он также приобретает дающие особые эффекты анималистические особенности. Каждый раз, когда шкурокожий принимает звериную форму, он может выбрать, что получить: две атаки когтями, каждая из которых наносит 1d4 урона, ночное зрение 60 футов или бонус естественной брони +1. Эти преимущества действуют до тех пор, пока он не вернется в свою гуманоидную форму в качестве быстрого действия. Шкурокожий должен сначала вернуться в гуманоидную форму, прежде чем снова принять звериную, чтобы изменить преимущества.","name":"Смена формы (Change Shape) (Св)"},{"description":"Шкурокожие начинают игру со знанием всеобщего языка. Шкурокожие с высоким значением Интеллекта могут изучить любые дополнительные языки (кроме тайных, таких как друидический).","name":"Языки (Languages)"}]},{"alignmentAndReligion":"Обычно нейтральное.","book":"Inner Sea World Guide","description":"За свои владения в горах стриксы отчаянно дерутся как на земле, так и в воздухе. Опасные, но мудрые стриксы предпочли бы тихо жить среди башен Дьяволова Насеста в Челии, но время и традиции научили их не доверять бескрылым обитателям побережья и долин. Они знают, что только страх может защитить их от посягательств бескрылых. К счастью, стриксы преуспели в искусстве кровопролития. Стриксы привыкли ненавидеть людей, хотя причин этой ненависти не знает никто, кроме самих стриксов. Скорее всего, дело в многочисленных кровавых вторжениях в их земли, неудачном первом столкновении или в еще более древней вражде.","favoredClass":[{"alias":"witch","description":"Добавьте одно заклинание из списка заклинаний ведьмы фамильяру ведьмы. Это заклинание должно быть по крайней мере на 1 уровень ниже самого высокого уровня заклинания, которое ведьма может сотворить. Если ведьма заменит своего фамильяра, новый фамильяр будет знать эти дополнительные заклинания.","name":"Ведьма"},{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"shaman","description":"Добавьте 1/2 к эффективному классовому уровню шамана для определения бонуса естественной брони, Интеллекта и специальных способностей его духовного зверя.","name":"Шаман"}],"kind":"race","nameEn":"Strix","nameRu":"Стрикс","physicalDescription":"Этот гибкий мускулистый гуманоид с черной как уголь кожей укрывается оперёнными крыльями, словно плащом. В среднем стриксы чуть выше 6 футов, мужчины и женщины примерно одного роста. Для этого народа характерны заострённые уши, глаза без зрачков и ноздри в виде узких щелей, но главная черта их внешности - это, конечно, крылья 12 футов в размахе. Взрослый стрикс весит около 170 фунтов. Обычно стриксы живут около 40 лет, старейшие доживают до 60.","slug":"strix","traits":[{"description":"Стриксы используют уровни в классах - у них нет КЗ народа","name":""},{"description":"Стриксы быстры и увёртливы, но упрямы и легко впадают в ярость.","name":"+2 Ловкость, -2 Харизма"},{"description":"У стриксов скорость полета 60 футов (средняя маневренность).","name":"Полёт"},{"description":"При тусклом свете стриксы видят вдвое дальше людей.","name":"Сумеречное зрение"},{"description":"Стриксы видят в темноте на расстоянии до 60 футов.","name":"Ночное зрение"},{"description":"Стриксы получают бонус +1 к проверкам атаки против гуманоидных существ с подтипом «человек» поскольку их специально учат сражаться с этими ненавистными врагами.","name":"Ненависть (Экс)"},{"description":"Стриксы получают бонус +2 (народ) к проверкам Внимания и Скрытности при тусклом свете или в темноте.","name":"Ночной"},{"description":"Стриксы получают бонус +2 (народ) к испытаниям против заклинаний и эффектов иллюзии.","name":"Подозрительность"},{"description":"Стриксы начинают игру со знанием языка стриксов. Стриксы с высоким значением Интеллекта могут выбрать дополнительные языки из следующих: ауран, ацланти, великаний, всеобщий, гномий, гоблинский, драконий, дьявольский.","name":"Языки"}]},{"alignmentAndReligion":"Обычно нейтральное.","book":"Advanced Race Guide","description":"Сули (или сули-джанн) - это небольшое ответвление джанн, которые живут среди людей. Они высокие и выглядят как обычные мужчины и женщины, но минуя их ненормальную красоту можно увидеть всплеск элементарного света в их глазах. Будучи физически одареннее и привлекательнее, чем обычные люди, некоторые сули-джанны не знают о своем наследие до того момента, пока они не вступят в контакт с чистокровным гением, который может пробудить в них силу. В то время как все сули могут проследить свою родословную до первоначального Джанн-предка, очень немногие имеют самих родителей джанн. В большинстве случаев это наследие дремлет в крови поколениями, только чтобы пробудиться десятилетия или даже столетия спустя. Жизнь Сули, чья сила пробудилась слишком рано, полна проблем и сложностей. Вопрос о непонятном происхождении ребенка вносит разлад во многие семьи. Некоторые из несчастных Сули выросли так и не узнав родительской любви и теплоты домашнего уюта. Сули стареют также как и люди, и схожи с ними по росту и весу. В детстве сули, как правило, немного меньше, чем их человеческие сверстники, но быстро нагоняют их по достижении подросткового возраста. Сули импульсивны и страстны по натуре. При этом сули, которые не знают о своем наследии обладают чрезмерным чувством гордости.","favoredClass":[{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"}],"kind":"race","nameEn":"Suli","nameRu":"Сули","physicalDescription":"Этот изящно сложенный гуманойд носит экзотическкую одежду, его глаза горят ярким светом, а руки покрыты потрескивающим пламенем.","slug":"suli","traits":[{"description":"Сули используют уровни в классах - КЗ народа у них нет.","name":""},{"description":"Сули мускулистые и очаровательные, но недогадливые.","name":"+2 к Силе, +2 к Харизме, -2 к Интеллекту"},{"description":"Сули - потусторонние существа с подтипом местное.","name":"Местное потустороннее существо"},{"description":"Сули - существа среднего размера, что не дает им никаких бонусов или штрафов.","name":"Средний"},{"description":"Базовая скорость Сули составляет 30 футов.","name":"Нормальная скорость"},{"description":"Сули видят в сумерках вдвое дальше людей.","name":"Сумеречное зрение"},{"description":"Сули - заядлые переговорщики, и они получает бонус народа +2 на проверках Дипломатии и Проницательность.","name":"Переговорщик"},{"description":"Один раз в день в качестве быстрого действия сули может окутать свои руки кислотой, холодом, электричеством или огнём. Этот эффект длится 1 раунд на уровень и может быть отменён в качестве свободного действия. Безоружные удары руками или атаки оружием в этих руках наносят +1d6 пунктов урона соответствующего типа энергии.","name":"Стихийная атака"},{"description":"Сули имеют устойчивость к кислоте 5, холоду 5, электричеству 5 и огню 5.","name":"Устойчивость к энергии"},{"description":"Сули начинают игру, говоря на всебщем и одном стихийном языке (акване, ауране, игнане или терране). Сули с высокими показателями Интеллекта может выбирать из следующих языков: акван, ауран, драконий, игнан и терран.","name":"Языки"}]},{"alignmentAndReligion":"Обычно нейтральный.","book":"Bestiary 1","description":"Свирфнеблины, или глубинные гномы, - боковая ветвь народа гномов, предпочитающая уединение. Они обитают в городах, скрытых глубоко под землёй, где им не угрожают ни тёмные эльфы, ни другие подземные народы. Цветом их кожа напоминает серый или коричневый камень. У женщин тонкие серые волосы, а мужчины полностью лысые. Связь этих гномов с миром фей гораздо прочнее, чем у их родичей, живущих на поверхности, поэтому они либо совсем не проявляют эмоций, либо выплёскивают их бурно и беспорядочно. Свирфнеблины долгое время воевали с двергарами и не видят особой разницы между ними и прочими дварфами.","favoredClass":[{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"}],"kind":"race","nameEn":"Svirfneblin","nameRu":"Свирфнеблин","physicalDescription":"Кожа этого жилистого лысого гнома серая, а бледные глаза чересчур велики и выразительны.","slug":"svirfneblin","traits":[{"description":"Свирфнеблины используют уровни в классах - КЗ народа у них нет.","name":""},{"description":"Свирфнеблины ловки и наблюдательны, но достаточно слабы и безэмоциональны.","name":"-2 Сила, +2 Ловкость, +2 Мудрость, -4 Харизма"},{"description":"Свирфнеблины - существа небольшого размера, поэтому они получают +1 (размер) к КБ, +1 (размер) к атакам, -1 к МБМ и ЗБМ и +4 (размер) к проверкам Скрытности.","name":"Небольшой размер"},{"description":"Свирфнеблины получают бонус +2 (уклонение) к КБ.","name":"Умение защищаться"},{"description":"Свирфнеблины обладают ночным зрением 120 футов и сумеречным зрением.","name":"Восприятие"},{"description":"Свирфнеблины получают +2 (народ) ко всем испытаниям.","name":"Удачливый"},{"description":"Свирфнеблины получают +2 (народ) к проверкам Скрытности, увеличивающийся до +4 под землёй. Кроме этого, они получают +2 (народ) к проверкам Внимания и Ремесла (алхимик).","name":"Умелый"},{"description":"Свирфнеблины получают +1 к атакам по гуманоидам с подтипами «дварф» или «рептилоид», так как обучены сражаться против своих кровных врагов.","name":"Ненависть"},{"description":"Свирфнеблины получают +2 к проверкам Внимания при обнаружении странностей в каменной кладке (например, ловушек или потайных дверей, скрытых в стенах или полу). Каждый раз, когда свирфнеблин оказывается на расстоянии 10 футов от такого места, он автоматически совершает эту проверку, даже если не занимается активным поиском.","name":"Знание камня"},{"description":"Свирфнеблины обладают УкМ, равной числу их уровней в классах + 11.","name":"Устойчивость к магии"},{"description":"СЛ испытаний против заклинаний школы иллюзии, сотворенных свирфнеблинами, повышается на +1. Кроме этого, они получают псевдозаклинания, перечисленные ниже. УЗ для них равен уровню персонажа); Постоянные - необнаружимость. 1/день - изменение облика, расплывчатость, слепота/глухота (СЛ 11).","name":"Свирфнеблинская магия"},{"description":"Свирфнеблины начинают игру со знанием гномьего и подземного языков. Свирфнеблины с высоким значением Интеллекта могут выбрать дополнительные языки из следующего списка: акло, великаний, всеобщий, гоблинский, дварфийский, драконий, орочий, терран, эльфийский.","name":"Языки"}]},{"adventurers":"Врожденное стремление докопаться до сути вещей толкает многих сильфов к приключенческой жизни. Сильф, идущий по следу тайны, никогда не будет удовлетворенным, пока он не раскроет каждую нить доказательств, отслеживая все зацепки и попадая в самый центр опасностей. Такие сильфы наживают много врагов, копаясь в чужих делах, и обычно обращаются к своим мошенническим талантам или волшебству, чтобы защититься.","alignmentAndReligion":"Сильфы мало уважают законы и традиции, поскольку такие ограничения часто запрещают именно то, что любят сильфы - уловки и секретность. Это не означает, что сильфы противостоят закону, они лишь используют самые целесообразные средства, доступные для достижения их целей, законные они или нет. Большинство сильфов, таким образом, имеют нейтральное мировоззрение. Сильфов естественно тянет к мистическим культам и божествам, которые сосредоточены на секретах, путешествиях или знаниях.","book":"Advanced Race Guide","description":"Родившиеся от людей и элементалей воздуха, таких как джинны, сильфы - застенчивый и замкнутый народ, поглощённый сильным любопытством. Сильфы тратят свои жизни, сливаясь с толпой и оставаясь незамеченными, шпионят и подслушивают окружающих их людей. Они называют это хобби «слушать ветер», и для многих сильфов это становится навязчивой идеей. Сильфы полагаются на свои способности, расчетливый интеллект и на основы полученных знаний от подслушивания, чтобы избавить их от опасности.","favoredClass":[{"alias":"witch","description":"Добавьте бонус +1/2 к проверкам Скрытности и Внимания фамильяра ведьмы. Если сильф заменит своего фамильяра, новый фамильяр получает эти дополнительные очки.","name":"Ведьма"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"}],"kind":"race","nameEn":"Sylph","nameRu":"Сильф","names":[{"isMale":true,"name":"Акааш"},{"isMale":true,"name":"Эйдан"},{"isMale":true,"name":"Хануун"},{"isMale":true,"name":"Сиивал"},{"isMale":true,"name":"Васаам"},{"isMale":false,"name":"Инам"},{"isMale":false,"name":"Кея"},{"isMale":false,"name":"Лисси"},{"isMale":false,"name":"Нава"},{"isMale":false,"name":"Радая"},{"isMale":false,"name":"Тена"}],"physicalDescription":"Сильфы обычно бледны и худощавы, кажутся нежными, но их тощие тела часто более устойчивы, чем кажется. Многие сильфы легко могут с некоторыми усилиями сойти за человека, хотя сложные синие отметины, которые кружатся на их коже, показывают их элементальное происхождение. Сильфы также несут более тонкие знаки своего наследия, например, лёгкий ветерок, преследующий их, куда бы они ни пошли. Эти признаки становятся более выраженными по мере того, как сильф испытывает сильную страсть или гнев: спонтанные порывы ветра взъерошивают волосы сильфа или горячие взрывы сбивают мелкие предметы с полок.","relations":"Сильфы любят вмешиваться в дела большинства людей и других народов, но они проявляют мало интереса в общении с большинством из них. Сильфы на хоть каком-то уровне могут относиться к эльфам, разделяющих их склонность к отчуждению, но часто они портят любые возможные отношения, нарушая эльфийское чувство уединения. Дварфы не доверяют сильфам, считая их ветреными и ненадежными. Они образуют отличные партнерские отношения с полуросликами, полагаясь на храбрость коротышки и умение прикрывать свои собственные недостатки. Сильфов забавляют раздраженные реакции, которые они вызывают в афритах, и находят ореадов слишком скучными, чтобы уделять им много внимания.","slug":"sylph","society":"Сильфы обычно рождаются от человеческих родителей, и поэтому воспитаны согласно человеческим обычаям. Большинство сильфов не любят внимание, которое они получают в человеческом обществе, поэтому они часто покидают дом вскоре после того, как подрастают. Однако они редко полностью отказываются от цивилизации, предпочитая вместо этого найти какой-нибудь новый город или поселок, где они могут остаться незамеченными среди людей, при этом следя за ними. Сильф, который незаметно встречается с другим сильфом, мгновенно становится одержимым своей семьей, шпионит и узнаёт о партнёре как можно больше. Только взвесив все за и против и сформулировав планы для каждого потенциального исхода, сильф представится ему. Нередко два сильфа обнаруживают присутствие друг друга в обществе одновременно. После этого происходит что-то вроде игры в кошки-мышки, запутанный танец, в котором каждый сильф шпионит за другим сильфом, и оба пытаются одержать верх. Сильфы, которые всегда так встречаются, становятся либо неразлучными друзьями, либо непримиримыми врагами.","traits":[{"description":"Сильфы используют уровни в классах - КЗ народа у них нет.","name":""},{"description":"Сильфы быстры и проницательны, но слабы и хрупки.","name":"+2 Ловкость, +2 Интеллект, -2 Выносливость"},{"description":"Сильфы - потусторонние существа с подтипом природный.","name":"Природное потусторонне существо"},{"description":"Сильфы - существа среднего размера и не имеют бонусов или штрафов из-за их размера.","name":"Средний"},{"description":"Базовая скорость сильфов составляет 30 футов.","name":"Нормальная скорость"},{"description":"Сильфы могут видеть в темноте до 60 футов.","name":"Ночное зрение"},{"description":"плавное падение 1/день (УЗ равен общему уровню сильфа).","name":"Псевдозаклинания"},{"description":"Сильфы обладают сопротивлением электричеству 5.","name":"Сопротивление энергии"},{"description":"Сильфы-чародеи со стихийным (воздушным) наследием рассматривают свою Харизму на 2 пункта выше для всех заклинаний чародея и классовых способностей. Сильфы-жрецы со сферой Воздуха используют свои силы сферы и заклинания, как если бы УЗ был на 1 выше.","name":"Родство с воздухом"},{"description":"Сильфы начинают игру, говоря на Всеобщем и Ауране. Сильфы с высоким Интеллектом могут выбрать дополнительный язык из следующего списка: Акван, Гномий, Эльфийский, Дварфийский, Полуросличий, Игнан и Терран.","name":"Языки"}]},{"alignmentAndReligion":"Обычно нейтральный.","book":"Bestiary 1","description":"Тэнгу - народ птицеподобных гуманоидов, внешне напоминающих воронов и ворон, и потому отношение к ним порой соответствующее. Они часто соседствуют с другими народами, населяющими крупные города, но их сообщества крепко сплочены и закрыты, они редко допускают в свой круг чужаков. Тэнгу часто объединяются в небольшие группы и обустраивают гнёзда на пустых складах или в домах под снос, которые из-за шума и возни часто принимают за гильдии воров, хотя примерно в половине случаев это не так. Подобно воронам тэнгу по природе своей любят блестящие или цветастые предметы и зачастую ненароком прикарманивают их, если не в силах удержаться. Они тщеславны и горды, поэтому лесть творит чудеса при попытках их в чём-то убедить.","favoredClass":[{"alias":"witch","description":"Добавьте одно заклинание из списка заклинаний ведьмы фамильяру ведьмы. Это заклинание должно быть, как минимум на один уровень ниже самого высокого уровня заклинания, которое она может использовать. Если ведьма заменит своего фамильяра, новый фамильяр будет знать эти дополнительные заклинания.","name":"Ведьма"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"}],"kind":"race","nameEn":"Tengu","nameRu":"Тэнгу","physicalDescription":"Всё тело этого гуманоида с головой ворона покрыто чёрным оперением, а его руки и ноги выглядят как птичьи лапы.","slug":"tengu","traits":[{"description":"Тэнгу используют уровни в классах - КЗ народа у них нет.","name":""},{"description":"Тэнгу проворны и наблюдательны, но достаточно хрупки.","name":"+2 Ловкость, -2 Выносливость, +2 Мудрость"},{"description":"Тэнгу - существа среднего размера и не получают ни бонусов, ни штрафов.","name":"Средний размер"},{"description":"Тэнгу обладают сумеречным зрением.","name":"Восприятие"},{"description":"Тэнгу получают +2 (народ) к проверкам Внимания и Скрытности.","name":"Скрытный"},{"description":"Тэнгу получают +4 (народ) к проверкам Языкознания и при получении пункта в Языкознании изучают 2 языка вместо 1.","name":"Одарённый лингвист"},{"description":"Тэнгу с рождения обучаются искусству владения мечом и в результате умеют обращаться со всеми мечами и схожим оружием (включая двуручные мечи, длинные и двухклинковые мечи, кинжалы, короткие мечи, кукри, мечи-бастарды, тычковые кинжалы, рапиры, скимитары, фальшионы и эльфийские сабли).","name":"Обращение с клинками"},{"description":"Тэнгу могут атаковать противника укусом, нанося 1d3 урона при попадании. Это основная атака либо вспомогательная, если тэнгу вооружён рукотворным оружием.","name":"Естественное оружие"},{"description":"Тэнгу начинают игру со знанием всеобщего языка и собственного диалекта языка тэнгу. Тэнгу с высоким значением Интеллекта могут выбирать любые дополнительные языки (кроме тайных, таких как друидический).","name":"Языки"}]},{"alignmentAndReligion":"Обычно нейтральный злой.","book":"Bestiary 1","description":"Тифлинги - люди, предком которых был демон, дьявол или иное злое потустороннее существо. Как правило, тифлинги часто становятся изгоями из-за внешности или странного поведения, поэтому они вынуждены скрывать своё происхождение либо жить в трущобах или на задворках цивилизации. Сами по себе они не злы, но легко становятся таковыми, настрадавшись в детстве от нападок «нормальных» людей. Тифлинги выглядят как люди, за исключением пары черт внешности, выдающих необычное происхождение.","favoredClass":[{"alias":"witch","description":"Фамильяр ведьмы получает устойчивость 1 к огню, холоду или электричеству. Каждый раз, когда ведьма выбирает этот бонус, увеличивайте устойчивость фамильяра одному из этих типов стихии на 1 (максимум 5 для любого типа). Если ведьма когда-нибудь заменит своего фамильяра, к новому фамильяру перейдет эта устойчивость.","name":"Ведьма"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"}],"kind":"race","nameEn":"Tiefling","nameRu":"Тифлинг","physicalDescription":"Долговязый мужчина, ухмыляясь, обнажает меч. Маленькие рожки и шипастый хвост красноречиво намекают, что он не просто человек.","slug":"tiefling","traits":[{"description":"Тифлинги используют уровни в классах - КЗ народа у них нет.","name":""},{"description":"Потустороннее существо.","name":"Тип"},{"description":"Тифлинги быстро действуют и соображают, но по природе своей странноваты.","name":"+2 Ловкость, +2 Интеллект, -2 Харизма"},{"description":"Тифлинги могут видеть в темноте на расстоянии до 60 футов.","name":"Ночное зрение"},{"description":"Тифлинги получают +2 (народ) к проверкам Блефа и Скрытности.","name":"Умелый"},{"description":"Тифлинги могут раз в день сотворить псевдозаклинание тьма. УЗ для него равен уровню персонажа.","name":"Псевдозаклинания"},{"description":"Тифлинги получают устойчивость к огню 5, устойчивость к холоду 5, устойчивость к электричеству 5.","name":"Устойчивость бестий"},{"description":"При применении любой классовой особенности чародеев значение Харизмы тифлингов-чародеев с демоническим или дьявольским наследием считается на 2 пункта выше.","name":"Магия бестий"},{"description":"Тифлинги начинают игру со знанием всеобщего и либо демонического, либо дьявольского языков. Тифлинги с высоким значением Интеллекта могут выбрать дополнительные языки из следующего списка: гномий, гоблинский, дварфийский, демонический, драконий, дьявольский, орочий, полуросличий, эльфийский.","name":"Языки"}]},{"alignmentAndReligion":"Обычно хаотичное нейтральное.","book":"Bestiary 4","description":"Троксы когда-то были членами куда более малочисленной расы покорных копателей, но были давно порабощены расой двергаров и использовались как какой-то полезный скот. Однако некоторые кланы троксов смогли сбежать от своих поработителей и достигли внешнего мира, при этом их поработители не торопились оставлять их в покое. Большинство троксов так и живут в служении своим хозяевам. Свободный трокс - это верный друг, для тех кого он считает своим товарищем. Они очень любознательны, но при этом склонны испытывать чувство глубокой зависти и обиды.","favoredClass":[{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"}],"kind":"race","nameEn":"Trox","nameRu":"Трокс","physicalDescription":"Эта неповоротливая громадина обладает двумя массивными мускулистыми руками и группой четырех более мелких рук, выступающих под его ребрами.","slug":"trox","traits":[{"description":"Троксы используют уровни в классах - КЗ народа у них нет. Несмотря на отсутствие КЗ народа, трокс - могущественное существо, и его КО на 2 выше, чем у человека того же уровня.","name":""},{"description":"Гуманоидное чудовище.","name":"Тип"},{"description":"Троксы очень сильные, но мрачные и не особо дружелюбные.","name":"+6 к Силе, -2 к Харизме, -2 к Интеллекту, - 2 к Мудрости"},{"description":"Троксы имеют базовую скорость 30 футов.","name":"Обычная скорость"},{"description":"Троксы большие по размеру существа и имеют штрафы: -1 к КБ, -4 к проверкам Скрытности, но при этом получают бонус +1 к МБМ и ЗБМ.","name":"Большой"},{"description":"Троксы видят в темноте на расстоянии 60 футов.","name":"Ночное зрение"},{"description":"скорость копания у Троксов 20 футов","name":"Копатель"},{"description":"Раз в день, получая урон, Трокс впадает в бешенство на 1 мин, получая расовый бонус +2 к Выносливости и Силе, но при этом его КБ снижается на 2.","name":"Бешенство"},{"description":"Маленькие руки трокса полезны не более чем для захвата. Трокс получают Захват+ в качестве бонусной черты и может поддерживать захват и при этом атаковать своими основными руками.","name":"Цепляющие придатки"},{"description":"Троксы начинают игру со знанием языка терран. Троксы с высоким показателем Интеллекта могут выбрать следующие языки: общий, дварфийский, великаний, подземный, орочий.","name":"Языки"}]},{"adventurers":"Иногда ундина покидает свой народ искать жизнь, полную приключений. Как и сама вода, некоторые Ундины просто вынуждены двигаться, и приключения дают им хороший повод жить в дороге. Другие путешествуют по менее благотворным причинам, а изгнание - это обычное наказание за преступления в обществе ундин. Не имея других вариантов, большинство изгнанников обращаются к приключениям, надеясь найти новое место в мире. Близость Ундин к воде делает их особенно хорошими друидами, в то время как у чародеев-ундин обычно водное наследие.","alignmentAndReligion":"Большинство ундин нейтральны. Их основные интересы заключаются в благополучии их народа, и поэтому их моральные заботы сосредоточены на сообществе и на себе. Такой нейтральный взгляд также позволяет им взаимодействовать с широким кругом не-ундинских народов, с которыми они торгуют. Будучи не глубоко религиозными, ундины обладают как сильной духовной связью с их сверхъестественным предками, так и связью с самой водой. Те, кто преследуют не мирские пути, почти всегда поклоняются богам своих предков или богам, чьи Планы связаны с водой.","book":"Advanced Race Guide","description":"Ундины - это люди, чья родословная связана с существами из Водного Плана. Даже с первого взгляда вы заметите силу их предков в толстой коже ундины, имитирующей цвет озер, морей и океанов. Имея кровь маридов или водяных мефитов в качестве своих родственников, все Ундины определяют себя через свое происхождение. Они воспринимают их индивидуальные различия как дары и потому исследуют сверхъестественные аспекты их уникального наследия в полной мере. Ундины - гордый народ, что мало проявляет страх. В то же время добродушные и несколько игривые среди себе подобных, они ведут себя немного более сдержанно и серьезнее в компании не-ундинов. Они имеют превосходный контроль над эмоциями и умеют менять свой нрав от спокойствия до ярости и обратно в течение нескольких минут. Хотя некоторые могут назвать их поведение беспорядочным, ундины просто внешне немного мелодраматичнее, чем большинство народов. Конечно, они не капризны и не злятся, возбуждены или иным образом эмоциональны без провокации. При близком знакомстве, некоторые находят их излишне собственническими, хотя они также чрезвычайно защищают тех, кто им небезразличен. Ундины, как правило, селятся возле воды, обычно в местах теплого климата. Хоть они и наземные жители, они проводят большую часть своего времени в воде. По этой причине большинство их них одевается редко; они носят достаточно одежды, чтобы защитить себя от элементов, и немногие носят обувь. Они избегают ношения украшений на шее, причёсывают волосы назад или завязывают их тугими узлами. Это предотвращает появление волос и других объектов, отвлекающих или мешающих плаванию. Точно так же ундины, занимающиеся боевыми искусствами, выбирают оружие, которым они могут эффективно владеть как на суше, так и в воде.","favoredClass":[{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"}],"kind":"race","nameEn":"Undine","nameRu":"Ундина","names":[{"isMale":true,"name":"Авен"},{"isMale":true,"name":"Дхарак"},{"isMale":true,"name":"Гив"},{"isMale":true,"name":"Джамаш"},{"isMale":true,"name":"Маакор"},{"isMale":true,"name":"Ондир"},{"isMale":true,"name":"Радид"},{"isMale":true,"name":"Ширадаз"},{"isMale":false,"name":"Афзара"},{"isMale":false,"name":"Баара"},{"isMale":false,"name":"Кала"},{"isMale":false,"name":"Ириани"},{"isMale":false,"name":"Маарин"},{"isMale":false,"name":"Нылгуне"},{"isMale":false,"name":"Пари"},{"isMale":false,"name":"Радабех"},{"isMale":false,"name":"Урдахна"}],"physicalDescription":"Ундины имеют широкий диапазон оттенков кожи, от бледно-бирюзового до темно-синего и морской зелени. Прямые густые волосы ундины имеют тенденцию быть похожими на кожу, но немного более темного цвета. Все из них имеют прозрачные голубые глаза. Физически ундины больше всего напоминают людей, и их телосложение показывает человеческое разнообразие с учетом общего роста и телосложения. Помимо их окраски, их самыми заметными чертами остаются их похожие на плавники уши и перепончатые руки и ноги.","relations":"Ундины не имеют предубеждений по отношению к каким-то конкретным народам. Их общины полагаются в первую очередь на торговлю, давая им широкие возможности взаимодействовать с разнообразным кругом посторонних существ и иноземцев. Они не сомневаются в создании кварталов в поселениях других народов, что даются при условии должного уважения, как к ундинам, так и ко всем близлежащим водоемам. Тем не менее, в таких случаях данное сообщество ундин стараются сохранить свою автономию. Ундины довольно хорошо ладят с эльфами и гномами. Часто эти народы разделяют обязанности по защите лесных угодий, озер и ручьев. Точно так же они благоприятно взаимодействуют с добрыми или нейтральными водными гуманоидами, разделяющими многие общие интересы. Они наиболее свободно торгуются с людьми и дварфами за такие ресурсы, как металл и ткань.","slug":"undine","society":"Ундины определяют себя как уникальный народ, способный производить потомство ундин. В то время как они остаются способными к скрещиванию с людьми, они, как правило, сохраняют самих себя, и образуют небольшие затворнические сообщества рядом с водоемами или, в некоторых случаях, плавучие поселения. Типичное сообщество ундин живет под руководством небольшого Совета, состоящего из официальных лиц, назначенного консенсусом. Должности в Совете могут быть заняты неограниченное время, хотя сообщество, недовольное производительностью членов совета, может потребовать его отставки. Смешанные браки в общинах ундин распространены, так что дети воспитываются совместно. Изрядное количество регионального разнообразия существует в культуре ундинов под влиянием специфической родословной самостоятельных поселений. Также следует отметить, что не все ундины в одном поселении претендуют на одно и то же происхождение, поскольку ундины могут выйти замуж за других ундин за пределами своих общин.","traits":[{"description":"Ундины используют уровни в классах - КЗ народа у них нет.","name":""},{"description":"Ундины и наблюдательны, и проворны, но склонны приспосабливаться, а не противостоять силе силой.","name":"+2 Ловкость +2 Мудрость, -2 Сила"},{"description":"Ундины - потусторонние существа с подтипом природный.","name":"Природное потусторонне существо"},{"description":"Ундины - существа среднего размера и не получают никаких бонусов или штрафов из-за своего размера.","name":"Средний размер"},{"description":"Базовая скорость ундин составляет 30 футов на суше. Скорость их плавания равна 30 футов, они могут двигаться в воде, не делая проверок Плавания, и Плавание всегда считается для них классовым навыком.","name":"Нормальная скорость"},{"description":"Ундины могут видеть в темноте до 60 футов.","name":"Ночное зрение"},{"description":"гидравлический толчок 1/день (УЗ равен уровню Ундины).","name":"Псевдозаклинание"},{"description":"У ундин имеется сопротивление холоду 5.","name":"Сопротивление энергии"},{"description":"Чародеи-ундины со стихийным (водным) наследием считают свой показатель Харизмы на 2 пункта выше для всех заклинаний чародея и классовых способностей. Жрецы-ундины со сферой Воды используют свои силы сфер и заклинания как если бы их УЗ был на 1 выше.","name":"Родство с водой"},{"description":"Ундины начинают игру, говоря на Всеобщем и Акван. Ундины с высоким показателем Интеллекта могут выбрать дополнительные языки из следующего списка: Ауран, Дварфийский, Эльфийский, Гномий, Полуросличий, Игнан и Терран.","name":"Языки"}]},{"alignmentAndReligion":"Обычно принципиальное доброе.","book":"Bestiary 3","description":"Ванара - это умные, обезьяны гуманоиды, которые живут в густых леса и джунглях. Они ловкие и умные, но страдают излишним любопытством и тягой к шуткам с розыгрышам. Обычно они безвредны и не представляют угрозу для того с кем сталкиваются. Тело Ванара покрыто тонким слоем мягкого меха, обычно каштанового оттенка, но встречаются особи с окрасом меха слоновой кости и даже золотистым окрасом. Несмотря на свой мех, Ванар может отращивать длинные волосы на голове как у человека. У мужчин и женщин Ванар могут быть сложные прически для подчеркивания тех или иных социальных ролей. Волосы на голове Ванара схожи по цвету с его мехом. Все Ванары имеют длинные цепкие хвосты и стопы похожие на кисти, которые с легкостью могут выполнять функции рук. Ванара в росте немного уступает среднестатистическому человеку. Мужчины Ванары весят от 150 до 200 фунтов, женщины чуть меньше. Продолжительность жизни Ванар от 60 до 75 лет. Ванары живут в больших деревнях на верхушках деревьев, соединенных между собой канатными мостами и лестницами. Их дома вырезаны в стволах деревьев, но могут сочетать в себе рукодельные элементы такие как навесы из палок и завесы из листьев. Ванарские общины обычно управляются религиозным лидером будь то священнослужитель, оракул или монах.","favoredClass":[{"alias":"witch","description":"Добавьте 1/4 к УЗ ведьмы при определении эффектов заклинаний, дарованных ей ее покровителем (максимум +2).","name":"Ведьма"},{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"shaman","description":"Добавьте 1 заклинание из списка заклинаний жреца, которого нет в списке заклинаний шамана, к списку заклинаний, которые знает шаман. Заклинание должно быть хотя бы на 1 круг меньше максимального круга, который может применять шаман.","name":"Шаман"}],"kind":"race","nameEn":"Vanara","nameRu":"Ванара","physicalDescription":"Этот худощавого телосложения, обезьяноподобный гуманойд покрыт слоем мягкого, едва окрашенного меха и имеет длинный цепкий хвост.","slug":"vanara","traits":[{"description":"Варана используют уровни в классах - КЗ народа у них нет.","name":""},{"description":"Ванары от природы ловкие и проницательные, но слишком озорные, что может раздражать.","name":"+2 к Ловкости, +2 к Мудрости, -2 к Харизме"},{"description":"Ванара лазает со скоростью 20 футов.","name":"Скорость лазания"},{"description":"Ванары видят в сумерках вдвое дальше людей.","name":"Сумеречное зрение"},{"description":"Ванары получают расовый бонус +2 Акробатике и Скрытности.","name":"Проворный"},{"description":"У всех ванар есть длинный подвижный хвост, при помощи которого они могут хватать объекты. Они не могут держать в нём оружие, но они способны выхватывать им небольшие предметы для использования в собственных нуждах к качестве свободного действия.","name":"Цепкий хвост (Prehensile Tail) (Экс)"},{"description":"Ванара начинают игру владея языками общим и ванарским. Ванара с высоким показателем Интеллекта могут выбрать следующие языки: акло, небесный, эльфийский, гномий, гоблинский и сильван.","name":"Языки"}]},{"adventurers":"Как и большинство леших, лиановые обычно не боятся смерти. Они знают, что если их тело умрёт, дух вернётся в мир природы и однажды может оказаться в новом теле. Это отсутствие страха в сочетании с любопытством заставляет их идти на риск. Тем не менее, они обычно избегают чрезмерно опасных занятий, так как предпочитают составлять историю из своих приключений, чтобы рассказать позже. Лиановые лешие тяготеют к классам, которые позволяют им использовать связь с природой, такими как друид и следопыт.","alignmentAndReligion":"Лиановые лешие считают себя частью древнего цикла природы. Они заботятся о своих друзьях и любых природных территориях, находящихся под их опекой, но редко чувствуют принуждение к благотворительности или злому умыслу. Большинство лиановый леших полностью нейтральны, и почти всегда в их мировоззрении есть хотя бы один нейтральный аспект. Религия не имеет особого значения для лиановых леших. Те, кто действительно находит веру, склонны поклоняться Гозрею, зеленому человеку или одному из Старейших из Первого Мира, но зелёная вера является наиболее распространенной философией, которой они следуют.","altTraits":[{"description":"Проворные лиановые лешие быстрее, но менее выносливы, чем типичные лиановые лешие. Замените бонус народа леших +2 к Выносливости на бонус народа +2 к Ловкости.","name":"Гибкий (Agile)","related":["+2 <a href=\"/ability/constitution\" class=\"link\">Выносливость</a>, +2 <a href=\"/ability/wisdom\" class=\"link\">Мудрость</a>, -2 <a href=\"/ability/intelligence\" class=\"link\">Интеллект</a>"]},{"description":"Лиановые лешие, сделанные из лоз ядовитого плюща, несут в своем теле природный яд. В качестве быстрого действия леший может пропитать свои лианы этим раздражающим веществом. В следующий раз, когда леший ударит существо безоружным ударом, существо будет поражено следующим ядом. Токсин лианового лешего (Vine Leshy Toxin): Безоружный удар - ранение; Испытание: Стойкости со СЛ 10 + 1/2 КЗ лианового лешего + модификатор Выносливости; Частота: 1/раунд до 6 раундов; Действие: дезориентация на 1 раунд; Лечение: 1 испытание. Леший может использовать эту способность количество раз в день, равное его модификатору Выносливости (минимум 1). Лиановый леший невосприимчив к своему собственному яду, но не к ядам других лиановых леших.","name":"Ядовитый (Poisonous)","related":["<a href=\"/bestiary/appendix/universalMonsterRules?scroll=changeShape\" class=\"link\">Смена формы</a> (Change Shape)","Речь растений (Plantspeech)"]},{"description":"Некоторые лиановые лешие сделаны из растений, которые в природе произрастают на болотах. Эти лешие получают бонус народа +2 к проверкам Плавания и +4 бонус народа к проверкам Скрытности в болотах.","name":"Болотный Леший (Swamp Leshy)","related":["Лазальщик (Climber)","Непритязательная листва (Unassuming Foliage)"]},{"description":"Лиановый леший из виноградной лозы может производить налитые магией плоды, которые исцеляют союзников. Он может использовать вкусные ягоды один раз в день как псевдозаклинание с уровнем заклинателя, равным уровню его персонажа.","name":"Виноградная лоза (Grapevine)","related":["Бесследный шаг (Pass without Trace)"]}],"book":"Ultimate Wilderness","description":"Лиановые лешие рождаются в ходе ритуала, когда друид направляет дух природы в форму растения. Дух природы, который отвечает на призыв ритуала творения лианового лешего, всегда остро ощущает влияние смертных существ. По сравнению с другими лешими, лиановые проще относятся к нерастительным существам и испытывают более глубокое любопытство к чудесам природного мира, помимо тех растений, которые тесно связаны с ними, а также увлекаются обществом людей и других существ.","favoredClass":[{"alias":"alchemist","description":"Добавьте 1/4 к бонусу естественной брони алхимика при использовании его мутагена.","name":"Алхимик"},{"alias":"bard","description":"Добавьте бонус +1/3 к проверкам Исполнения (ораторское искусство), включая проверки прикладного искусства, если бард сначала потратит не менее 10 минут на рассказ истории.","name":"Бард"},{"alias":"druid","description":"Добавьте бонус +1/2 к проверкам понимания животных или понимания растений друида.","name":"Друид"},{"alias":"kineticist","description":"Получите 1/5 черты Дополнительный дикий талант. Эта черта должна быть потрачена на талант элемента дерева.","name":"Кинетик"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"oracle","description":"Оракул с тайной природы или дерева добавляет одно заклинание из списка заклинаний друида, которого нет в списке заклинаний жреца, в список заклинаний оракула; он по-прежнему должен выбрать это заклинание как одно из своих известных заклинаний, чтобы использовать его. Это заклинание должно быть как минимум на 1 уровень ниже, чем самый высокий уровень заклинания, который может сотворить оракул.","name":"Оракул"},{"alias":"rogue","description":"Добавьте бонус +1/2 к проверкам Лазания и к проверкам Скрытности в лесу.","name":"Плут"},{"alias":"ranger","description":"Добавьте бонус +1/2 к проверкам Знания (природа) в излюбленной местности следопыта.","name":"Следопыт"}],"kind":"race","nameEn":"Vine Leshy","nameRu":"Лиановый леший","names":[{"isMale":false,"name":"Болтающий Водопад"},{"isMale":false,"name":"Восхитительные Тройные Листья"},{"isMale":false,"name":"Искусный Пьющий Солнце"},{"isMale":false,"name":"Снежные Сосновые Ветви"},{"isMale":false,"name":"Зелёный Ткач Историй"},{"isMale":false,"name":"Трепещущий Взбирающийся по Деревьям"}],"physicalDescription":"Тело лианового лешего состоит из множества скрученных лиан и листьев, иногда также включающих цветы и фрукты. Их внешний вид в основном определяется видом лианы, использованной при создании, но у большинства из них есть большая гроздь листьев, которая образует лицо с круглыми глазами, маленьким ртом и без видимого носа.","relations":"Лиановые лешие заинтересованы в изучении культур многих других народов. Их первоначальное отношение к новым народам основано на предубеждениях из прошлых воплощений природного духа, но со временем они развиваются благодаря опыту леших. В незнакомых ситуациях лешие предпочитают сливаться с растительностью, чтобы понаблюдать, прежде чем выйти и представиться. В соответствии с видами растений, из которых сделаны их тела, лиановые лешие проявляют спектр полов. Некоторые лиановые лешие являются исключительно женскими или мужскими, в то время как многие лешие являются обоими. Биологические особенности цветков леших не обязательно указывают на пол, поскольку природный дух, который населяет лешего, играет сильную роль в определении личности. Лиановые лешие имеют необычные отношения с другими лешими, поскольку в отличие от стандартных леших, лиановые не выращиваются в качестве слуг. Они свободолюбивые и индивидуалистические существа. Считает ли отдельный лиановый леший положение, которое терпят другие лешие, сродни рабству или как нечто большее, похожее на благородную традицию служения могущественному друиду, зависит от мнения и его мировоззрения. В то время как необычно видеть, что лиановый леший берёт себе другого лешего в качестве миньона традиционным способом, нет ничего необычного в том, что лиановый леший берёт на себя опеку над другими лешими, обращаясь с ними почти как с приёмными детьми или сбившимися с пути изгнанниками, нуждающимися в руководстве и защите от тех, кто использует их.","slug":"vineLeshy","society":"Из-за ритуального происхождения лиановые лешие не имеют традиционной семейной структуры. Они завязывают прочные дружеские отношения с теми, кто сопровождает их в исследованиях или помогает им в охране природных территорий. В отличие от большинства леших, лиановые лешие обычно испытывают сильное желание найти того, кто их создал. Они видят в своих создателях друзей и союзников, а не родителей. В то время как большинство леших посвящают себя защите определенной территории в течение длительного периода времени, лиановые лешие гораздо более склонны путешествовать и исследовать, останавливаясь, чтобы ухаживать за множеством разных мест на короткие периоды в течение своей жизни. Лиановые лешие любят рассказывать истории, но уделяют большее внимание значению и содержанию истории, чем деталям, потому что не всегда могут вспомнить детали и потому, что считают многие детали ненужными. История, которая прошла через несколько лиановых леших, вероятно, претерпит значительные изменения в персонажах и окружении, но обычно сохраняет основной посыл.","traits":[{"description":"Лиановые лешие выносливы и проницательны, но иногда забывчивы.","name":"+2 Выносливость, +2 Мудрость, -2 Интеллект"},{"description":"Лиановые лешие - это растения с подтипом леший, но у них отсутствует невосприимчивость к воздействиям на разум, параличу, яду, полиморфу, сну и оглушению, которые обычно дает тип растения, и у них отсутствует невосприимчивость к электричеству и звуку, как обычно бывает у подтипа леших.","name":"Леший (Leshy)"},{"description":"Лиановые лешие - небольшие существа и получают +1 (размер) к КБ, +1 (размер) к броскам атаки, штраф -1 на проверки боевого манёвра и к защите от боевого манёвра и +4 (размер) на проверки Скрытности.","name":"Небольшой размер (Small)"},{"description":"Базовая скорость лиановых леших составляет 20 футов.","name":"Низкая скорость (Slow Speed)"},{"description":"Лиановые лешие могут видеть в темноте на расстоянии до 60 футов.","name":"Ночное зрение (Darkvision)"},{"description":"Лиановые лешие могут видеть вдвое дальше людей в сумерках.","name":"Сумеречное зрение (Low-Light Vision)"},{"description":"Лиановые лешие обладают постоянным псевдозаклинанием бесследный шаг (уровень заклинателя 2-й).","name":"Бесследный шаг (Pass without Trace)"},{"description":"Лиановые лешие могут трансформироваться в лианы подобно заклинанию облик дерева. В таком виде леший выглядит как особенно здоровая лиана небольшого размера. Леший может принять форму растения или вернуться к истинной форме в качестве быстрого действия.","name":"Смена формы (Change Shape)"},{"description":"Лиановые лешие могут говорить с лианами, как если бы они были подвержены постоянному заклинанию разговор с растениями.","name":"Речь растений (Plantspeech)"},{"description":"При убийстве лиановый леший взрывается взрывом плодородной энергии. Все растительные существа в пределах 30 футов от убитого лешего исцеляются на 1d8 пунктов здоровья, и лианы быстро заполняют область. Если местность способна поддерживать лианы, подлесок достаточно густой, чтобы область превратилась в труднопроходимую местность на 24 часа, после чего рост растений снижается до обычного уровня; в противном случае эти растения не оказывает значительного влияния на движения, и увядают и отмирают в течение часа.","name":"Зелёный взрыв (Verdant Burst)"},{"description":"Лиановые лешие получают бонус (народ) +4 на проверки Скрытности в лесах.","name":"Непритязательная листва (Unassuming Foliage)"},{"description":"Лиановые лешие получают бонус (народ) +2 на проверки Лазания.","name":"Лазальщик (Climber)"},{"description":"Лиановые лешие начинают игру, говоря на всеобщем и сильване. Лиановые лешие с высоким показателем Интеллекта могут выбирать из следующего списка: акван, акло, ауран, гномий, гоблинский, подземный, терран или эльфийский.","name":"Языки (Languages)"}]},{"book":"Advanced Race Guide","description":"Вишканья - народ экзотических гуманоидов с ядовитой кровью. Эти изящные гуманоиды, обладающие чуждой красотой, видят мир змеиными глазами из полированного золота. Их гибкая кожа покрыта крошечными чешуйками, часто светло-зеленого цвета, которая иногда имеет узоры, похожие на змеиные. Их нельзя обобщать как добро или зло, но, поскольку они действительно говорят раздвоенными языками, они довольствуются тем, что принимают предлагаемое им золото и оставляют вопросы морали другим.","favoredClass":[{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"}],"kind":"race","nameEn":"Vishkanya","nameRu":"Вишканья","slug":"vishkanya","traits":[{"description":"Вишканья изящны и элегантны, но часто иррациональны.","name":"+2 Ловкость, +2 Харизма, -2 Мудрость"},{"description":"Вишканья - гуманоиды с подтипом вишканья.","name":"Вишканья"},{"description":"Вишканья - существа среднего размера и не имеют бонусов или штрафов из-за своего размера.","name":"Средний размер"},{"description":"Базовая скорость Вишканья составляет 30 футов.","name":"Нормальная скорость"},{"description":"Вишканья могут видеть вдвое дальше людей в условиях тусклого света.","name":"Сумеречное зрение"},{"description":"Вишканья получают бонус народа +2 к проверкам Внимания.","name":"Острые чувства"},{"description":"Вишканья получают бонус народа +2 на проверки Изворотливости и Скрытности.","name":"Гибкость"},{"description":"Вишканья имеет бонус народа на испытания от яда, равный их КЗ.","name":"Сопротивление яду"},{"description":"Вишканья искусны в использовании ядов и никогда не отравляются при использовании или применении яда.","name":"Использование ядов (Poison Use) (Экс)"},{"description":"Количество раз в день, равное модификатору Выносливости (минимум 1/день), вишканья может отравить оружие, которое держит в руках, своей токсичной слюной или кровью (использование крови требует, чтобы вишканья был ранен при использовании этой способности). Применение яда является быстрым действием. Яд Вишканьи (Vishkanya Venom): ранение; Испытание: Стойкости со СЛ 10 + 1/2 КЗ Вишканьи + модификатор его Выносливости; Частота: 1/раунд до 6 раундов; Действие: 1d2 урона Лвк; Лечение: 1 испытание.","name":"Токсичность (Toxic) (Экс)"},{"description":"Вишканья всегда владеют духовой трубкой, кукри и сюрикеном.","name":"Обращение с оружием"},{"description":"Вишканья начинают игру, говоря на Всеобщем и Вишканья. Вишканья с высокими значениями Интеллекта могут выбирать дополнительные языки из следующих: Акло, Драконий, Эльфийский, Гоблинский, Сильван и Подземный.","name":"Языки"}]},{"alignmentAndReligion":"Обычно хаотичное нейтральное.","book":"Bestiary 4","description":"Их происхождение лежит в самом сердце Теневого плана. Сами Ваянги размерами подобны феям и имеют крайне хрупкие конечности и кожу, окраса самой мрачной тени. Они следуют учению известному как «Растворение», что дает им возможность сливаться с тенью.","favoredClass":[{"alias":"witch","description":"Добавьте одно заклинание из списка заклинаний чародея/волшебника, которого нет в списке заклинаний ведьмы, в список известных заклинаний. Это заклинание должно быть, как минимум на 1 уровень ниже самого высокого уровня заклинания, которое может сотворить ведьма, и относиться к подшколе иллюзии (тень) или иметь дескриптор тьма.","name":"Ведьма"},{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"shaman","description":"Добавьте 1 заклинание из списка заклинаний волшебника/чародея, которого нет в списке заклинаний шамана, к списку заклинаний, которые знает шаман. Заклинание должно быть хотя бы на 1 круг меньше максимального круга, который может применять шаман и быть подшколы иллюзии (тень) или иметь дескриптор тьма.","name":"Шаман"}],"kind":"race","nameEn":"Wayang","nameRu":"Ваянг","physicalDescription":"Спиральные узоры покрывают кожу этого гуманойда, а растрепанные клочья черных волос рассеиваются в дым.","slug":"wayang","traits":[{"description":"Ваянги используют уровни в классах - КЗ народа у них нет.","name":""},{"description":"Ваянги проворные и ловкие, довольно умные, но имеют очень странное мировоззрение.","name":"+2 к Ловкости, +2 к Интеллекту, -2 к Мудрости"},{"description":"Ваянги - существа небольшого размера, поэтому они получают +1 (размер) к КБ, +1 (размер) к атакам, -1 к МБМ и ЗБМ и +4 (размер) к проверкам Скрытности.","name":"Небольшой размер"},{"description":"базовая скорость Ваянгов составляет 20 футов.","name":"Медленный"},{"description":"Ваянги видят в темноте на расстоянии 60 футов.","name":"Ночное зрение"},{"description":"Ваянги получают расовый бонус +2 к проверкам Внимания и Скрытности","name":"Наблюдатель"},{"description":"В качестве быстрого действия 1 раз в день Ваянг может выбрать каким образом на него будет влиять проходящая через него энергия, как если бы он был нежитью и получал урон от светлой энергии или исцеление от темной. Эффект длится 1 минуту.","name":"Свет и тьма"},{"description":"К сложности проверки против теневых заклятий Ваянгов добавляется +1. Ваянги с уровнем Харизмы от 11 и выше получают следующие псевдозаклинания: 1/день - призрачный звук, бесследный шаг, чревовещание (УЗ равен уровню персонажа, испытания основаны на Харизме).","name":"Теневая магия"},{"description":"Ваянги имеют расовый бонус сопротивления +2 к заклинаниям школы теней.","name":"Сопротивление тени"},{"description":"Ваянги начинают игру со знанием языков: общий, ваянгский. Ваянги с высоким показателем Интеллекта могут выбрать следующие языки: любой человеческий язык, абиссал, акло, драконий, гоблинский, инфернал.","name":"Языки"}]},{"alignmentAndReligion":"Обычно нейтральное.","book":"Bestiary 4","description":"Эта относительно молодая раса была создана заговорщицкой группой волшебников, которая нуждалась в ловких и умелых прислужниках, способных осуществялть грязные замыслы их творцов. Те маги желали создавать магические машины, для этого они делали своих приспешников маленькими, ловкими и умными. Однажды маги зашли слишком далеко и наделили своих слуг собственной волей. Первое что пришло на ум Вирвудов это вопрос «А с чего вдруг мы вообще должны быть замешаны в чьи-то мелкие интриги?». Последней каплей стало, когда волшебники попытались заставить Вирвудов воевать на их стороне, используя словно марионетки, за что и были убиты своими же творениями. Детища своих создателей похитили их записи содержащих тайну создания им же подобных существ, что позволило им закрепиться как полноценной расе и риск их исчезновения больше не представлял угрозу. Вирвуды скрытны и в каком то смысле ксенофобы, при этом для других могут казаться хладнокровными и расчетливыми, что некоторые могут расценить это как положительные черты. Чистые рационализаторы, лишенные всяких эмоций, для которых сохранение собственной расы - главная цель. Даже те редкие Вирвуды, которые понимают значение эмпатии и альтруизма, смотрят на это как на инструмент способный принести пользу для их собственных целей (естественно сохранение расы). Каждый Вирвуд знает и хранит секрет создания себе подобного, дабы избежать возможности применения другими расами этой тайны для порабощения Вирвудов. Большинство Вирвудов волшебники или плуты. Те немногие, которые подаются в веру воспринимают свои заповеди скорее как жесткий кодекс поведения и следуют протоколу, нежели «зову сердца».","favoredClass":[{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"}],"kind":"race","nameEn":"Wyrwood","nameRu":"Вирвуд","physicalDescription":"Вопреки деревянному строению тела это маленькое, проворное существо движется очень плавно и целенаправленно.","slug":"wyrwood","traits":[{"description":"Вирвуды используют уровни в классах - КЗ народа у них нет.","name":""},{"description":"Конструкция.","name":"Тип"},{"description":"Вирвуды проворные и расчетливые, при этом как конструкции они не имею характеристику Выносливость.","name":"+2 к Ловкости, +2 к Интеллекту, -2 к Харизме"},{"description":"Вирвуды имеют базовую скорость 30 футов.","name":"Обычная скорость"},{"description":"Вирвуды - существа небольшого размера, поэтому они получают +1 (размер) к КБ, +1 (размер) к атакам, -1 к МБМ и ЗБМ и +4 (размер) к проверкам Скрытности.","name":"Небольшой размер"},{"description":"Вирвуды видят в темноте на расстоянии 60 футов.","name":"Ночное зрение"},{"description":"Вирвуды видят в сумерках вдвое дальше людей.","name":"Сумеречное зрение"},{"description":"Вирвуды начинают игру со знанием языков: общий. Вирвуды с высоким показателем Интеллекта могут выбрать следующие языки: драконий, дварфийский, эльфийский, гномий, гоблинский, орочий.","name":"Языки"}]},{"alignmentAndReligion":"Обычно принципиальное нейтральное.","book":"Bestiary 4","description":"Эти создания - результат магических драконьих экспериментов, представляющих собой результат скрещивания кобольда и виверны. Вивараны существа ревностно охраняющие свою территорию, свято чтущие свой род и племя, они не подпустят вас на свои земли без важной на то причины, ну и без должной дани разумеется. Каждый из них печется о своем имуществе и помоги бог тому, кто посмеет что-то украсть у них, ведь кара не заставит себя долго ждать. По большей мере злые или нейтральные по мировоззрению Вивараны в первую очередь озабочены идеей расширения своих земель и накопления богатства. Большинство цивилизованных рас байкотируют Виваран видя в них только неугомонных, тупых, эгоистичных зверей. Хотя те кто готовы по достоинству оценить их принципы могут обрести в них надежных и верных союзников. Те же кто покинули племя и отправились на поиски приключений всегда готовы рисковать ради своих товарищей и готовы подставить свое плечо в трудную минуту.","favoredClass":[{"alias":"legendaryMedium","description":"Добавьте 1/3 к результату любого броска духовного всплеска, который совершает легендарный медиум.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Бонус духа легендарного медиума увеличивается на 1/6.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/6 дополнительной духовной черты.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Увеличьте бонус, получаемый легендарным медиумом от бонуса сеанса на 1/3. Это не увеличивает бонусы, получаемые союзниками от общего сеанса.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Дает 1/2 очка запаса указаний.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"Добавьте 1/5 к бонусу, которые легендарный медиум и его союзники получают через общий сеанс. Это не увеличивает бонус сеанса легендарного медиума.","name":"Легендарный медиум"},{"alias":"legendaryMedium","description":"При использовании Множественного транса, вы можете выбрать 1/6 дополнительной продвинутой духовной способности.","name":"Легендарный медиум"}],"kind":"race","nameEn":"Wyvaran","nameRu":"Виваран","physicalDescription":"Этот драконоподобный гуманойд размахивает своим копьем, раскрывает крылья и обнажает клыки, свирепо рыча.","slug":"wyvaran","traits":[{"description":"Виварны используют уровни в классах - КЗ народа у них нет.","name":""},{"description":"Дракон.","name":"Тип"},{"description":"Вивараны имеют грацию рептилии и сильную волю, но умом природа их не наградила.","name":"+2 к Ловкости, +2 к Мудрости, -2 к Интеллекту"},{"description":"Вивараны имеют базовую скорость 30 футов.","name":"Обычная скорость"},{"description":"Вивараны счастливые обладатели драконоподобных крыльев, что позволяет им летать со скоростью 30 футов со скверной маневренностью.","name":"Полет"},{"description":"Вивараны своим хвостом могут произвести атаку шлепком, которую они могут применять когда производят внеочередную атаку. Данная атака наносит урон 1d8 + модификатор Силы персонажа.","name":"Шлепок хвостом"},{"description":"Вивараны видят в темноте на расстоянии 60 футов.","name":"Ночное зрение"},{"description":"Ванары видят в сумерках вдвое дальше людей.","name":"Сумеречное зрение"},{"description":"Виваран начинают игру со знанием языков: общий и драконий. Виваран с высоким показателем Интеллекта могут выбрать следующие языки: дварфийский, эльфийский, гномий, гоблинский, орочий.","name":"Языки"}]}]};
